window.BOOK={"key":"tuhfamuluk","app":"mutoon","lsk":"mutoon_tuhfamuluk_v1","title":"تحفة الملوك","unitWord":"فقرة","sub":"الفقه الحنفي: تحفة الملوك في فقه مذهب الإمام أبي حنيفة النعمان · زين الدين الرازي (ت ٦٦٦هـ) · ٦٥ بابًا","source":"https://shamela.ws/book/46 (المسبوك على منحة السلوك في شرح تحفة الملوك، د. عبد المحسن القاسم، ط١ ١٤٢٨هـ: the matn of تحفة الملوك printed at the top of each page, edited on four manuscripts of the matn; unvocalized) — wording base · قوبل بـ: https://shamela.ws/book/6173 (تحفة الملوك، اعتنى به د. عبد الله نذير أحمد، دار البشائر الإسلامية ١٤١٧هـ، partly vocalized: word-by-word script collation and source of the harakat) + al-Ayni, منحة السلوك (ed. al-Kubaisi, OpenITI 0855BadrDinCayni.MinhatSuluk.Sham19Y0013784) as arbiter; see tuhfamuluk-sources.md","note":"لفظ المتن من تحقيق د. عبد المحسن القاسم على أربع نسخ خطية للمتن، وقوبل كلمةً كلمةً بسكربت على نشرة دار البشائر (تحقيق د. عبد الله نذير أحمد، الشاملة ٦١٧٣) وعلى ألفاظ المتن في «منحة السلوك» للعيني (ت. الكبيسي)، وأُخذت رواية النشرتين الأخريين حيث اتفقتا عليه (٣٥ موضعًا). لا توجد نسخة مشكولة كاملة: الشكل الجزئي منقول من نشرة دار البشائر (نحو ٤٢٪ من الحروف)، والتفصيل في تقرير المصادر. والطبعات مشكولة جزئيًا (نحو ٤٢٪)، فأكمل الذكاء الاصطناعي باقي الحركات، فإذا شككت بحركة فراجع شيخك.","chapters":[{"id":"tu1","title":"مُقَدِّمَةُ الْمُصَنِّفِ","units":[{"id":"tu1_1","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ١","segs":[["matn","الْحَمْدُ لِلَّهِ، وَسَلَامٌ عَلَى عِبَادِهِ الَّذِينَ اصْطَفَى. هَذَا مُخْتَصَرٌ فِي عِلْمِ الْفِقْهِ جَمَعْتُهُ لِبَعْضِ إِخْوَانِي فِي الدِّينِ بِقَدْرِ مَا وَسِعَهُ وَقْتُهُ."]]},{"id":"tu1_2","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ٢","segs":[["matn","وَاقْتَصَرْتُ فِيهِ عَلَى عَشَرَةِ كُتُبٍ، هِيَ أَهَمُّ كُتُبِ الْفِقْهِ لَهُ، وَأَحَقُّهَا بِالتَّقْدِيمِ. وَهِيَ كِتَابُ الطَّهَارَةِ، وَالصَّلَاةِ، وَالزَّكَاةِ، وَالصَّوْمِ، وَالْحَجِّ."]]},{"id":"tu1_3","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ٣","segs":[["matn","وَالْجِهَادِ وَالصَّيْدِ مَعَ الذَّبَائِحِ وَالْكَرَاهِيَةِ وَالْفَرَائِضِ وَالْكَسْبِ مَعَ الْأَدَبِ. نَفَعَهُ اللَّهُ بِهِ، وَجَعَلَهُ سَبَبًا لِتَرَقِّيهِ إِلَى أَعْلَى مَرَاتِبِ سَعَادَةِ الْآخِرَةِ، وَاللَّهُ الْمُوَفِّقُ."]]}]},{"id":"tu2","title":"كِتَابُ الطَّهَارَةِ","units":[{"id":"tu2_1","label":"كِتَابُ الطَّهَارَةِ · ١","segs":[["matn","الْمَاءُ عَلَى ثَلَاثَةِ أَقْسَامٍ: طَاهِرٌ وَطَهُورٌ. وَهُوَ: الْمَاءُ الْبَاقِي عَلَى أَوْصَافِ خِلْقَتِهِ. وَمِنْهُ: مَا يَقْطُرُ مِنَ الْكَرْمِ وَالْمُتَغَيِّرُ بِطَاهِرٍ، مَا لَمْ يَغْلِبْهُ بِالْأَجْزَاءِ، وَلَمْ يُجَدَّدْ لَهُ اسْمٌ آخَرُ."]]},{"id":"tu2_2","label":"كِتَابُ الطَّهَارَةِ · ٢","segs":[["matn","وَطَاهِرٌ فَقَطْ، وَهُوَ كُلُّ مَاءٍ أُزِيلَ بِهِ حَدَثٌ، أَوْ أُقِيمَتْ بِهِ قُرْبَةٌ. وَنَجِسٌ: وَهُوَ مَاءٌ قَلِيلٌ وَقَعَتْ فِيهِ نَجَاسَةٌ، وَإِنْ لَمْ تُغَيِّرْهُ."]]},{"id":"tu2_3","label":"كِتَابُ الطَّهَارَةِ · ٣","segs":[["matn","وَكَثِيرٌ وَقَعَتْ فِيهِ نَجَاسَةٌ غَيَّرَتْ أَحَدَ أَوْصَافِهِ جَارِيًا، كَانَ أَوْ وَاقِفًا. وَالْكَثِيرُ: عَشْرٌ فِي عَشْرٍ، بِذِرَاعِ الْكِرْبَاسِ، فِي عُمْقٍ لَا تَظْهَرُ الْأَرْضُ بِالْغَرْفِ، وَالْقَلِيلُ مَا دُونَهُ."]]},{"id":"tu2_4","label":"كِتَابُ الطَّهَارَةِ · ٤","segs":[["matn","وَالْجَارِي: مَا يَذْهَبُ بِتِبْنَةٍ وَالْوَاقِفُ: مَا دُونَهُ. وَالنَّجَاسَةُ: كُلُّ خَارِجٍ مِنْ أَحَدِ السَّبِيلَيْنِ مِنَ الْإِنْسَانِ وَغَيْرِهِ، إِلَّا خُرْءَ الْحَمَامِ، وَالْعُصْفُورِ، وَالدَّمُ، وَالْقَيْحُ، وَالصَّدِيدُ،"]]},{"id":"tu2_5","label":"كِتَابُ الطَّهَارَةِ · ٥","segs":[["matn","إِذَا سَالَ إِلَى مَحَلِّ الطَّهَارَةِ إِمَّا لِلْوُضُوءِ وَإِمَّا لِلْغُسْلِ فِي الْجُمْلَةِ، وَالْخَمْرُ، وَالْقَيْءُ مِلْءَ الْفَمِ، وَخُرْءُ مَا لَا يُؤْكَلُ لَحْمُهُ مِنَ الطُّيُورِ، يُنَجِّسُ الْمَاءَ، إِلَّا الثَّوْبَ حَتَّى يَفْحُشَ."]]},{"id":"tu2_6","label":"كِتَابُ الطَّهَارَةِ · ٦","segs":[["matn","وَخُرْءُ الْفَأْرَةِ، وَبَوْلُهُ مَعْفُوٌّ عَنْهُ فِي الطَّعَامِ، وَالثَّوْبِ؛ لَا فِي الْمَاءِ. وَدَمُ الْبَقِّ وَالْبَرَاغِيثِ وَالسَّمَكِ عَفْوٌ. وَشَعْرُ الْمَيْتَةِ، وَكُلُّ جُزْءٍ مِنْهَا لَا حَيَاةَ فِيهِ، طَاهِرٌ."]]},{"id":"tu2_7","label":"كِتَابُ الطَّهَارَةِ · ٧","segs":[["matn","وَشَعْرُ الْخِنْزِيرِ، وَسَائِرُ أَجْزَائِهِ نَجِسٌ، وَرُخِّصَ الْخَرْزُ بِشَعْرِهِ. وَالْفِيلُ طَاهِرٌ. وَكُلُّ إِهَابٍ دُبِغَ فَقَدْ طَهُرَ، إِلَّا جِلْدَ الْخِنْزِيرِ، وَالْآدَمِيِّ."]]},{"id":"tu2_8","label":"كِتَابُ الطَّهَارَةِ · ٨","segs":[["matn","وَسُؤْرُ الْآدَمِيِّ طَاهِرٌ إِلَّا حَالَ شُرْبِهِ الْخَمْرَ. وَسُؤْرُ الْفَرَسِ، وَمَا يُؤْكَلُ لَحْمُهُ طَاهِرٌ. وَسُؤْرُ الْخِنْزِيرِ، وَالْكَلْبِ، وَسِبَاعِ الْبَهَائِمِ، نَجِسٌ."]]},{"id":"tu2_9","label":"كِتَابُ الطَّهَارَةِ · ٩","segs":[["matn","وَسُؤْرُ الْهِرَّةِ، وَالدَّجَاجَةِ الْمُخَلَّاةِ، وَالْإِبِلِ، وَالْبَقَرِ الْجَلَّالَةِ، وَالْحَيَّةِ، وَالْعَقْرَبِ، وَالْفَأْرَةِ، وَسِبَاعِ الطَّيْرِ، مَكْرُوهٌ. وَسُؤْرُ الْبَغْلِ، وَالْحِمَارِ، مَشْكُوكٌ فِي طَهُورِيَّتِهِ؛ فَإِنْ لَمْ يَجِدْ غَيْرَهُ تَوَضَّأَ بِهِ وَتَيَمَّمَ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"tu3","title":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ","units":[{"id":"tu3_1","label":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ · ١","segs":[["matn","فُرُوضُ الْوُضُوءِ: أَرْبَعَةٌ: الْأَوَّلُ: غَسْلُ الْوَجْهِ، وَهُوَ: مِنْ مَنْبِتِ النَّاصِيَةِ، إِلَى أَسْفَلِ الذَّقَنِ طُولًا، وَمِنْ شَحْمَةِ الْأُذُنِ إِلَى شَحْمَةِ الْأُذُنِ عَرْضًا."]]},{"id":"tu3_2","label":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ · ٢","segs":[["matn","وَيَجِبُ غَسْلُ الشَّعْرِ السَّاتِرِ لِلْخَدَّيْنِ وَالذَّقَنِ، وَلَا يَجِبُ غَسْلُ مَا تَحْتَهُ، وَتَحْتَ الشَّارِبِ، وَالْحَاجِبِ، وَمَا نَزَلَ مِنَ اللِّحْيَةِ. وَأَمَّا الْبَيَاضُ الَّذِي بَيْنَ الْعِذَارِ، وَالْأُذُنِ: فَيَجِبُ غَسْلُهُ."]]},{"id":"tu3_3","label":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ · ٣","segs":[["matn","الثَّانِي: غَسْلُ الْيَدَيْنِ مَعَ الْمِرْفَقَيْنِ. وَالثَّالِثُ: مَسْحُ رُبُعِ الرَّأْسِ. الرَّابِعُ: غَسْلُ الرِّجْلَيْنِ مَعَ الْكَعْبَيْنِ. وَالدَّوَاءُ فِي شُقُوقِهِمَا يَصِحُّ مَعَهُ الْوُضُوءُ."]]},{"id":"tu3_4","label":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ · ٤","segs":[["matn","وَسُنَنُهُ عِشْرُونَ: النِّيَّةُ، وَالتَّسْمِيَةُ، وَغَسْلُ الْيَدَيْنِ إِلَى الرُّسْغَيْنِ ثَلَاثًا لِلْقَائِمِ مِنْ نَوْمِهِ، وَالتَّرْتِيبُ، وَالْمُوَالَاةُ، وَالسِّوَاكُ، وَالْمَضْمَضَةُ، وَالِاسْتِنْشَاقُ، وَالْمُبَالَغَةُ فِيهِمَا لِلْمُفْطِرِ، وَالْبِدَايَةُ بِالْمَيَامِنِ،"]]},{"id":"tu3_5","label":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ · ٥","segs":[["matn","وَالْبِدَايَةُ فِي غَسْلِ الْيَدَيْنِ وَالرِّجْلَيْنِ مِنْ رُؤُوسِ الْأَصَابِعِ، وَتَخْلِيلُ اللِّحْيَةِ، وَالْأَصَابِعِ، وَتَحْرِيكُ الْخَاتَمِ الضَّيِّقِ، وَمَسْحُ كُلِّ الرَّأْسِ، وَالْبِدَايَةُ مِنْ مُقَدَّمِهِ، وَمَسْحُ الْأُذُنَيْنِ، وَالرَّقَبَةِ، وَتَثْلِيثُ كُلِّ غَسْلٍ."]]},{"id":"tu3_6","label":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ · ٦","segs":[["matn","وَفُرُوضُ الْغُسْلِ: خَمْسَةٌ، الْمَضْمَضَةُ، وَالِاسْتِنْشَاقُ، وَغَسْلُ سَائِرِ الْبَدَنِ، وَإِيصَالُ الْمَاءِ إِلَى بَاطِنِ السُّرَّةِ، وَإِلَى أَثْنَاءِ شَعْرِ الرَّجُلِ وَإِنْ كَانَ مَضْفُورًا، بِخِلَافِ ضَفَائِرِ الْمَرْأَةِ."]]},{"id":"tu3_7","label":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ · ٧","segs":[["matn","وَسُنَنُهُ: سِتَّةٌ: أَنْ يَبْدَأَ بِغَسْلِ يَدَيْهِ، وَفَرْجِهِ، وَإِزَالَةِ نَجَاسَةِ بَدَنِهِ، ثُمَّ يَتَوَضَّأَ وُضُوءَ الصَّلَاةِ إِلَّا رِجْلَيْهِ إِنْ كَانَ فِي مَجْمَعِ الْغُسَالَةِ،"]]},{"id":"tu3_8","label":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ · ٨","segs":[["matn","ثُمَّ يَغْسِلَ رَأْسَهُ، وَجَسَدَهُ ثَلَاثًا، ثُمَّ يَخْرُجَ مِنْ مَجْمَعِ الْغُسَالَةِ، فَيَغْسِلَ رِجْلَيْهِ، وَغُسْلُ يَوْمِ الْجُمُعَةِ، وَالْعِيدَيْنِ، وَعَرَفَةَ، وَعِنْدَ الْإِحْرَامِ سُنَّةٌ."]]},{"id":"tu3_9","label":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ · ٩","segs":[["matn","وَشَرْطُ السُّنَّةِ: أَنْ يُصَلِّيَ بِهِ الْجُمُعَةَ قَبْلَ أَنْ يُحْدِثَ. وَغُسْلُ مَنْ أَسْلَمَ، أَوْ أَفَاقَ، أَوْ بَلَغَ بِالسِّنِّ: مُسْتَحَبٌّ وَإِنْ بَلَغَ بِالْإِنْزَالِ فَوَاجِبٌ."]]},{"id":"tu3_10","label":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ · ١٠","segs":[["matn","وَغُسْلُ الْجَنَابَةِ، وَالْحَيْضِ، لَا يَسْقُطُ بِالْإِسْلَامِ. وَنَوَاقِضُ الْوُضُوءِ: كُلُّ مَا خَرَجَ مِنَ السَّبِيلَيْنِ، وَالدَّمُ، وَالْقَيْحُ، وَالصَّدِيدُ السَّائِلُ بِغَيْرِ عَصْرٍ إِلَى مَحَلِّ الطَّهَارَةِ فِي الْجُمْلَةِ،"]]},{"id":"tu3_11","label":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ · ١١","segs":[["matn","وَالْقَيْءُ مِلْءَ الْفَمِ، وَالنَّوْمُ مُضْطَجِعًا، أَوْ مُتَّكِئًا، أَوْ مُسْتَنِدًا غَيْرَ مُسْتَقِرٍّ عَلَى الْأَرْضِ، وَغَلَبَةُ الْعَقْلِ بِإِغْمَاءٍ، أَوْ جُنُونٍ، أَوْ سُكْرٍ، وَالْقَهْقَهَةُ فِي كُلِّ صَلَاةٍ ذَاتِ رُكُوعٍ، وَسُجُودٍ."]]},{"id":"tu3_12","label":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ · ١٢","segs":[["matn","وَلَوْ خَرَجَ مِنْ فَمِهِ دَمٌ، إِنْ غَلَبَهُ الرِّيقُ لَوْنًا لَمْ يَنْقُضْ، وَإِنْ غَلَبَ الدَّمُ الرِّيقَ، أَوْ تَسَاوَيَا نَقَضَ. وَمَسُّ الذَّكَرِ لَا يَنْقُضُ، وَلَا لَمْسُ الْمَرْأَةِ، إِلَّا فِي الْمُبَاشَرَةِ الْفَاحِشَةِ."]]},{"id":"tu3_13","label":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ · ١٣","segs":[["matn","وَيُوجِبُ الْغُسْلَ: دَفْقُ الْمَنِيِّ بِشَهْوَةٍ نَائِمًا كَانَ، أَوْ يَقْظَانًا، وَتَغْيِيبُ الْحَشَفَةِ فِي أَحَدِ السَّبِيلَيْنِ مِنَ الْإِنْسَانِ عَلَيْهِمَا، وَالْحَيْضُ وَالنِّفَاسُ."]]},{"id":"tu3_14","label":"فَصْلٌ فِي الْوُضُوءِ وَالْغُسْلِ · ١٤","segs":[["matn","وَلَا يُوجِبُهُ خُرُوجُ الْمَنِيِّ، بِغَيْرِ شَهْوَةٍ. وَلَوِ احْتَلَمَ، وَلَمْ يَرَ بَلَلًا فَلَا غُسْلَ عَلَيْهِ، وَلَوْ رَأَى بَلَلًا مَذْيًا أَوْ مَنِيًّا، وَلَمْ يَذْكُرِ احْتِلَامًا: لَزِمَهُ الْغُسْلُ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"tu4","title":"فَصْلٌ فِي مَسْحِ الْخُفِّ","units":[{"id":"tu4_1","label":"فَصْلٌ فِي مَسْحِ الْخُفِّ · ١","segs":[["matn","يَمْسَحُ الْمُقِيمُ: يَوْمًا، وَلَيْلَةً. وَالْمُسَافِرُ: ثَلَاثَةَ أَيَّامٍ، وَلَيَالِيَهَا. مِنَ الْحَدَثِ خَاصَّةً مِنْ وَقْتِ الْحَدَثِ، بِشَرْطِ لُبْسِهِ عَلَى طَهَارَةٍ كَامِلَةٍ عِنْدَ الْحَدَثِ."]]},{"id":"tu4_2","label":"فَصْلٌ فِي مَسْحِ الْخُفِّ · ٢","segs":[["matn","وَيَجُوزُ الْمَسْحُ عَلَى خُفٍّ، فَوْقَ خُفٍّ، وَعَلَى جُرْمُوقٍ فَوْقَ خُفٍّ، إِنْ لَبِسَهُ قَبْلَ الْحَدَثِ، وَعَلَى جَوْرَبٍ لَا يَشِفُّ، وَيَقِفُ عَلَى السَّاقِ بِلَا رَبْطٍ، وَلَوْ لَمْ يَكُنْ مُجَلَّدًا."]]},{"id":"tu4_3","label":"فَصْلٌ فِي مَسْحِ الْخُفِّ · ٣","segs":[["matn","وَلَوْ سَافَرَ مُقِيمٌ فِي مُدَّتِهِ أَتَمَّ ثَلَاثًا، وَلَوْ أَقَامَ مُسَافِرٌ فِي مُدَّتِهِ لَمْ يَزِدْ عَلَى يَوْمٍ وَلَيْلَةٍ، مِنْ حِينِ مَسَحَ."]]},{"id":"tu4_4","label":"فَصْلٌ فِي مَسْحِ الْخُفِّ · ٤","segs":[["matn","وَيَمْسَحُ ظَاهِرَ الْخُفِّ، وَأَقَلُّهُ: قَدْرُ ثَلَاثَةِ أَصَابِعَ مِنْ أَصَابِعِ الْيَدِ. وَالْخَرْقُ الْكَبِيرُ مَانِعٌ، وَهُوَ قَدْرُ ثَلَاثَةِ أَصَابِعَ مِنْ أَصْغَرِ أَصَابِعِ الرِّجْلِ. وَيَنْقُضُ الْمَسْحَ: كُلُّ مَا يَنْقُضُ الْوُضُوءَ."]]},{"id":"tu4_5","label":"فَصْلٌ فِي مَسْحِ الْخُفِّ · ٥","segs":[["matn","وَيَنْقُضُهُ أَيْضًا: مُضِيُّ الْمُدَّةِ، وَنَزْعُ إِحْدَى الْقَدَمَيْنِ إِلَى سَاقِ الْخُفِّ. وَمَتَى بَطَلَ الْمَسْحُ بِمُضِيِّ الْمُدَّةِ، أَوْ بِالنَّزْعِ، كَفَى غَسْلُ الْقَدَمَيْنِ. وَيَمْسَحُ الْجَبِيرَةَ وَإِنْ شَدَّهَا مُحْدِثًا، وَلَا يَتَوَقَّتُ."]]},{"id":"tu4_6","label":"فَصْلٌ فِي مَسْحِ الْخُفِّ · ٦","segs":[["matn","فَإِنْ سَقَطَتْ عَنْ غَيْرِ بُرْءٍ بَقِيَ الْمَسْحُ، وَإِنْ كَانَ عَنْ بُرْءٍ بَطَلَ، وَإِنْ كَانَ فِي الصَّلَاةِ اسْتَقْبَلَهَا. وَعِصَابَةُ الْفَصْدِ، وَنَحْوُهُ إِنْ ضَرَّهُ حَلُّهَا مَسَحَهَا مَعَ فُرْجَتِهَا."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"tu5","title":"فَصْلٌ فِي التَّيَمُّمِ","units":[{"id":"tu5_1","label":"فَصْلٌ فِي التَّيَمُّمِ · ١","segs":[["matn","وَمَنْ لَمْ يَجِدِ الْمَاءَ خَارِجَ الْمِصْرِ وَبَيْنَهُ وَبَيْنَ الْمِصْرِ مِيلٌ، أَوْ وَجَدَهُ وَهُوَ يَخَافُ الْعَطَشَ، أَوْ كَانَ مَرِيضًا يَخَافُ شِدَّةَ مَرَضِهِ بِحَرَكَتِهِ،"]]},{"id":"tu5_2","label":"فَصْلٌ فِي التَّيَمُّمِ · ٢","segs":[["matn","أَوْ بِاسْتِعْمَالِهِ، أَوْ كَانَ جُنُبًا فِي الْمِصْرِ يَخَافُ شِدَّةَ الْبَرْدِ، أَوْ خَائِفًا مِنْ عَدُوٍّ، أَوْ سَبُعٍ، أَوْ وَجَدَهُ يُبَاعُ بِغَبْنٍ فَاحِشٍ، أَوْ بِثَمَنِ الْمِثْلِ،"]]},{"id":"tu5_3","label":"فَصْلٌ فِي التَّيَمُّمِ · ٣","segs":[["matn","وَهُوَ لَا يَمْلِكُهُ تَيَمَّمَ، وَيَتَيَمَّمُ مَعَ وُجُودِ الْمَاءِ؛ لِخَوْفِ فَوْتِ صَلَاةِ الْعِيدِ، أَوِ الْجِنَازَةِ، وَالْوَلِيُّ غَيْرُهُ لَا لِخَوْفِ فَوْتِ الْجُمُعَةِ، وَالْوَقْتِ."]]},{"id":"tu5_4","label":"فَصْلٌ فِي التَّيَمُّمِ · ٤","segs":[["matn","فَإِنْ كَانَ مَعَ رَفِيقِهِ مَاءٌ طَلَبَهُ قَبْلَ التَّيَمُّمِ؛ اسْتِحْسَانًا. وَلَا يَجِبُ طَلَبُ الْمَاءِ. وَالتَّيَمُّمُ ضَرْبَتَانِ: ضَرْبَةٌ لِلْوَجْهِ: وَضَرْبَةٌ لِلْيَدَيْنِ مَعَ مِرْفَقَيْهِ، وَيُخَلِّلُ أَصَابِعَهُ، وَيَنْزِعُ خَاتَمَهُ."]]},{"id":"tu5_5","label":"فَصْلٌ فِي التَّيَمُّمِ · ٥","segs":[["matn","وَالنِّيَّةُ فِيهِ فَرْضٌ. وَيَجُوزُ بِالصَّعِيدِ الطَّاهِرِ، وَهُوَ: كُلُّ مَا كَانَ مِنْ جِنْسِ الْأَرْضِ كَالتُّرَابِ وَالرَّمْلِ وَالْحَجَرِ وَالنُّورَةِ وَالْكُحْلِ وَالزِّرْنِيخِ. وَالتَّيَمُّمُ لِلْحَدَثِ، وَالْجَنَابَةِ سَوَاءٌ."]]},{"id":"tu5_6","label":"فَصْلٌ فِي التَّيَمُّمِ · ٦","segs":[["matn","وَيَنْقُضُهُ: مَا يَنْقُضُ الْوُضُوءَ، وَرُؤْيَةُ الْمَاءِ أَيْضًا إِذَا قَدَرَ عَلَى اسْتِعْمَالِهِ. وَمَنْ يَرْجُو الْمَاءَ فِي آخِرِ الْوَقْتِ، فَالْأَفْضَلُ لَهُ تَأْخِيرُ الصَّلَاةِ، وَيُصَلِّي بِتَيَمُّمِهِ مَا شَاءَ مِنَ الْفَرَائِضِ وَالنَّوَافِلِ."]]},{"id":"tu5_7","label":"فَصْلٌ فِي التَّيَمُّمِ · ٧","segs":[["matn","وَلَوْ نَسِيَ الْمَاءَ فِي رَحْلِهِ، أَوْ كَانَ بِقُرْبِهِ مَاءٌ لَا يَعْلَمُ بِهِ، فَتَيَمَّمَ، وَصَلَّى أَجْزَأَهُ. وَمَا أُعِدَّ فِي الطَّرِيقِ لِلشُّرْبِ، لَا يَمْنَعُ التَّيَمُّمَ، إِلَّا أَنْ يَعْلَمَ بِكَثْرَتِهِ أَنَّهُ وُضِعَ لِلْوُضُوءِ، وَالشُّرْبِ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"tu6","title":"فَصْلٌ فِي إِزَالَةِ النَّجَاسَةِ","units":[{"id":"tu6_1","label":"فَصْلٌ فِي إِزَالَةِ النَّجَاسَةِ · ١","segs":[["matn","النَّجَاسَةُ الْمَرْئِيَّةُ: تَطْهُرُ بِزَوَالِ عَيْنِهَا بِكُلِّ مَائِعٍ طَاهِرٍ، مُزِيلٍ، كَالْخَلِّ، وَمَاءِ الْوَرْدِ، وَالْمَاءِ الْمُسْتَعْمَلِ. وَالْأَثَرُ الَّذِي يَشُقُّ إِزَالَتُهُ عَفْوٌ."]]},{"id":"tu6_2","label":"فَصْلٌ فِي إِزَالَةِ النَّجَاسَةِ · ٢","segs":[["matn","وَغَيْرُ الْمَرْئِيَّةِ: تَطْهُرُ بِالْغَسْلِ الَّذِي يَغْلِبُ عَلَى الظَّنِّ الزَّوَالُ بِهِ. وَكُلُّ شَيْءٍ صَقِيلٍ، كَالْمِرْآةِ، وَالسَّيْفِ، وَالسِّكِّينِ، وَنَحْوِهَا، يَطْهُرُ بِالْمَسْحِ."]]},{"id":"tu6_3","label":"فَصْلٌ فِي إِزَالَةِ النَّجَاسَةِ · ٣","segs":[["matn","وَالْمَنِيُّ: نَجِسٌ. يَجِبُ غَسْلُهُ رَطْبًا، وَيَكْفِي فَرْكُهُ يَابِسًا. وَلَوْ ذَهَبَ أَثَرُ النَّجَاسَةِ عَنِ الْأَرْضِ بِالشَّمْسِ، جَازَتِ الصَّلَاةُ عَلَى مَكَانِهَا، دُونَ التَّيَمُّمِ مِنْهُ."]]},{"id":"tu6_4","label":"فَصْلٌ فِي إِزَالَةِ النَّجَاسَةِ · ٤","segs":[["matn","وَإِذَا أَصَابَتِ الْخُفَّ، أَوِ النَّعْلَ، نَجَاسَةٌ لَهَا جِرْمٌ، فَجَفَّتْ، فَدَلْكُهُ بِالْأَرْضِ يُطَهِّرُ، بِخِلَافِ الْمَائِعَةِ، وَالثَّوْبِ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"tu7","title":"فَصْلٌ فِي الْبِئْرِ","units":[{"id":"tu7_1","label":"فَصْلٌ فِي الْبِئْرِ · ١","segs":[["matn","النَّجَاسَةُ الْمَائِعَةُ تُنَجِّسُهَا، وَالْجَامِدَةُ، كَالْبَعَرِ، وَالرَّوْثِ، وَالْخِثْيِ، قَلِيلُهَا: عَفْوٌ لَا كَثِيرُهَا، وَهُوَ: مَا يَعُدُّهُ النَّاظِرُ كَثِيرًا. وَالرَّطْبُ، وَالْيَابِسُ، وَالصَّحِيحُ، وَالْمُنْكَسِرُ، سَوَاءٌ."]]},{"id":"tu7_2","label":"فَصْلٌ فِي الْبِئْرِ · ٢","segs":[["matn","فَإِنْ مَاتَتْ فِيهَا عُصْفُورَةٌ تَطْهُرُ بِنَزْحِ عِشْرِينَ دَلْوًا بِدَلْوِهَا بَعْدَ إِخْرَاجِ الْوَاقِعِ. وَفِي الْحَمَامَةِ، وَالدَّجَاجَةِ، وَالْهِرَّةِ، وَنَحْوِهَا: أَرْبَعُونَ."]]},{"id":"tu7_3","label":"فَصْلٌ فِي الْبِئْرِ · ٣","segs":[["matn","وَفِي الْآدَمِيِّ، وَالشَّاةِ، وَنَحْوِهِمَا يُنْزَحُ الْكُلُّ. وَإِنِ انْتَفَخَ الْوَاقِعُ، أَوْ تَفَسَّخَ، نُزِحَ الْكُلُّ مُطْلَقًا، وَإِنْ لَمْ يُمْكِنْ؛ لِنَبْعِ الْمَاءِ، نُزِحَ حَتَّى يَغْلِبَهُمُ الْمَاءُ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"tu8","title":"فَصْلٌ فِي الِاسْتِنْجَاءِ","units":[{"id":"tu8_1","label":"فَصْلٌ فِي الِاسْتِنْجَاءِ · ١","segs":[["matn","وَهُوَ سُنَّةٌ مِنَ الْبَوْلِ، وَالْغَائِطِ، وَنَحْوِهِمَا. بِكُلِّ طَاهِرٍ مُزِيلٍ يَمْسَحُ الْمَحَلَّ، حَتَّى يُنَقِّيَهُ، وَلَا يُسَنُّ الْعَدَدُ. وَالْمَاءُ أَفْضَلُ، فَإِنْ جَاوَزَ الْخَارِجُ الْمَخْرَجَ، تَعَيَّنَ الْمَاءُ. وَيُكْرَهُ بِالْعَظْمِ، وَالرَّوْثِ، وَالْمَطْعُومِ، وَالْيَمِينِ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"tu9","title":"كِتَابُ الصَّلَاةِ","units":[{"id":"tu9_1","label":"كِتَابُ الصَّلَاةِ · ١","segs":[["matn","وَمَنْ أَسْلَمَ، أَوْ أَفَاقَ، أَوْ بَلَغَ، أَوْ طَهُرَتْ، وَقَدْ بَقِيَ مِنَ الْوَقْتِ قَدْرُ تَحْرِيمَةٍ، لَزِمَتْهُ. وَلَوِ ارْتَدَّ، أَوْ جُنَّ، أَوْ حَاضَتْ حِينَئِذٍ لَمْ تَجِبْ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu10","title":"فَصْلٌ فِي الْأَذَانِ","units":[{"id":"tu10_1","label":"فَصْلٌ فِي الْأَذَانِ · ١","segs":[["matn","الْأَذَانُ: سُنَّةٌ، لِلْخَمْسِ، وَالْجُمُعَةِ، فَقَطْ بِغَيْرِ تَرْجِيعٍ. وَيَزِيدُ فِي أَذَانِ الْفَجْرِ بَعْدَ الْفَلَاحِ، الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ، مَرَّتَيْنِ."]]},{"id":"tu10_2","label":"فَصْلٌ فِي الْأَذَانِ · ٢","segs":[["matn","وَالْإِقَامَةُ مِثْلُهُ، بِزِيَادَةِ قَدْ قَامَتِ الصَّلَاةُ، مَرَّتَيْنِ بَعْدَ الْفَلَاحِ، وَيَتَرَسَّلُ الْأَذَانَ، وَيَحْدُرُ الْإِقَامَةَ، وَيَتَوَجَّهُ فِيهِمَا الْقِبْلَةَ، وَيَلْتَفِتُ يَمْنَةً وَيَسْرَةً، وَيَرْفَعُ صَوْتَهُ، وَيُسْتَحَبُّ الْوُضُوءُ فِيهِمَا، وَيُكْرَهَانِ لِلْجُنُبِ، وَيُعَادُ الْأَذَانُ خَاصَّةً، وَيُكْرَهُ إِقَامَةُ الْمُحْدِثِ."]]},{"id":"tu10_3","label":"فَصْلٌ فِي الْأَذَانِ · ٣","segs":[["matn","وَيُؤَذِّنُ لِلْفَائِتَةِ الْأُولَى، وَيُقِيمُ، وَلَهُ الِاكْتِفَاءُ بِالْإِقَامَةِ فِي الْبَاقِي، وَيَجُوزُ إِقَامَةُ غَيْرِ الْمُؤَذِّنِ. وَيُكْرَهُ لِلْمُؤَذِّنِ أَخْذُ الْأُجْرَةِ وَلَا يُؤَذَّنُ لِصَلَاةٍ قَبْلَ الْوَقْتِ، وَيُعَادُ فِيهِ."]]},{"id":"tu10_4","label":"فَصْلٌ فِي الْأَذَانِ · ٤","segs":[["matn","وَيَجِبُ عَلَى سَامِعِ الْأَذَانِ، وَالْإِقَامَةِ مُتَابَعَةُ الْمُؤَذِّنِ، إِلَّا فِي الْحَيْعَلَةِ الْأُولَى، فَيَقُولُ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ، وَفِي الثَّانِيَةِ: مَا شَاءَ اللَّهُ كَانَ، وَمَا لَمْ يَشَأْ لَمْ يَكُنْ، وَعِنْدَ قَوْلِهِ: الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ، صَدَقْتَ، وَبِالْحَقِّ نَطَقْتَ."]]},{"id":"tu10_5","label":"فَصْلٌ فِي الْأَذَانِ · ٥","segs":[["matn","وَلَا يَتَكَلَّمُ سَامِعُهُمَا، وَلَا يَقْرَأُ، وَلَا يُسَلِّمُ، وَلَا يَرُدُّ، وَلَا يَشْتَغِلُ بِعَمَلٍ غَيْرِ الْإِجَابَةِ، وَيَقْطَعُ الْقِرَاءَةَ لَهُمَا."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu11","title":"فَصْلٌ","units":[{"id":"tu11_1","label":"فَصْلٌ · ١","segs":[["matn","وَشُرُوطُ الصَّلَاةِ سِتَّةٌ: الْوَقْتُ، وَالطَّهَارَةُ بِأَنْوَاعِهَا، وَسَتْرُ الْعَوْرَةِ، وَاسْتِقْبَالُ الْقِبْلَةِ، وَالنِّيَّةُ، وَتَكْبِيرَةُ الْإِحْرَامِ. وَأَرْكَانُهَا سِتَّةٌ: الْقِيَامُ، وَالْقِرَاءَةُ، وَالرُّكُوعُ، وَالسُّجُودُ، وَالِانْتِقَالُ مِنْ رُكْنٍ إِلَى رُكْنٍ، وَالْقَعْدَةُ الْأَخِيرَةُ."]]},{"id":"tu11_2","label":"فَصْلٌ · ٢","segs":[["matn","وَوَاجِبَاتُهَا أَحَدَ عَشَرَ: الْفَاتِحَةُ فِي الْأُولَيَيْنِ، وَسُورَةٌ، أَوْ قَدْرُهَا، وَالْجَهْرُ فِي الْجَهْرِيَّةِ لِلْإِمَامِ، وَالْمُخَافَتَةُ فِي السِّرِّيَّةِ مُطْلَقًا، وَالطُّمَأْنِينَةُ فِي الرُّكُوعِ، وَالسُّجُودِ، وَتَرْتِيبُ أَفْعَالِهَا، وَالْقَعْدَةُ الْأُولَى، وَالتَّشَهُّدُ فِي الْقَعْدَتَيْنِ، وَالتَّسْلِيمُ، وَالْقُنُوتُ، وَتَكْبِيرَاتُ الْعِيدَيْنِ."]]},{"id":"tu11_3","label":"فَصْلٌ · ٣","segs":[["matn","وَسُنَنُهَا مَا سِوَى ذَلِكَ مِنْ أَقْوَالِهَا، وَأَفْعَالِهَا الْمَطْلُوبَةِ. الشَّرْطُ الْأَوَّلُ: الْوَقْتُ. وَوَقْتُ الصُّبْحِ مِنْ طُلُوعِ الْفَجْرِ الصَّادِقِ، إِلَى طُلُوعِ الشَّمْسِ."]]},{"id":"tu11_4","label":"فَصْلٌ · ٤","segs":[["matn","وَالظُّهْرِ مِنْ زَوَالِهَا، حَتَّى يَصِيرَ ظِلُّ كُلِّ شَيْءٍ مِثْلَيْهِ، سِوَى فَيْءِ الزَّوَالِ. وَهُوَ أَوَّلُ وَقْتِ الْعَصْرِ، وَآخِرُهُ غُرُوبُهَا. وَهُوَ أَوَّلُ وَقْتِ الْمَغْرِبِ، وَآخِرُهُ غُرُوبُ الشَّفَقِ الْأَبْيَضِ بَعْدَ الْحُمْرَةِ."]]},{"id":"tu11_5","label":"فَصْلٌ · ٥","segs":[["matn","وَهُوَ أَوَّلُ وَقْتِ الْعِشَاءِ، وَآخِرُهُ طُلُوعُ الْفَجْرِ الصَّادِقِ. وَوَقْتُ الْوِتْرِ: وَقْتُ الْعِشَاءِ، وَيَجِبُ تَأْخِيرُهُ عَنْهَا. وَيُسْتَحَبُّ الْإِسْفَارُ بِالْفَجْرِ، إِلَّا لِلْحَاجِّ بِمُزْدَلِفَةَ، فَالتَّغْلِيسُ أَفْضَلُ."]]},{"id":"tu11_6","label":"فَصْلٌ · ٦","segs":[["matn","وَالْإِبْرَادُ بِالظُّهْرِ فِي الصَّيْفِ، وَتَعْجِيلُهَا فِي الشِّتَاءِ، وَتَأْخِيرُ الْعَصْرِ مَا لَمْ يَتَغَيَّرْ قُرْصُ الشَّمْسِ فِي الصَّيْفِ، وَالشِّتَاءِ. وَتَعْجِيلُ الْمَغْرِبِ دَائِمًا."]]},{"id":"tu11_7","label":"فَصْلٌ · ٧","segs":[["matn","وَتَأْخِيرُ الْعِشَاءِ إِلَى ثُلُثِ اللَّيْلِ فِي الشِّتَاءِ، وَتَعْجِيلُهَا فِي الصَّيْفِ. وَفِي يَوْمِ الْغَيْمِ، يُعَجَّلُ الْعَصْرُ، وَالْعِشَاءُ، وَيُؤَخَّرُ الْبَاقِي. وَلَا يُجْمَعُ بَيْنَ صَلَاتَيْنِ فِي وَقْتٍ وَاحِدٍ، إِلَّا بِعَرَفَةَ، وَمُزْدَلِفَةَ."]]},{"id":"tu11_8","label":"فَصْلٌ · ٨","segs":[["matn","وَيُسْتَحَبُّ الْوِتْرُ فِي آخِرِ اللَّيْلِ، إِنْ وَثِقَ بِالِانْتِبَاهِ وَإِلَّا فَأَوَّلَهُ وَوَقْتُ الْجُمُعَةِ وَقْتُ الظُّهْرِ. وَوَقْتُ صَلَاةِ الْعِيدَيْنِ مِنِ ارْتِفَاعِ الشَّمْسِ إِلَى زَوَالِهَا."]]},{"id":"tu11_9","label":"فَصْلٌ · ٩","segs":[["matn","وَأَوْقَاتُ الْكَرَاهِيَةِ، ثَمَانِيَةٌ: ثَلَاثَةٌ يُكْرَهُ فِيهَا كُلُّ صَلَاةٍ، وَسَجْدَةُ التِّلَاوَةِ، وَالسَّهْوِ، عِنْدَ طُلُوعِ الشَّمْسِ، وَاسْتِوَائِهَا، وَغُرُوبِهَا، إِلَّا عَصْرَ يَوْمِهِ، وَوَقْتَانِ يُكْرَهُ فِيهِمَا التَّطَوُّعُ، وَالْمَنْذُورَةُ، وَرَكْعَتَا الطَّوَافِ، وَقَضَاءُ تَطَوُّعٍ إِذَا أَفْسَدَهُ،"]]},{"id":"tu11_10","label":"فَصْلٌ · ١٠","segs":[["matn","وَلَا يُكْرَهُ غَيْرُ ذَلِكَ، وَهُمَا: مَا بَيْنَ طُلُوعِ الْفَجْرِ، إِلَى طُلُوعِ الشَّمْسِ، وَمَا بَعْدَ الْعَصْرِ إِلَى الْغُرُوبِ."]]},{"id":"tu11_11","label":"فَصْلٌ · ١١","segs":[["matn","وَثَلَاثَةُ أَوْقَاتٍ يُكْرَهُ فِيهَا التَّطَوُّعُ فَقَطْ، وَذَلِكَ بَعْدَ الْغُرُوبِ قَبْلَ الْمَغْرِبِ، وَوَقْتَ خُطْبَةِ الْجُمُعَةِ، وَقَبْلَ صَلَاةِ الْعِيدِ. الثَّانِي: الطَّهَارَةُ: طَهَارَةُ الْمُصَلِّي، وَلِبَاسِهِ، وَمَكَانِهِ شَرْطٌ."]]},{"id":"tu11_12","label":"فَصْلٌ · ١٢","segs":[["matn","وَالنَّجَاسَةُ مُخَفَّفَةٌ، وَهِيَ: بَوْلُ الْفَرَسِ، وَمَا يُؤْكَلُ لَحْمُهُ، وَخُرْءُ مَا لَا يُؤْكَلُ لَحْمُهُ مِنَ الطُّيُورِ، وَيَمْنَعُ مِنْهَا قَدْرُ رُبُعِ الْعُضْوِ أَوْ رُبُعِ طَرَفِ الْإِصَابَةِ، كَالذَّيْلِ، وَالدِّخْرِيصِ، وَالْكُمِّ، وَنَحْوِهَا لَا مَا دُونَهُ."]]},{"id":"tu11_13","label":"فَصْلٌ · ١٣","segs":[["matn","وَمُغَلَّظَةٌ، وَهِيَ: بَقِيَّةُ النَّجَاسَةِ. وَوَزْنُ الْمِثْقَالِ: عَفْوٌ فِي ذَاتِ الْجِرْمِ مَعَ الْكَرَاهَةِ. وَقَدْرُ عَرْضِ الْكَفِّ فِي الْمَائِعَةِ، وَمَا زَادَ مَانِعٌ."]]},{"id":"tu11_14","label":"فَصْلٌ · ١٤","segs":[["matn","وَمَحَلُّ الِاسْتِنْجَاءِ: خَارِجٌ عَنِ الْعَفْوِ، وَرَشَاشُ الْبَوْلِ، كَرُؤُوسِ الْإِبَرِ عَفْوٌ. وَلَوْ صَلَّى عَلَى بِسَاطٍ صَغِيرٍ فِي طَرَفِهِ نَجَاسَةٌ، لَا يَصِحُّ."]]},{"id":"tu11_15","label":"فَصْلٌ · ١٥","segs":[["matn","وَلَوْ حَمَلَ الْمُصَلِّي نَافِجَةَ مِسْكٍ، إِنْ كَانَتْ بِحَيْثُ لَوْ أَصَابَهَا الْمَاءُ لَا يُفْسِدُهَا، تَصِحُّ مُطْلَقًا، وَإِنْ كَانَ يُفْسِدُهَا الْمَاءُ تَصِحُّ، بِشَرْطِ كَوْنِهَا مِنْ حَيَوَانٍ مُذَكًّى."]]},{"id":"tu11_16","label":"فَصْلٌ · ١٦","segs":[["matn","وَمَنْ لَمْ يَجِدْ مَا يُزِيلُ بِهِ النَّجَاسَةَ، وَرُبُعُ ثَوْبِهِ طَاهِرٌ، صَلَّى فِيهِ حَتْمًا، وَلَمْ يُعِدْ، وَإِنْ كَانَ الطَّاهِرُ أَقَلَّ مِنَ الرُّبُعِ، يُخَيَّرُ بَيْنَ الصَّلَاةِ، فِيهِ وَبَيْنَ الصَّلَاةِ عَارِيًا وَالْأَوَّلُ أَفْضَلُ."]]},{"id":"tu11_17","label":"فَصْلٌ · ١٧","segs":[["matn","الثَّالِثُ: سَتْرُ الْعَوْرَةِ، وَعَوْرَةُ الرَّجُلِ: مَا بَيْنَ سُرَّتِهِ إِلَى رُكْبَتِهِ، وَالرُّكْبَةُ عَوْرَةٌ، وَالسُّرَّةُ لَا. وَالْحُرَّةُ: جَمِيعُ بَدَنِهَا، وَشَعْرُهَا عَوْرَةٌ، إِلَّا الْوَجْهَ، وَالْكَفَّيْنِ، وَالْقَدَمَيْنِ."]]},{"id":"tu11_18","label":"فَصْلٌ · ١٨","segs":[["matn","وَعَوْرَةُ الْأَمَةِ، مِثْلُ عَوْرَةِ الرَّجُلِ. مَعَ زِيَادَةِ بَطْنِهَا وَظَهْرِهَا. وَالْعَوْرَةُ الْغَلِيظَةُ، وَالْخَفِيفَةُ، سَوَاءٌ. وَمَا دُونَ رُبُعِ الْعُضْوِ، عَفْوٌ. وَالرُّبُعُ مَانِعٌ."]]},{"id":"tu11_19","label":"فَصْلٌ · ١٩","segs":[["matn","وَالسَّاتِرُ الرَّقِيقُ، الَّذِي لَا يَمْنَعُ رُؤْيَةَ الْعَوْرَةِ، لَا يَكْفِي. وَمَنْ فَقَدَ السَّاتِرَ، صَلَّى عُرْيَانًا قَاعِدًا يُومِئُ بِالرُّكُوعِ، وَالسُّجُودِ، أَوْ قَائِمًا يَرْكَعُ، وَيَسْجُدُ. وَالْأَوَّلُ أَفْضَلُ."]]},{"id":"tu11_20","label":"فَصْلٌ · ٢٠","segs":[["matn","الرَّابِعُ: اسْتِقْبَالُ الْقِبْلَةِ. وَفَرْضُهُ عَيْنُ الْكَعْبَةِ لِلْمَكِّيِّ، وَجِهَتُهَا لِغَيْرِهِ. وَمَنِ اشْتَبَهَتْ عَلَيْهِ الْقِبْلَةُ لَا يَتَحَرَّى وَعِنْدَهُ مَنْ يَسْأَلُهُ، وَلَا فِي الصَّحْرَاءِ، وَالسَّمَاءُ مُصْحِيَةٌ."]]},{"id":"tu11_21","label":"فَصْلٌ · ٢١","segs":[["matn","وَإِذَا عَدِمَ الدَّلَائِلَ وَالْمُخْبِرَ فِي الصَّحْرَاءِ، تَحَرَّى، وَصَلَّى، فَلَوْ تَبَيَّنَ الْخَطَأُ فِيهَا بَنَى وَلَوْ تَبَيَّنَ بَعْدَهَا لَا يُعِيدُ. الْخَامِسُ: النِّيَّةُ: وَهِيَ إِرَادَةُ الصَّلَاةِ بِقَلْبِهِ، وَاللَّفْظُ سُنَّةٌ."]]},{"id":"tu11_22","label":"فَصْلٌ · ٢٢","segs":[["matn","وَالْمُقْتَدِي يَنْوِي بِقَلْبِهِ أَصْلَ الصَّلَاةِ، وَمُتَابَعَةَ الْإِمَامِ، أَوِ الِاقْتِدَاءَ بِهِ، وَنَحْوَ ذَلِكَ. وَالْأَحْوَطُ: مُقَارَنَةُ النِّيَّةِ لِلتَّكْبِيرِ، فَإِنْ قَدَّمَهَا عَلَيْهِ صَحَّ، إِنْ لَمْ تَبْطُلْ بِقَاطِعٍ."]]},{"id":"tu11_23","label":"فَصْلٌ · ٢٣","segs":[["matn","السَّادِسُ: تَكْبِيرَةُ الْإِحْرَامِ. وَيَصِحُّ الِافْتِتَاحُ بِالتَّكْبِيرِ، وَالتَّهْلِيلِ، وَالتَّسْمِيَةِ، وَبِكُلِّ اسْمٍ مِنْ أَسْمَاءِ اللَّهِ تَعَالَى، وَبِقَوْلِهِ: اللَّهُمَّ، وَلَا يَصِحُّ بِقَوْلِهِ: اللَّهُمَّ اغْفِرْ لِي."]]},{"id":"tu11_24","label":"فَصْلٌ · ٢٤","segs":[["matn","وَلَوْ أَدْرَكَ الْإِمَامَ رَاكِعًا، فَكَبَّرَ لِلرُّكُوعِ صَارَ مُفْتَتِحًا. وَلَوْ كَبَّرَ قَبْلَ الْإِمَامِ نَاوِيًا الِاقْتِدَاءَ، بَطَلَ أَصْلًا. وَالْأَفْضَلُ: مُقَارَنَةُ الْإِمَامِ فِي التَّكْبِيرِ، وَالتَّأْخِيرُ فِي التَّسْلِيمِ."]]},{"id":"tu11_25","label":"فَصْلٌ · ٢٥","segs":[["matn","وَيَرْفَعُ يَدَيْهِ مُقَارِنًا لِلتَّكْبِيرِ، يُحَاذِي بِإِبْهَامَيْهِ شَحْمَتَيْ أُذُنَيْهِ، وَلَا يُفَرِّجُ أَصَابِعَهُ، وَكَذَا الرَّفْعُ فِي الْقُنُوتِ، وَتَكْبِيرَاتِ الْعِيدَيْنِ الزَّوَائِدِ، وَتَرْفَعُ الْمَرْأَةُ حَذْوَ مَنْكِبَيْهَا، وَلَا يَرْفَعُ يَدَيْهِ فِي غَيْرِ تَكْبِيرَةِ الْإِحْرَامِ."]]},{"id":"tu11_26","label":"فَصْلٌ · ٢٦","segs":[["matn","وَالسُّنَّةُ: قِيَامُ الْإِمَامِ، وَالْقَوْمِ، عِنْدَ قَوْلِ الْمُؤَذِّنِ: حَيَّ عَلَى الصَّلَاةِ. وَيُكَبِّرُ الْإِمَامُ عِنْدَ قَوْلِهِ: قَدْ قَامَتِ الصَّلَاةُ. الْأَرْكَانُ."]]},{"id":"tu11_27","label":"فَصْلٌ · ٢٧","segs":[["matn","أَوَّلُهَا: الْقِيَامُ، وَلَا يَجُوزُ تَرْكُهُ فِي الْفَرْضِ، وَالْوَاجِبِ بِغَيْرِ عُذْرٍ، إِلَّا فِي السَّفِينَةِ الْجَارِيَةِ خَاصَّةً. وَإِذَا كَبَّرَ، وَضَعَ يَمِينَهُ عَلَى يَسَارِهِ، تَحْتَ سُرَّتِهِ."]]},{"id":"tu11_28","label":"فَصْلٌ · ٢٨","segs":[["matn","وَالْمَرْأَةُ تَضَعُ يَدَيْهَا عَلَى صَدْرِهَا ثُمَّ يَقُولُ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَهَ غَيْرُكَ. الثَّانِي: الْقِرَاءَةُ، ثُمَّ يَتَعَوَّذُ إِنْ كَانَ إِمَامًا، أَوْ مُنْفَرِدًا، وَيُسَمِّي."]]},{"id":"tu11_29","label":"فَصْلٌ · ٢٩","segs":[["matn","وَيَقْرَأُ الْفَاتِحَةَ، وَسُورَةً مَعَهَا، أَوْ ثَلَاثَ آيَاتٍ مِنْ أَيِّ سُورَةٍ شَاءَ فِي كُلِّ وَاحِدَةٍ مِنَ الْأَوَّلَتَيْنِ، وَفَرْضُ الْقِرَاءَةِ مُطْلَقُ آيَةٍ. وَوَاجِبَاتُهَا مَا بَيَّنَّا."]]},{"id":"tu11_30","label":"فَصْلٌ · ٣٠","segs":[["matn","وَإِذَا قَالَ الْإِمَامُ: وَلَا الضَّالِّينَ، أَمَّنَ هُوَ، وَالْقَوْمُ سِرًّا. وَالْفَاتِحَةُ وَحْدَهَا فِي الْأُخْرَيَيْنِ سُنَّةٌ، وَلَوْ سَبَّحَ فِيهِمَا جَازَ، وَلَوْ سَكَتَ كُرِهَ، وَالْقِرَاءَةُ وَاجِبَةٌ فِي كُلِّ رَكَعَاتِ النَّفْلِ، وَالْوِتْرِ."]]},{"id":"tu11_31","label":"فَصْلٌ · ٣١","segs":[["matn","وَيَجْهَرُ الْإِمَامُ حَتْمًا فِي الْفَجْرِ وَالْأُولَيَيْنِ مِنَ الْمَغْرِبِ، وَالْعِشَاءِ. وَيُخَيَّرُ الْمُنْفَرِدُ، وَيُخْفِيَانِ فِي الْبَاقِي حَتْمًا. وَيَجْهَرُ فِي الْجُمُعَةِ، وَالْعِيدَيْنِ، وَفِي النَّفْلِ يُخْفِي نَهَارًا، وَيُخَيَّرُ لَيْلًا."]]},{"id":"tu11_32","label":"فَصْلٌ · ٣٢","segs":[["matn","وَيُكْرَهُ تَخْصِيصُ سُورَةٍ بِصَلَاةٍ، إِلَّا إِذَا كَانَ أَيْسَرَ عَلَيْهِ، أَوِ اتَّبَعَ فِيهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. مُعْتَقِدًا لِلتَّسْوِيَةِ. وَلَا يَقْرَأُ الْمَأْمُومُ خَلْفَ الْإِمَامِ."]]},{"id":"tu11_33","label":"فَصْلٌ · ٣٣","segs":[["matn","الثَّالِثُ: الرُّكُوعُ: فَإِذَا فَرَغَ مِنَ الْقِرَاءَةِ كَبَّرَ وَرَكَعَ. وَقَالَ: سُبْحَانَ رَبِّيَ الْعَظِيمِ ثَلَاثًا، وَهُوَ أَدْنَى الْكَمَالِ، وَإِنْ سَبَّحَ مَرَّةً كُرِهَ."]]},{"id":"tu11_34","label":"فَصْلٌ · ٣٤","segs":[["matn","فَإِذَا اطْمَأَنَّ رَاكِعًا قَامَ، وَقَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، لَا غَيْرُ، وَيَقُولُ الْقَوْمُ: رَبَّنَا لَكَ الْحَمْدُ، وَالْمُنْفَرِدُ يَجْمَعُ بَيْنَهُمَا."]]},{"id":"tu11_35","label":"فَصْلٌ · ٣٥","segs":[["matn","الرَّابِعُ: السُّجُودُ: فَإِذَا اطْمَأَنَّ قَائِمًا كَبَّرَ، وَسَجَدَ، وَقَالَ: سُبْحَانَ رَبِّيَ الْأَعْلَى ثَلَاثًا، ثُمَّ يَرْفَعُ رَأْسَهُ مُكَبِّرًا، وَيَقْعُدُ، فَإِذَا اطْمَأَنَّ قَاعِدًا كَبَّرَ، وَسَجَدَ ثَانِيَةً كَالْأُولَى."]]},{"id":"tu11_36","label":"فَصْلٌ · ٣٦","segs":[["matn","وَيَجُوزُ سُجُودُهُ عَلَى كَوْرِ عِمَامَتِهِ، وَطَرَفِ ثَوْبِهِ. الْخَامِسُ: الِانْتِقَالُ مِنْ رُكْنٍ إِلَى رُكْنٍ. السَّادِسُ: الْقَعْدَةُ الْأَخِيرَةُ قَدْرَ التَّشَهُّدِ الْأَوَّلِ، وَإِذَا قَرَأَ التَّشَهُّدَ يُشِيرُ بِمُسَبِّحَتِهِ عِنْدَ كَلِمَةِ التَّوْحِيدِ. فِي الْأَصَحِّ."]]},{"id":"tu11_37","label":"فَصْلٌ · ٣٧","segs":[["matn","وَلَا يَزِيدُ فِي الْقَعْدَةِ الْأُولَى عَلَى قَوْلِهِ: وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ. وَيَزِيدُ فِي الثَّانِيَةِ: الصَّلَاةَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى آلِهِ."]]},{"id":"tu11_38","label":"فَصْلٌ · ٣٨","segs":[["matn","وَيَدْعُو مَا شَاءَ مِنَ الدُّعَاءِ، وَالسُّؤَالِ كُلَّ مَا لَا يُعْطِيهِ إِلَّا اللَّهُ تَعَالَى، كَالرَّحْمَةِ، وَالْمَغْفِرَةِ، وَنَحْوِهِمَا."]]},{"id":"tu11_39","label":"فَصْلٌ · ٣٩","segs":[["matn","ثُمَّ يُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ، وَيَنْوِي بِكُلِّ تَسْلِيمَةٍ مَنْ فِي تِلْكَ الْجِهَةِ مِنَ الْمَلَائِكَةِ، وَالْحَاضِرِينَ. وَالْمُنْفَرِدُ يَنْوِي الْمَلَائِكَةَ فَقَطْ، وَالْمَأْمُومُ يَنْوِي إِمَامَهُ فِي أَيِّ جِهَةٍ كَانَ، فَإِنْ كَانَ بِحِذَائِهِ نَوَاهُ فِيهِمَا."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu12","title":"فَصْلٌ فِي السُّنَنِ الرَّوَاتِبِ وَغَيْرِهَا","units":[{"id":"tu12_1","label":"فَصْلٌ فِي السُّنَنِ الرَّوَاتِبِ وَغَيْرِهَا · ١","segs":[["matn","وَهِيَ: رَكْعَتَانِ قَبْلَ الْفَجْرِ، وَأَرْبَعٌ قَبْلَ الظُّهْرِ، وَرَكْعَتَانِ بَعْدَهَا، وَأَرْبَعٌ قَبْلَ الْعَصْرِ أَوْ رَكْعَتَانِ، وَرَكْعَتَانِ بَعْدَ الْمَغْرِبِ، وَأَرْبَعٌ قَبْلَ الْعِشَاءِ، وَبَعْدَهَا أَرْبَعٌ أَوْ رَكْعَتَانِ، وَأَرْبَعٌ قَبْلَ الْجُمُعَةِ، وَأَرْبَعٌ بَعْدَهَا."]]},{"id":"tu12_2","label":"فَصْلٌ فِي السُّنَنِ الرَّوَاتِبِ وَغَيْرِهَا · ٢","segs":[["matn","وَالسُّنَّةُ لَا تُقْضَى إِلَّا سُنَّةَ الْفَجْرِ إِذَا فَاتَتْ مَعَ الْفَجْرِ، وَيَقْضِيهَا قَبْلَ الزَّوَالِ، وَسُنَّةُ الظُّهْرِ أَيْضًا يَقْضِيهَا فِي وَقْتِهَا، وَيُؤَخِّرُهَا عَنِ الرَّكْعَتَيْنِ."]]},{"id":"tu12_3","label":"فَصْلٌ فِي السُّنَنِ الرَّوَاتِبِ وَغَيْرِهَا · ٣","segs":[["matn","وَالتَّطَوُّعُ بِالنَّهَارِ: رَكْعَتَانِ بِتَسْلِيمَةٍ أَوْ أَرْبَعٌ، وَبِاللَّيْلِ رَكْعَتَانِ، أَوْ أَرْبَعٌ، أَوْ سِتٌّ، أَوْ ثَمَانٍ، وَتُكْرَهُ الزِّيَادَةُ عَلَى ذَلِكَ فِيهِمَا، وَالْأَرْبَعُ أَفْضَلُ فِيهِمَا."]]},{"id":"tu12_4","label":"فَصْلٌ فِي السُّنَنِ الرَّوَاتِبِ وَغَيْرِهَا · ٤","segs":[["matn","وَالْأَفْضَلُ فِي السُّنَنِ، وَالنَّوَافِلِ، الْمَنْزِلُ. وَيَتَطَوَّعُ قَاعِدًا بِغَيْرِ عُذْرٍ. إِلَّا سُنَّةَ الْفَجْرِ، وَلَوْ شَرَعَ قَاعِدًا وَأَتَمَّ قَائِمًا، أَوْ بِالْعَكْسِ صَحَّ، وَلَوْ شَرَعَ رَاكِبًا، ثُمَّ نَزَلَ بَنَى، وَفِي عَكْسِهِ يَسْتَقْبِلُ."]]},{"id":"tu12_5","label":"فَصْلٌ فِي السُّنَنِ الرَّوَاتِبِ وَغَيْرِهَا · ٥","segs":[["matn","وَيُكْرَهُ التَّطَوُّعُ بِجَمَاعَةٍ إِلَّا التَّرَاوِيحَ، وَمَنْ تَطَوَّعَ بِصَلَاةٍ، أَوْ صَوْمٍ، لَزِمَهُ إِتْمَامُهُ، وَقَضَاؤُهُ إِنْ أَفْسَدَهُ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu13","title":"فَصْلٌ فِي التَّرَاوِيحِ","units":[{"id":"tu13_1","label":"فَصْلٌ فِي التَّرَاوِيحِ · ١","segs":[["matn","وَهِيَ سُنَّةٌ مُؤَكَّدَةٌ. خَمْسُ تَرْوِيحَاتٍ، كُلُّ تَرْوِيحَةٍ تَسْلِيمَتَانِ، وَيَجْلِسُ بَيْنَ كُلِّ تَرْوِيحَتَيْنِ، مِقْدَارَ تَرْوِيحَةٍ، وَكَذَا بَيْنَ الْخَامِسَةِ وَالْوِتْرِ."]]},{"id":"tu13_2","label":"فَصْلٌ فِي التَّرَاوِيحِ · ٢","segs":[["matn","وَلَا يَجْلِسُ بَعْدَ التَّسْلِيمَةِ الْخَامِسَةِ فِي الْأَصَحِّ، ثُمَّ يُوتِرُ بِهِمْ. وَسُنَّتُهَا: الْخَتْمُ. فِي الشَّهْرِ، أَوْ فِي كُلِّ رَكْعَةٍ عَشْرُ آيَاتٍ."]]},{"id":"tu13_3","label":"فَصْلٌ فِي التَّرَاوِيحِ · ٣","segs":[["matn","وَالْجَمَاعَةُ فِيهَا سُنَّةٌ عَلَى الْكِفَايَةِ. وَيَتْرُكُ الْإِمَامُ الدُّعَاءَ بَعْدَ التَّشَهُّدِ إِنْ عَلِمَ مَلَلَ الْقَوْمِ. وَوَقْتُهَا: بَعْدَ أَدَاءِ الْعِشَاءِ إِلَى طُلُوعِ الْفَجْرِ، قَبْلَ الْوِتْرِ، وَبَعْدَهُ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu14","title":"فَصْلٌ فِي الْوِتْرِ","units":[{"id":"tu14_1","label":"فَصْلٌ فِي الْوِتْرِ · ١","segs":[["matn","وَهُوَ وَاجِبٌ. ثَلَاثُ رَكَعَاتٍ مُتَّصِلَةٍ، يَقْنُتُ فِي الثَّالِثَةِ سِرًّا قَبْلَ الرُّكُوعِ، كُلَّ السَّنَةِ، وَلَا يَقْنُتُ فِي الْفَجْرِ، فَإِنْ قَنَتَ إِمَامُهُ فِيهِ سَكَتَ هُوَ قَائِمًا، فِي الْأَصَحِّ."]]},{"id":"tu14_2","label":"فَصْلٌ فِي الْوِتْرِ · ٢","segs":[["matn","وَلَوْ فَاتَ الْوِتْرُ يُقْضَى، وَلَا يَجُوزُ قَاعِدًا، وَلَا رَاكِبًا بِغَيْرِ عُذْرٍ، وَلَيْسَ فِيهِ دُعَاءٌ مُعَيَّنٌ، كَذَا فِي \"الْمُحِيطِ\"، وَفِي \"جَامِعِ الْأُصُولِ\" عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ،"]]},{"id":"tu14_3","label":"فَصْلٌ فِي الْوِتْرِ · ٣","segs":[["matn","أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي وِتْرِهِ: \"اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ\"."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu15","title":"فَصْلٌ","units":[{"id":"tu15_1","label":"فَصْلٌ · ١","segs":[["matn","يُسْتَحَبُّ أَنْ يَكُونَ نَظَرُ الْمُصَلِّي فِي قِيَامِهِ إِلَى مَوْضِعِ سُجُودِهِ، وَفِي رُكُوعِهِ إِلَى أَصَابِعِ رِجْلَيْهِ، وَفِي سُجُودِهِ إِلَى طَرَفِ أَنْفِهِ، وَفِي قُعُودِهِ إِلَى حِجْرِهِ وَلَا يَلْتَفِتُ،"]]},{"id":"tu15_2","label":"فَصْلٌ · ٢","segs":[["matn","وَلَا يَعْبَثُ بِثَوْبِهِ وَعُضْوِهِ، وَيُكْرَهُ تَغْمِيضُ عَيْنَيْهِ، وَيُكْرَهُ سَبْقُهُ الْإِمَامَ بِالْأَفْعَالِ، وَعَدُّ الْآيِ، وَالتَّسْبِيحِ، وَحَمْلُ شَيْءٍ فِي يَدِهِ، أَوْ فَمِهِ."]]},{"id":"tu15_3","label":"فَصْلٌ · ٣","segs":[["matn","وَتَطْوِيلُ الْإِمَامِ الرُّكُوعَ لِدَاخِلٍ يَعْرِفُهُ، وَيُكْرَهُ افْتِتَاحُ الصَّلَاةِ وَبِهِ حَاجَةٌ إِلَى خَلَاءٍ وَتُكْرَهُ الصَّلَاةُ خَلْفَ الصَّفِّ وَحْدَهُ مَهْمَا وَجَدَ فُرْجَةً."]]},{"id":"tu15_4","label":"فَصْلٌ · ٤","segs":[["matn","وَلَوْ صَلَّى فِي مَكَانٍ طَاهِرٍ مِنَ الْحَمَّامِ، وَلَا صُورَةَ فِيهِ لَا يُكْرَهُ. وَتُكْرَهُ الْقِرَاءَةُ فِي الْحَمَّامِ جَهْرًا لَا سِرًّا، وَتُكْرَهُ صُورَةُ ذِي الرُّوحِ فِي كُلِّ جِهَاتِ الْمُصَلِّي."]]},{"id":"tu15_5","label":"فَصْلٌ · ٥","segs":[["matn","إِلَّا مَمْحُوَّةَ الرَّأْسِ، أَوِ الصَّغِيرَةَ جِدًّا، وَلَوِ اسْتَقْبَلَ تَنُّورًا يَتَّقِدُ، أَوْ كَانُونًا فِيهِ نَارٌ يُكْرَهُ، بِخِلَافِ الشَّمْعِ، وَالسِّرَاجِ، وَالْمُصْحَفِ، وَالسَّيْفِ، وَنَحْوِهَا."]]},{"id":"tu15_6","label":"فَصْلٌ · ٦","segs":[["matn","وَالْعَمَلُ الْكَثِيرُ يَقْطَعُ الصَّلَاةَ، وَهُوَ مَا لَا يُوجَدُ إِلَّا بِالْيَدَيْنِ، وَقِيلَ: هُوَ مَا يَجْزِمُ النَّاظِرُ إِلَيْهِ أَنَّهُ لَيْسَ فِي الصَّلَاةِ، وَهُوَ الْمُخْتَارُ."]]},{"id":"tu15_7","label":"فَصْلٌ · ٧","segs":[["matn","وَمَنْ صَلَّى فِي الصَّحْرَاءِ، نَصَبَ بَيْنَ يَدَيْهِ سُتْرَةً، قَدْرَ ذِرَاعٍ فَصَاعِدًا فِي غِلَظِ الْأُصْبُعِ فَمَا زَادَ وَيَقْرُبُ مِنْهَا، وَيَجْعَلُهَا بِحِذَاءِ أَحَدِ حَاجِبَيْهِ، وَلَا عِبْرَةَ بِالْإِلْقَاءِ، وَلَا بِالْخَطِّ."]]},{"id":"tu15_8","label":"فَصْلٌ · ٨","segs":[["matn","وَيَأْثَمُ الْمَارُّ فِي مَوْضِعِ سُجُودِهِ فِي الصَّحْرَاءِ، وَالْمَسْجِدِ الْجَامِعِ، وَيَدْرَأُ الْمَارَّ إِنْ لَمْ يَكُنْ لَهُ سُتْرَةٌ، أَوْ مَرَّ بَيْنَهُ وَبَيْنَهَا بِإِشَارَةٍ، أَوْ تَسْبِيحٍ، وَلَا يَدْرَأُ بِهِمَا."]]},{"id":"tu15_9","label":"فَصْلٌ · ٩","segs":[["matn","وَإِنْ تَنَحْنَحَ بِغَيْرِ عُذْرٍ فَحَصَلَتْ بِهِ حُرُوفٌ بَطَلَتْ، وَإِنْ كَانَ بِعُذْرٍ فَلَا. كَالْعُطَاسِ، وَالْجُشَاءِ، وَلَوْ حَصَلَتْ بِهِمَا حُرُوفٌ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu16","title":"فَصْلٌ فِي الْجَمَاعَةِ","units":[{"id":"tu16_1","label":"فَصْلٌ فِي الْجَمَاعَةِ · ١","segs":[["matn","هِيَ: سُنَّةٌ مُؤَكَّدَةٌ، وَتَخْفِيفُهَا مَعَ الْإِتْمَامِ سُنَّةٌ ثَانِيَةٌ. وَأَقَلُّهَا فِي غَيْرِ الْجُمُعَةِ وَاحِدٌ مَعَ الْإِمَامِ، وَلَوْ كَانَ امْرَأَةً، أَوْ صَبِيًّا."]]},{"id":"tu16_2","label":"فَصْلٌ فِي الْجَمَاعَةِ · ٢","segs":[["matn","وَالْأَوْلَى بِالْإِمَامَةِ: الْأَفْقَهُ، ثُمَّ الْأَقْرَأُ، ثُمَّ الْأَوْرَعُ، ثُمَّ الْأَكْبَرُ سِنًّا، ثُمَّ الْأَحْسَنُ خُلُقًا، ثُمَّ الْأَشْرَفُ نَسَبًا، ثُمَّ الْأَصْبَحُ وَجْهًا."]]},{"id":"tu16_3","label":"فَصْلٌ فِي الْجَمَاعَةِ · ٣","segs":[["matn","وَمَنْ أَمَّ وَاحِدًا أَقَامَهُ عَنْ يَمِينِهِ مُقَارِنًا لَهُ، وَإِنْ أَمَّ اثْنَيْنِ تَقَدَّمَ عَلَيْهِمَا، وَمَنْ تَقَدَّمَ عَلَى إِمَامِهِ عِنْدَ اقْتِدَائِهِ لَمْ يَصِحَّ اقْتِدَاؤُهُ، وَإِنْ تَقَدَّمَ عَلَيْهِ بَعْدَ اقْتِدَائِهِ فَسَدَتْ صَلَاتُهُ."]]},{"id":"tu16_4","label":"فَصْلٌ فِي الْجَمَاعَةِ · ٤","segs":[["matn","وَلَا يَصِحُّ اقْتِدَاءُ الرَّجُلِ بِالْمَرْأَةِ، وَلَا بِالصَّبِيِّ مُطْلَقًا، وَيَصِحُّ اقْتِدَاءُ الصَّبِيِّ بِالصَّبِيِّ. وَيَصُفُّ الرِّجَالُ، ثُمَّ الصِّبْيَانُ، ثُمَّ الْخُنَاثَى، ثُمَّ النِّسَاءُ."]]},{"id":"tu16_5","label":"فَصْلٌ فِي الْجَمَاعَةِ · ٥","segs":[["matn","وَيُكْرَهُ لِلنِّسَاءِ الشَّوَابِّ حُضُورُ الْجَمَاعَةِ مُطْلَقًا، وَيُبَاحُ لِلْعَجَائِزِ الْخُرُوجُ فِي الْعِيدَيْنِ، وَالْجُمُعَةِ، وَالْفَجْرِ، وَالْمَغْرِبِ، وَالْعِشَاءِ. وَلَوْ ظَهَرَ حَدَثُ الْإِمَامِ أَعَادَ الْمَأْمُومُ. وَمَتَى كَانَ بَيْنَ الْإِمَامِ وَالْمَأْمُومِ حَائِلٌ يَشْتَبِهُ عَلَيْهِ مَنَعَ الصِّحَّةَ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu17","title":"فَصْلٌ فِي الْجُمُعَةِ","units":[{"id":"tu17_1","label":"فَصْلٌ فِي الْجُمُعَةِ · ١","segs":[["matn","لَا تَصِحُّ الْجُمُعَةُ إِلَّا فِي مِصْرٍ جَامِعٍ، أَوْ فِي فِنَائِهِ، وَهُوَ: كُلُّ مَوْضِعٍ لَهُ أَمِيرٌ، وَقَاضٍ يُنَفِّذُ الْأَحْكَامَ، وَيُقِيمُ الْحُدُودَ، وَلَا يُقِيمُهَا إِلَّا السُّلْطَانُ، أَوْ نَائِبُهُ."]]},{"id":"tu17_2","label":"فَصْلٌ فِي الْجُمُعَةِ · ٢","segs":[["matn","وَيَخْطُبُ قَبْلَهَا خُطْبَتَيْنِ خَفِيفَتَيْنِ، وَلَوْ ذَكَرَ اللَّهَ تَعَالَى بَدَلَ الْخُطْبَةِ صَحَّ، وَشَرْطُهَا: ثَلَاثَةٌ غَيْرُ الْإِمَامِ."]]},{"id":"tu17_3","label":"فَصْلٌ فِي الْجُمُعَةِ · ٣","segs":[["matn","وَلَا جُمُعَةَ عَلَى مُسَافِرٍ، وَامْرَأَةٍ، وَعَبْدٍ، وَأَعْمَى، وَإِنْ صَلَّوْهَا كَفَتْهُمْ، وَتَصِحُّ إِمَامَتُهُمْ فِيهَا، إِلَّا الْمَرْأَةَ، وَتَحْصُلُ بِهِمُ الْجَمَاعَةُ أَيْضًا."]]},{"id":"tu17_4","label":"فَصْلٌ فِي الْجُمُعَةِ · ٤","segs":[["matn","وَمَنْ صَلَّى الظُّهْرَ بِجَمَاعَةٍ يَوْمَ الْجُمُعَةِ فِي مَنْزِلِهِ بِغَيْرِ عُذْرٍ كُرِهَ، وَأَجْزَأَهُ، وَيُكْرَهُ لِلْمَعْذُورِينَ، وَالْمَحْبُوسِينَ، الظُّهْرُ بِجَمَاعَةٍ يَوْمَ الْجُمُعَةِ."]]},{"id":"tu17_5","label":"فَصْلٌ فِي الْجُمُعَةِ · ٥","segs":[["matn","وَمَنْ أَدْرَكَ الْإِمَامَ فِي التَّشَهُّدِ، أَوْ سُجُودِ السَّهْوِ، أَتَمَّ الْجُمُعَةَ، وَبِالْأَذَانِ الْأَوَّلِ يَحْرُمُ الْبَيْعُ، وَيَجِبُ السَّعْيُ عَلَى مَنْ يَسْمَعُ النِّدَاءَ فَقَطْ."]]},{"id":"tu17_6","label":"فَصْلٌ فِي الْجُمُعَةِ · ٦","segs":[["matn","وَإِذَا خَرَجَ الْإِمَامُ لِلْخُطْبَةِ، تَرَكَ النَّاسُ الصَّلَاةَ، وَالْكَلَامَ حَتَّى يُصَلُّوا، فَإِذَا خَطَبَ وَجَبَ السَّمَاعُ وَالسُّكُوتُ، عَلَى الْقَرِيبِ وَالْبَعِيدِ. وَإِذَا قَرَأَ ﴿يَاأَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ﴾. يُصَلِّي السَّامِعُ فِي نَفْسِهِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu18","title":"فَصْلٌ فِي الْعِيدَيْنِ","units":[{"id":"tu18_1","label":"فَصْلٌ فِي الْعِيدَيْنِ · ١","segs":[["matn","تَجِبُ صَلَاةُ الْعِيدَيْنِ، عَلَى كُلِّ مَنْ تَجِبُ عَلَيْهِ صَلَاةُ الْجُمُعَةِ. وَيُسْتَحَبُّ يَوْمَ الْفِطْرِ أَنْ يَطْعَمَ الْإِنْسَانُ قَبْلَ الصَّلَاةِ، وَفِي الْأَضْحَى بَعْدَهَا، وَيَغْتَسِلَ فِيهِمَا، وَيَتَطَيَّبَ، وَيَلْبَسَ أَحْسَنَ ثِيَابِهِ."]]},{"id":"tu18_2","label":"فَصْلٌ فِي الْعِيدَيْنِ · ٢","segs":[["matn","وَيَتَوَجَّهَ إِلَى الْمُصَلَّى وَهُوَ غَيْرُ مُكَبِّرٍ جَهْرًا، بِخِلَافِ الْأَضْحَى، فَإِنَّهُ يُكَبِّرُ فِيهِ جَهْرًا طُولَ الطَّرِيقِ. وَصَلَاةُ الْأَضْحَى كَالْفِطْرِ، وَيُسْتَحَبُّ تَعْجِيلُهَا."]]},{"id":"tu18_3","label":"فَصْلٌ فِي الْعِيدَيْنِ · ٣","segs":[["matn","وَالْوُقُوفُ يَوْمَ عَرَفَةَ فِي مَوْضِعٍ آخَرَ، تَشَبُّهًا بِأَهْلِ عَرَفَةَ بِدْعَةٌ. وَتَكْبِيرُ التَّشْرِيقِ: أَوَّلُهُ بَعْدَ الْفَجْرِ مِنْ يَوْمِ عَرَفَةَ، وَآخِرُهُ: بَعْدَ عَصْرِ يَوْمِ النَّحْرِ."]]},{"id":"tu18_4","label":"فَصْلٌ فِي الْعِيدَيْنِ · ٤","segs":[["matn","وَصِفَتُهُ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ وَلِلَّهِ الْحَمْدُ، مَرَّةً وَاحِدَةً بَعْدَ الْفَرْضِ."]]},{"id":"tu18_5","label":"فَصْلٌ فِي الْعِيدَيْنِ · ٥","segs":[["matn","وَإِنَّمَا يَجِبُ عَلَى كُلِّ مُقِيمٍ مُصَلٍّ فِي جَمَاعَةٍ مُسْتَحَبَّةٍ لَا غَيْرُ، وَلَا يُكَبِّرُ بَعْدَ الْوِتْرِ، وَلَا صَلَاةِ الْعِيدِ، وَيُكَبِّرُ بَعْدَ الْجُمُعَةِ، فَإِنْ تَرَكَ الْإِمَامُ التَّكْبِيرَ كَبَّرَ الْمَأْمُومُ، وَيُسْتَحَبُّ اخْتِلَافُ الطَّرِيقِ فِي صَلَاةِ الْعِيدِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu19","title":"فَصْلٌ فِي صَلَاةِ الْمُسَافِرِ","units":[{"id":"tu19_1","label":"فَصْلٌ فِي صَلَاةِ الْمُسَافِرِ · ١","segs":[["matn","السَّفَرُ الْمُرَخِّصُ لِلْمُطِيعِ وَالْعَاصِي، مُقَدَّرٌ بِثَلَاثَةِ أَيَّامٍ بِسَيْرِ الْإِبِلِ، وَمَشْيِ الْأَقْدَامِ. وَفَرْضُ الْمُسَافِرِ فِي كُلِّ رُبَاعِيَّةٍ رَكْعَتَانِ."]]},{"id":"tu19_2","label":"فَصْلٌ فِي صَلَاةِ الْمُسَافِرِ · ٢","segs":[["matn","فَلَوْ صَلَّى أَرْبَعًا، وَقَرَأَ فِي الْأُولَيَيْنِ، وَقَعَدَ فِي الثَّانِيَةِ، قَدْرَ التَّشَهُّدِ، وَقَعَتِ الْأُولَيَانِ فَرْضًا، وَمَا بَعْدَهُمَا نَفْلًا، وَإِنْ لَمْ يَقْعُدْ بَطَلَتْ."]]},{"id":"tu19_3","label":"فَصْلٌ فِي صَلَاةِ الْمُسَافِرِ · ٣","segs":[["matn","وَيَتَرَخَّصُ الْمُسَافِرُ بِمُفَارَقَةِ بُيُوتِ الْمِصْرِ حَتَّى يَرْجِعَ إِلَيْهَا، أَوْ يَنْوِيَ الْإِقَامَةَ فِي بَلَدٍ، أَوْ فِي قَرْيَةٍ خَمْسَةَ عَشَرَ يَوْمًا، لَا فِي مَفَازَةٍ فَيُتِمُّ."]]},{"id":"tu19_4","label":"فَصْلٌ فِي صَلَاةِ الْمُسَافِرِ · ٤","segs":[["matn","وَلَوْ دَخَلَ مِصْرًا، وَلَمْ يَنْوِ الْإِقَامَةَ فِيهِ، وَتَمَادَتْ حَاجَتُهُ أَشْهُرًا تَرَخَّصَ، وَلَا تَصِحُّ نِيَّةُ إِقَامَةِ الْعَسْكَرِ الْمُحَارِبِ لِلْكُفَّارِ، أَوِ الْبُغَاةِ، بِخِلَافِ أَهْلِ الْكَلَأِ."]]},{"id":"tu19_5","label":"فَصْلٌ فِي صَلَاةِ الْمُسَافِرِ · ٥","segs":[["matn","وَيُتِمُّ الْمُسَافِرُ الْمُقْتَدِي بِالْمُقِيمِ، وَإِذَا صَلَّى الْمُسَافِرُ بِالْمُقِيمِينَ رَكْعَتَيْنِ سَلَّمَ، وَقَالَ: أَتِمُّوا صَلَاتَكُمْ فَإِنَّا قَوْمٌ سَفْرٌ، فَيُتِمُّونَ صَلَاتَهُمْ بِغَيْرِ قِرَاءَةٍ، وَمَنْ تَوَطَّنَ فِي غَيْرِ وَطَنِهِ، ثُمَّ دَخَلَ وَطَنَهُ الْأَوَّلَ قَصَرَ."]]},{"id":"tu19_6","label":"فَصْلٌ فِي صَلَاةِ الْمُسَافِرِ · ٦","segs":[["matn","وَفَائِتَةُ الْحَضَرِ تُقْضَى فِي السَّفَرِ أَرْبَعًا، وَفَائِتَةُ السَّفَرِ تُقْضَى فِي الْحَضَرِ رَكْعَتَيْنِ، وَالْمُعْتَبَرُ فِي ذَلِكَ آخِرُ الْوَقْتِ."]]},{"id":"tu19_7","label":"فَصْلٌ فِي صَلَاةِ الْمُسَافِرِ · ٧","segs":[["matn","وَيَصِيرُ الْمُسَافِرُ مُقِيمًا بِمُجَرَّدِ النِّيَّةِ، وَلَا يَصِيرُ الْمُقِيمُ مُسَافِرًا إِلَّا بِالنِّيَّةِ مَعَ الْخُرُوجِ. وَيُبَاحُ السَّفَرُ يَوْمَ الْجُمُعَةِ، قَبْلَ الزَّوَالِ وَبَعْدَهُ."]]},{"id":"tu19_8","label":"فَصْلٌ فِي صَلَاةِ الْمُسَافِرِ · ٨","segs":[["matn","وَمَنْ بَدَا لَهُ الرُّجُوعُ مِنَ الطَّرِيقِ إِلَى مِصْرِهِ، وَلَيْسَ بَيْنَهُمَا مُدَّةُ سَفَرٍ صَارَ مُقِيمًا فِي الْحَالِ، وَهُوَ مُسَافِرٌ حَتَّى يَصِلَ إِلَى مِصْرِهِ. وَكُلُّ تَبَعٍ يَصِيرُ مُقِيمًا بِنِيَّةِ مَتْبُوعِهِ، إِذَا عَلِمَ بِهَا."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu20","title":"فَصْلٌ فِي صَلَاةِ الْمَرِيضِ","units":[{"id":"tu20_1","label":"فَصْلٌ فِي صَلَاةِ الْمَرِيضِ · ١","segs":[["matn","مَنْ عَجَزَ عَنِ الْقِيَامِ صَلَّى قَاعِدًا يَرْكَعُ وَيَسْجُدُ، فَإِنْ لَمْ يُطِقِ الرُّكُوعَ وَالسُّجُودَ أَوْمَأَ قَاعِدًا، وَجَعَلَ سُجُودَهُ أَخْفَضَ مِنْ رُكُوعِهِ،"]]},{"id":"tu20_2","label":"فَصْلٌ فِي صَلَاةِ الْمَرِيضِ · ٢","segs":[["matn","وَلَا يَرْفَعُ إِلَى وَجْهِهِ شَيْئًا يَسْجُدُ عَلَيْهِ، فَإِنْ لَمْ يُطِقِ الْقُعُودَ اسْتَلْقَى عَلَى ظَهْرِهِ، وَجَعَلَ رِجْلَيْهِ إِلَى الْقِبْلَةِ، وَأَوْمَأَ بِالرُّكُوعِ وَالسُّجُودِ، أَوِ اضْطَجَعَ عَلَى جَنْبِهِ مُتَوَجِّهًا إِلَيْهَا."]]},{"id":"tu20_3","label":"فَصْلٌ فِي صَلَاةِ الْمَرِيضِ · ٣","segs":[["matn","وَالْأَوَّلُ أَوْلَى، فَإِنْ لَمْ يُطِقِ الْإِيمَاءَ بِرَأْسِهِ أَخَّرَ الصَّلَاةَ وَلَمْ تَسْقُطْ مَا دَامَ مُفِيقًا، وَلَا يُومِئُ بِغَيْرِ رَأْسِهِ، وَإِنْ قَدَرَ عَلَى الْقِيَامِ لَا عَلَى الرُّكُوعِ وَالسُّجُودِ صَلَّى قَاعِدًا يُومِئُ بِهِمَا أَوْ قَائِمًا."]]},{"id":"tu20_4","label":"فَصْلٌ فِي صَلَاةِ الْمَرِيضِ · ٤","segs":[["matn","وَالْأَوَّلُ أَوْلَى. وَمَنْ مَرِضَ فِي صَلَاتِهِ بَنَى عَلَى حَسَبِ مَا يَقْدِرُ، وَمَنْ صَلَّى قَاعِدًا ثُمَّ صَحَّ بَنَى قَائِمًا."]]},{"id":"tu20_5","label":"فَصْلٌ فِي صَلَاةِ الْمَرِيضِ · ٥","segs":[["matn","وَمَنْ صَلَّى مُومِئًا ثُمَّ صَحَّ فِيهَا اسْتَقْبَلَ، وَمَنْ جُنَّ أَوْ أُغْمِيَ عَلَيْهِ يَوْمًا وَلَيْلَةً قَضَى بِخِلَافِ الْأَكْثَرِ، وَالنَّائِمُ يَقْضِي مُطْلَقًا، وَيَقْضِي الْمَرِيضُ فَائِتَةَ الصِّحَّةِ عَلَى حَسَبِ حَالِهِ، وَيَقْضِي الصَّحِيحُ فَائِتَةَ الْمَرَضِ كَامِلَةً."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu21","title":"فَصْلٌ فِي الْفَائِتَةِ","units":[{"id":"tu21_1","label":"فَصْلٌ فِي الْفَائِتَةِ · ١","segs":[["matn","وَمَنْ فَاتَتْهُ صَلَاةٌ قَضَاهَا إِذَا ذَكَرَهَا قَبْلَ فَرْضِ الْوَقْتِ، إِلَّا إِذَا خَافَ فَوْتَ فَرْضِ الْوَقْتِ، أَوْ وُقُوعَهُ فِي وَقْتٍ مَكْرُوهٍ، أَوْ كَانَتِ الْفَوَائِتُ سِتًّا كُلُّهَا قَدِيمَةٌ أَوْ حَدِيثَةٌ، فَإِنْ قَضَى وَاحِدَةً مِنَ السِّتَّةِ، عَادَ التَّرْتِيبُ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu22","title":"فَصْلٌ","units":[{"id":"tu22_1","label":"فَصْلٌ · ١","segs":[["matn","وَمَنْ دَخَلَ مَسْجِدًا قَدْ أُذِّنَ فِيهِ كُرِهَ خُرُوجُهُ قَبْلَ الصَّلَاةِ، إِلَّا أَنْ يَكُونَ إِمَامًا، أَوْ مُؤَذِّنًا؛ فَذَهَبَ إِلَى جَمَاعَتِهِ، أَوْ يَكُونَ قَدْ صَلَّى الْفَرْضَ، فَيَخْرُجُ إِلَّا أَنْ يُقَامَ لِلصَّلَاةِ قَبْلَ خُرُوجِهِ فَيَقْتَدِي تَطَوُّعًا فِي الظُّهْرِ،"]]},{"id":"tu22_2","label":"فَصْلٌ · ٢","segs":[["matn","وَالْعِشَاءِ، وَيَخْرُجُ فِي الْبَاقِي وَلَوْ جَاءَ رَجُلٌ وَالْإِمَامُ فِي صَلَاةِ الْفَجْرِ: إِنْ خَافَ فَوْتَ رَكْعَةٍ وَاحِدَةٍ مَعَ الْإِمَامِ، صَلَّى السُّنَّةَ خَارِجَ الْمَسْجِدِ، ثُمَّ اقْتَدَى بِهِ، وَإِنْ خَافَ فَوْتَ الرَّكْعَتَيْنِ، تَرَكَ السُّنَّةَ، وَاقْتَدَى بِهِ وَلَمْ يَقْضِهَا."]]},{"id":"tu22_3","label":"فَصْلٌ · ٣","segs":[["matn","وَسُنَّةُ الظُّهْرِ يَتْرُكُهَا فِي الْحَالَيْنِ، وَيَقْضِيهَا كَمَا مَرَّ فِي فَصْلِ السُّنَنِ. وَمَنْ أَدْرَكَ مَعَ الْإِمَامِ رَكْعَةً، حَصَلَ لَهُ ثَوَابُ الْجَمَاعَةِ."]]},{"id":"tu22_4","label":"فَصْلٌ · ٤","segs":[["matn","وَلَوْ أَدْرَكَ الْإِمَامَ رَاكِعًا فَكَبَّرَ، وَوَقَفَ حَتَّى رَفَعَ الْإِمَامُ رَأْسَهُ، لَا يَصِيرُ مُدْرِكًا لِتِلْكَ الرَّكْعَةِ، وَلَوْ أَدْرَكَهُ فِي الْقِيَامِ، وَلَمْ يَرْكَعْ مَعَهُ حَتَّى رَفَعَ الْإِمَامُ رَأْسَهُ، ثُمَّ رَكَعَ الْمُقْتَدِي صَارَ مُدْرِكًا لَهَا، وَلَوْ رَكَعَ قَبْلَ الْإِمَامِ، فَأَدْرَكَهُ الْإِمَامُ فِيهِ صَحَّ."]]},{"id":"tu22_5","label":"فَصْلٌ · ٥","segs":[["matn","وَالْمَسْبُوقُ يَقْضِي فَائِتَهُ بَعْدَ فَرَاغِ الْإِمَامِ بِقِرَاءَةٍ، وَلَوْ كَانَ قَرَأَ مَعَ الْإِمَامِ، بِخِلَافِ مَا لَوْ قَنَتَ مَعَهُ، فَإِنَّهُ لَا يَقْنُتُ فِيمَا يَقْضِي،"]]},{"id":"tu22_6","label":"فَصْلٌ · ٦","segs":[["matn","وَلَوْ أَدْرَكَ مَعَ الْإِمَامِ ثَالِثَةَ الْمَغْرِبِ قَضَى الْأُولَيَيْنِ بِجَلْسَتَيْنِ، وَمَا يَقْضِيهِ الْمَسْبُوقُ أَوَّلُ صَلَاتِهِ حُكْمًا، فَيَسْتَفْتِحُ فِيهِ لَا فِيمَا أَدْرَكَ، وَيَتَشَهَّدُ مَعَ إِمَامِهِ، وَلَا يَدْعُو."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu23","title":"فَصْلٌ فِي سُجُودِ السَّهْوِ","units":[{"id":"tu23_1","label":"فَصْلٌ فِي سُجُودِ السَّهْوِ · ١","segs":[["matn","يَجِبُ لِلسَّهْوِ لَا لِلْعَمْدِ سَجْدَتَانِ، مَتَى تَرَكَ وَاجِبًا، أَوْ أَخَّرَهُ، أَوْ أَخَّرَ رُكْنًا، أَوْ زَادَ فِي صَلَاتِهِ فِعْلًا مِنْ جِنْسِهَا."]]},{"id":"tu23_2","label":"فَصْلٌ فِي سُجُودِ السَّهْوِ · ٢","segs":[["matn","وَيَجِبُ عَلَى الْمَأْمُومِ بِسَهْوِ الْإِمَامِ، فَإِنْ تَرَكَهُ الْإِمَامُ وَافَقَهُ الْمَأْمُومُ، وَسَهْوُ الْمَأْمُومِ لَا يُوجِبُ السُّجُودَ."]]},{"id":"tu23_3","label":"فَصْلٌ فِي سُجُودِ السَّهْوِ · ٣","segs":[["matn","وَمَنْ سَهَا عَنِ الْقَعْدَةِ الْأُولَى: فَإِنْ تَذَكَّرَ وَهُوَ إِلَى الْقُعُودِ أَقْرَبُ قَعَدَ، وَلَا شَيْءَ عَلَيْهِ وَإِنْ كَانَ إِلَى الْقِيَامِ أَقْرَبَ لَمْ يَعُدْ، وَيَسْجُدُ لِلسَّهْوِ."]]},{"id":"tu23_4","label":"فَصْلٌ فِي سُجُودِ السَّهْوِ · ٤","segs":[["matn","وَمَنْ سَهَا عَنِ الْقَعْدَةِ الْأَخِيرَةِ، عَادَ إِلَيْهَا مَا لَمْ يَسْجُدْ لِلْخَامِسَةِ، وَيَسْجُدُ لِلسَّهْوِ، وَإِنْ سَجَدَ لِلْخَامِسَةِ صَارَ فَرْضُهُ نَفْلًا، وَيَضُمُّ إِلَيْهَا رَكْعَةً سَادِسَةً، وَإِنْ لَمْ يَضُمَّ صَحَّ."]]},{"id":"tu23_5","label":"فَصْلٌ فِي سُجُودِ السَّهْوِ · ٥","segs":[["matn","وَلَوْ قَعَدَ فِي الرَّابِعَةِ، ثُمَّ قَامَ وَلَمْ يُسَلِّمْ يَظُنُّ أَنَّهَا الْقَعْدَةُ الْأُولَى، عَادَ مَا لَمْ يَسْجُدْ لِلْخَامِسَةِ، وَيَسْجُدُ لِلسَّهْوِ."]]},{"id":"tu23_6","label":"فَصْلٌ فِي سُجُودِ السَّهْوِ · ٦","segs":[["matn","وَإِنْ سَجَدَ لِلْخَامِسَةِ زَادَ سَادِسَةً وَتَمَّ فَرْضُهُ، وَالزَّائِدُ نَفْلٌ غَيْرُ نَائِبٍ عَنْ سُنَّةِ الظُّهْرِ، وَيَسْجُدُ لِلسَّهْوِ. وَمَنْ سَلَّمَ يُرِيدُ الْخُرُوجَ مِنْ صَلَاتِهِ وَعَلَيْهِ سَهْوٌ، لَمْ يَخْرُجْ مِنْهَا، وَيَسْجُدُ لِلسَّهْوِ."]]},{"id":"tu23_7","label":"فَصْلٌ فِي سُجُودِ السَّهْوِ · ٧","segs":[["matn","وَمَنْ شَكَّ أَصَلَّى ثَلَاثًا، أَوْ أَرْبَعًا، وَذَلِكَ أَوَّلُ مَا عَرَضَ لَهُ اسْتَأْنَفَ بِالسَّلَامِ، وَهُوَ أَوْلَى مِنَ الْكَلَامِ، وَمُجَرَّدُ النِّيَّةِ لَغْوٌ."]]},{"id":"tu23_8","label":"فَصْلٌ فِي سُجُودِ السَّهْوِ · ٨","segs":[["matn","وَإِنْ كَانَ الشَّكُّ يَعْرِضُ لَهُ كَثِيرًا، عَمِلَ بِأَكْبَرِ رَأْيِهِ، فَإِنْ لَمْ يَكُنْ لَهُ رَأْيٌ، أَخَذَ بِالْأَقَلِّ، وَقَعَدَ حَيْثُ يَتَوَهَّمُهُ آخِرَ صَلَاتِهِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu24","title":"فَصْلٌ فِي سَجْدَةِ التِّلَاوَةِ","units":[{"id":"tu24_1","label":"فَصْلٌ فِي سَجْدَةِ التِّلَاوَةِ · ١","segs":[["matn","وَهِيَ أَرْبَعَ عَشْرَةَ سَجْدَةً مَعْرُوفَةً. مِنْهَا: الْأُولَى فِي الْحَجِّ خَاصَّةً، وَمِنْهَا: سَجْدَةُ ص."]]},{"id":"tu24_2","label":"فَصْلٌ فِي سَجْدَةِ التِّلَاوَةِ · ٢","segs":[["matn","وَتَجِبُ عَلَى التَّالِي وَالسَّامِعِ، وَوُجُوبُهَا عَلَى التَّرَاخِي، وَلَا تَجِبُ عَلَى مَنْ لَا تَجِبُ عَلَيْهِ الصَّلَاةُ، وَلَا قَضَاؤُهَا، كَالْحَائِضِ، وَالنُّفَسَاءِ، وَالصَّبِيِّ، وَالْمَجْنُونِ، وَالْكَافِرِ، وَتَجِبُ عَلَى سَامِعِهَا مِنْهُمْ، وَلَوْ سَمِعَهَا مِنَ الطُّوطِيِّ، وَالنَّائِمِ، قِيلَ: لَا تَجِبُ."]]},{"id":"tu24_3","label":"فَصْلٌ فِي سَجْدَةِ التِّلَاوَةِ · ٣","segs":[["matn","وَتَجِبُ عَلَى التَّالِي الْأَصَمِّ. وَإِنْ قَرَأَهَا الْمَأْمُومُ خَلْفَ الْإِمَامِ لَمْ يَسْجُدْهَا هُوَ، وَلَا الْإِمَامُ فِي الصَّلَاةِ وَبَعْدَهَا. وَالسَّجْدَةُ الصَّلَاتِيَّةُ لَا تُقْضَى خَارِجَ الصَّلَاةِ."]]},{"id":"tu24_4","label":"فَصْلٌ فِي سَجْدَةِ التِّلَاوَةِ · ٤","segs":[["matn","وَمَنْ قَرَأَ آيَةَ سَجْدَةٍ وَلَمْ يَسْجُدْهَا حَتَّى صَلَّى فِي مَجْلِسِهِ، وَأَعَادَهَا، وَسَجَدَ سَقَطَتَا، وَلَوْ كَانَ سَجَدَ لِلْأُولَى قَبْلَ الصَّلَاةِ سَجَدَ لِلْأُخْرَى، وَمَتَى اتَّحَدَ الْمَجْلِسُ وَالْآيَةُ تَدَاخَلَتْ، وَمَتَى اخْتَلَفَ أَحَدُهُمَا تَعَدَّدَتْ."]]},{"id":"tu24_5","label":"فَصْلٌ فِي سَجْدَةِ التِّلَاوَةِ · ٥","segs":[["matn","وَلَا يَخْتَلِفُ الْمَجْلِسُ بِمُجَرَّدِ الْقِيَامِ، وَلَا بِخُطْوَةٍ، أَوْ خُطْوَتَيْنِ وَلُقْمَةٍ أَوْ لُقْمَتَيْنِ. وَالسَّفِينَةُ الْجَارِيَةُ كَالْبَيْتِ، وَلَوْ كَرَّرَهَا عَلَى الدَّابَّةِ وَهِيَ تَسِيرُ،"]]},{"id":"tu24_6","label":"فَصْلٌ فِي سَجْدَةِ التِّلَاوَةِ · ٦","segs":[["matn","فَإِنْ كَانَ فِي الصَّلَاةِ اتَّحَدَتْ، وَإِنْ لَمْ يَكُنْ فِيهَا تَعَدَّدَتْ، وَإِذَا تَلَاهَا عَلَى الدَّابَّةِ أَجْزَأَتْهُ بِالْإِيمَاءِ. وَهِيَ كَسَجْدَةِ الصَّلَاةِ بِغَيْرِ تَشَهُّدٍ، وَسَلَامٍ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu25","title":"فَصْلٌ فِي الْمَيِّتِ","units":[{"id":"tu25_1","label":"فَصْلٌ فِي الْمَيِّتِ · ١","segs":[["matn","يُوَجَّهُ الْمُحْتَضَرُ إِلَى الْقِبْلَةِ عَلَى شِقِّهِ الْأَيْمَنِ، وَتُذْكَرُ عِنْدَهُ الشَّهَادَةُ، وَلَا يُؤْمَرُ بِهَا. فَإِذَا مَاتَ غُسِّلَ، وَكُفِّنَ، وَصُلِّيَ عَلَيْهِ."]]},{"id":"tu25_2","label":"فَصْلٌ فِي الْمَيِّتِ · ٢","segs":[["matn","وَإِنْ لَمْ يُصَلَّ عَلَيْهِ، صُلِّيَ عَلَى قَبْرِهِ مَا لَمْ يَغْلِبْ عَلَى الظَّنِّ تَفَسُّخُهُ. وَمَنِ اسْتَهَلَّ غُسِّلَ، وَكُفِّنَ، وَصُلِّيَ عَلَيْهِ."]]},{"id":"tu25_3","label":"فَصْلٌ فِي الْمَيِّتِ · ٣","segs":[["matn","وَإِنْ لَمْ يَسْتَهِلَّ غُسِّلَ، وَلُفَّ فِي خِرْقَةٍ، وَلَمْ يُصَلَّ عَلَيْهِ. وَلَا يُصَلَّى عَلَى بَاغٍ، وَلَا قَاطِعِ الطَّرِيقِ. وَالْمَشْيُ خَلْفَ الْجِنَازَةِ أَفْضَلُ، وَيُطِيلُ الصَّمْتَ، وَيُكْرَهُ رَفْعُ الصَّوْتِ بِالذِّكْرِ."]]},{"id":"tu25_4","label":"فَصْلٌ فِي الْمَيِّتِ · ٤","segs":[["matn","فَإِذَا وَصَلُوا إِلَى قَبْرِهِ، كُرِهَ الْجُلُوسُ قَبْلَ وَضْعِهِ عَنِ الرِّقَابِ. وَيُحْفَرُ الْقَبْرُ لَحْدًا، وَيُدْخَلُ الْمَيِّتُ فِيهِ مِنْ جِهَةِ الْقِبْلَةِ، وَيُضْجَعُ عَلَى شِقِّهِ الْأَيْمَنِ مُوَجَّهًا إِلَيْهَا."]]},{"id":"tu25_5","label":"فَصْلٌ فِي الْمَيِّتِ · ٥","segs":[["matn","وَيُكْرَهُ الْبِنَاءُ عَلَى الْقَبْرِ، وَلَا يُدْفَنُ فِي قَبْرٍ أَكْثَرُ مِنْ وَاحِدٍ إِلَّا لِلضَّرُورَةِ. وَاتِّخَاذُ التَّابُوتِ لِلْمَرْأَةِ حَسَنٌ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu26","title":"فَصْلٌ فِي الشَّهِيدِ","units":[{"id":"tu26_1","label":"فَصْلٌ فِي الشَّهِيدِ · ١","segs":[["matn","وَالشَّهِيدُ: كُلُّ مُسْلِمٍ قَتَلَهُ كَافِرٌ، أَوْ مُسْلِمٌ ظُلْمًا، قَتْلًا لَمْ يَجِبْ بِهِ مَالٌ. وَلَا يُغَسَّلُ، إِلَّا إِذَا قُتِلَ جُنُبًا، أَوْ صَبِيًّا."]]},{"id":"tu26_2","label":"فَصْلٌ فِي الشَّهِيدِ · ٢","segs":[["matn","وَلَا يُغْسَلُ دَمُهُ، وَلَا يُنْزَعُ ثِيَابُهُ، وَيُنْزَعُ كُلُّ مَا عَلَيْهِ مِنْ غَيْرِ جِنْسِ الْكَفَنِ، وَيُكَمَّلُ كَفَنُهُ، ثُمَّ يُصَلَّى عَلَيْهِ."]]},{"id":"tu26_3","label":"فَصْلٌ فِي الشَّهِيدِ · ٣","segs":[["matn","وَكُلُّ جَرِيحٍ أَكَلَ، أَوْ شَرِبَ، أَوْ نَامَ، أَوْ عُولِجَ، أَوْ ضَمَّهُ سَقْفٌ، أَوْ نُقِلَ مِنَ الْمَعْرَكَةِ حَيًّا، لَا لِخَوْفِ وَطْءِ الْخَيْلِ، أَوْ مَرَّ عَلَيْهِ وَقْتُ صَلَاةٍ وَهُوَ حَيٌّ يَعْقِلُ، أَوْ أَوْصَى بِأَمْرٍ دُنْيَوِيٍّ غُسِّلَ. وَاللَّهُ أَعْلَمُ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"tu27","title":"كِتَابُ الزَّكَاةِ","units":[{"id":"tu27_1","label":"كِتَابُ الزَّكَاةِ · ١","segs":[["matn","الزَّكَاةُ تَجِبُ عَلَى كُلِّ حُرٍّ بَالِغٍ عَاقِلٍ مُسْلِمٍ، مَلَكَ نِصَابًا مِلْكًا تَامًّا رَقَبَةً وَيَدًا، وَتَمَّ عَلَيْهِ الْحَوْلُ، وُجُوبًا عَلَى الْفَوْرِ فِي قَوْلٍ."]]},{"id":"tu27_2","label":"كِتَابُ الزَّكَاةِ · ٢","segs":[["matn","وَكُلُّ دَيْنٍ لِآدَمِيٍّ يَمْنَعُ بِقَدْرِهِ حَالًّا كَانَ، أَوْ مُؤَجَّلًا. وَمَنْ مَاتَ وَعَلَيْهِ زَكَاةٌ، أَوْ صَدَقَةُ فِطْرٍ، أَوْ صَوْمٌ، أَوْ نَذْرٌ، أَوْ كَفَّارَةٌ سَقَطَتْ، إِلَّا إِنْ أَوْصَى بِهَا فَتُنَفَّذُ مِنَ الثُّلُثِ."]]},{"id":"tu27_3","label":"كِتَابُ الزَّكَاةِ · ٣","segs":[["matn","وَلَا زَكَاةَ فِي غَيْرِ الْفِضَّةِ وَالذَّهَبِ وَالسَّوَائِمِ، إِلَّا بِنِيَّةِ التِّجَارَةِ. وَلَا زَكَاةَ فِي مَالِ الضِّمَارِ، وَهُوَ مَا لَا يَقْدِرُ عَلَيْهِ بِنَفْسِهِ وَلَا بِنَائِبِهِ."]]},{"id":"tu27_4","label":"كِتَابُ الزَّكَاةِ · ٤","segs":[["matn","وَلَا تَصِحُّ إِلَّا بِنِيَّةٍ مُقَارِنَةٍ لِلْأَدَاءِ، أَوْ لِعَزْلِهَا، إِلَّا إِذَا تَصَدَّقَ بِكُلِّ النِّصَابِ."]]},{"id":"tu27_5","label":"كِتَابُ الزَّكَاةِ · ٥","segs":[["matn","وَنِصَابُ الْفِضَّةِ: مِائَتَا دِرْهَمٍ، كُلُّ عَشَرَةٍ مِنْهَا وَزْنُ سَبْعَةٍ أَغْلَبُهَا فِضَّةٌ، وَفِيهِ خَمْسَةُ دَرَاهِمَ، ثُمَّ فِي كُلِّ أَرْبَعِينَ دِرْهَمًا دِرْهَمٌ، وَالنَّاقِصُ عَفْوٌ."]]},{"id":"tu27_6","label":"كِتَابُ الزَّكَاةِ · ٦","segs":[["matn","وَنِصَابُ الذَّهَبِ عِشْرُونَ مِثْقَالًا أَغْلَبُهَا ذَهَبٌ، وَفِيهِ نِصْفُ مِثْقَالٍ، ثُمَّ فِي كُلِّ أَرْبَعَةِ مَثَاقِيلَ قِيرَاطَانِ، وَالنَّاقِصُ عَفْوٌ، وَالتِّبْرُ وَالْحُلِيُّ وَالْآنِيَةُ نِصَابٌ."]]},{"id":"tu27_7","label":"كِتَابُ الزَّكَاةِ · ٧","segs":[["matn","وَمَا غَلَبَهُ مِنْهُمَا غِشٌّ فَهُوَ كَعُرُوضِ التِّجَارَةِ، إِلَّا أَنْ يَخْلُصَ مِنْهُ نِصَابٌ. وَنِصَابُ الْعُرُوضِ أَنْ يَبْلُغَ قِيمَتُهَا نِصَابًا بِالْأَنْفَعِ لِلْفُقَرَاءِ."]]},{"id":"tu27_8","label":"كِتَابُ الزَّكَاةِ · ٨","segs":[["matn","وَكَمَالُ النِّصَابِ فِي طَرَفَيِ الْحَوْلِ كَافٍ. وَيُضَمُّ الذَّهَبُ وَالْفِضَّةُ وَالْعُرُوضُ بَعْضُهَا إِلَى بَعْضٍ بِالْقِيمَةِ، وَيُضَمُّ مَا دُونَ الْأَرْبَعِينَ إِلَى مَا دُونَ أَرْبَعَةِ مَثَاقِيلَ أَيْضًا."]]},{"id":"tu27_9","label":"كِتَابُ الزَّكَاةِ · ٩","segs":[["matn","وَنِصَابُ الْإِبِلِ: فِي كُلِّ خَمْسٍ شَاةٌ إِلَى خَمْسٍ وَعِشْرِينَ، ثُمَّ بِنْتُ مَخَاضٍ إِلَى سِتٍّ وَثَلَاثِينَ، ثُمَّ بِنْتُ لَبُونٍ إِلَى سِتٍّ وَأَرْبَعِينَ، ثُمَّ حِقَّةٌ إِلَى إِحْدَى وَسِتِّينَ،"]]},{"id":"tu27_10","label":"كِتَابُ الزَّكَاةِ · ١٠","segs":[["matn","ثُمَّ جَذَعَةٌ إِلَى سِتٍّ وَسَبْعِينَ، ثُمَّ بِنْتَا لَبُونٍ إِلَى إِحْدَى وَتِسْعِينَ، ثُمَّ حِقَّتَانِ إِلَى مِائَةٍ وَعِشْرِينَ، ثُمَّ يَبْدَأُ كَمَا مَرَّ إِلَى خَمْسٍ وَعِشْرِينَ،"]]},{"id":"tu27_11","label":"كِتَابُ الزَّكَاةِ · ١١","segs":[["matn","ثُمَّ بِنْتُ مَخَاضٍ إِلَى مِائَةٍ وَخَمْسِينَ، ثُمَّ ثَلَاثُ حِقَاقٍ، ثُمَّ يَبْدَأُ إِلَى سِتٍّ وَثَلَاثِينَ، ثُمَّ بِنْتُ لَبُونٍ إِلَى مِائَةٍ وَسِتٍّ وَتِسْعِينَ، ثُمَّ أَرْبَعُ حِقَاقٍ إِلَى مِائَتَيْنِ، ثُمَّ يَبْدَأُ كَمَا بَدَأَ ثَانِيًا. وَالْبُخْتُ وَالْعِرَابُ سَوَاءٌ."]]},{"id":"tu27_12","label":"كِتَابُ الزَّكَاةِ · ١٢","segs":[["matn","وَنِصَابُ الْبَقَرِ: ثَلَاثُونَ، وَفِيهِ تَبِيعٌ إِلَى أَرْبَعِينَ، ثُمَّ مُسِنَّةٌ، وَمَا زَادَ بِحِسَابِهِ إِلَى سِتِّينَ، ثُمَّ تَبِيعَانِ إِلَى سَبْعِينَ، ثُمَّ مُسِنَّةٌ وَتَبِيعٌ إِلَى ثَمَانِينَ،"]]},{"id":"tu27_13","label":"كِتَابُ الزَّكَاةِ · ١٣","segs":[["matn","ثُمَّ مُسِنَّتَانِ إِلَى تِسْعِينَ، ثُمَّ ثَلَاثَةُ أَتْبِعَةٍ إِلَى مِائَةٍ، ثُمَّ تَبِيعَانِ وَمُسِنَّةٌ، وَهَكَذَا أَبَدًا كَمَا ذَكَرْنَا. وَالذَّكَرُ وَالْأُنْثَى سَوَاءٌ، وَالْجَوَامِيسُ وَالْبَقَرُ سَوَاءٌ."]]},{"id":"tu27_14","label":"كِتَابُ الزَّكَاةِ · ١٤","segs":[["matn","وَنِصَابُ الْغَنَمِ: أَرْبَعُونَ، وَفِيهِ شَاةٌ إِلَى مِائَةٍ وَإِحْدَى وَعِشْرِينَ، ثُمَّ شَاتَانِ إِلَى مِائَتَيْنِ وَوَاحِدَةٍ، ثُمَّ ثَلَاثُ شِيَاهٍ إِلَى أَرْبَعِمِائَةٍ، أَرْبَعُ شِيَاهٍ، فِي كُلِّ مِائَةٍ شَاةٌ. وَالضَّأْنُ وَالْمَعْزُ سَوَاءٌ."]]},{"id":"tu27_15","label":"كِتَابُ الزَّكَاةِ · ١٥","segs":[["matn","وَيُؤْخَذُ الثَّنِيُّ مِنْهُمَا، وَلَا يُؤْخَذُ الْجَذَعُ. وَمَا يُنْتَجُ بَيْنَ ظَبْيٍ وَشَاةٍ، أَوْ بَقَرَةٍ وَحْشِيَّةٍ وَأَهْلِيَّةٍ، يُعْتَبَرُ أُمُّهُ. وَنِصَابُ الْخَيْلِ: اثْنَانِ ذَكَرٌ وَأُنْثَى، وَفِيهِ دِينَارَانِ، أَوْ زَكَاةُ الْقِيمَةِ."]]},{"id":"tu27_16","label":"كِتَابُ الزَّكَاةِ · ١٦","segs":[["matn","وَلَا يَجِبُ شَيْءٌ فِي ذُكُورٍ، أَوْ إِنَاثٍ مَحْضَةٍ فِي الْأَشْهَرِ، وَلَا فِي الْبِغَالِ وَالْحَمِيرِ، وَلَا فِي الصِّغَارِ إِلَّا تَبَعًا لِلْكَبِيرَةِ."]]},{"id":"tu27_17","label":"كِتَابُ الزَّكَاةِ · ١٧","segs":[["matn","وَلَيْسَ فِي الْعَلُوفَةِ، وَلَا فِي الْحَوَامِلِ، وَالْعَوَامِلِ السَّائِمَةِ، زَكَاةٌ. وَالسَّائِمَةُ: الرَّاعِيَةُ أَكْثَرَ الْحَوْلِ، لَا لِلرُّكُوبِ وَالْعَمَلِ. وَبِنْتُ مَخَاضٍ: مَا دَخَلَ فِي السَّنَةِ الثَّانِيَةِ."]]},{"id":"tu27_18","label":"كِتَابُ الزَّكَاةِ · ١٨","segs":[["matn","وَبِنْتُ لَبُونٍ: فِي الثَّالِثَةِ. وَالْحِقَّةُ: فِي الرَّابِعَةِ. وَالْجَذَعَةُ: فِي الْخَامِسَةِ. وَالتَّبِيعُ: فِي الثَّانِيَةِ. وَالْمُسِنَّةُ: فِي الثَّالِثَةِ. وَثَنِيُّ الْغَنَمِ مَا بَلَغَ سَنَةً، وَجَذَعُهَا مَا بَلَغَ أَكْثَرَهَا."]]},{"id":"tu27_19","label":"كِتَابُ الزَّكَاةِ · ١٩","segs":[["matn","وَمَنْ وَجَبَ عَلَيْهِ سِنٌّ لَا يَمْلِكُهُ أَعْطَى أَعْلَى مِنْهُ، وَأَخَذَ الزَّائِدَ بِرِضَا السَّاعِي، أَوْ أَعْطَى أَسْفَلَ مِنْهُ مَعَ الزَّائِدِ مُطْلَقًا."]]},{"id":"tu27_20","label":"كِتَابُ الزَّكَاةِ · ٢٠","segs":[["matn","وَيَجُوزُ دَفْعُ الْقِيمَةِ فِي الزَّكَاةِ، وَالْفِطْرِ، وَالْكَفَّارَةِ، وَالْعُشْرِ، وَالْخَرَاجِ، وَالنَّذْرِ، لَا فِي الْهَدَايَا وَالضَّحَايَا. وَالْوَاجِبُ أَخْذُ الْوَسَطِ مِنَ النِّصَابِ."]]},{"id":"tu27_21","label":"كِتَابُ الزَّكَاةِ · ٢١","segs":[["matn","وَمُطْلَقُ الْمُسْتَفَادِ يُضَمُّ فِي الْحَوْلِ، إِلَّا أَنَّ الرِّبْحَ وَالْوَلَدَ يُضَمُّ إِلَى أَصْلِهِ لَا غَيْرُ، وَغَيْرُهُمَا يُضَمُّ إِلَى أَقْرَبِ جِنْسِهِ حَوْلًا."]]},{"id":"tu27_22","label":"كِتَابُ الزَّكَاةِ · ٢٢","segs":[["matn","وَالزَّكَاةُ وَاجِبَةٌ فِي النِّصَابِ دُونَ الْعَفْوِ، فَلَا يَسْقُطُ شَيْءٌ بِهَلَاكِ الْعَفْوِ، وَلَوْ هَلَكَ النِّصَابُ بَعْدَ وُجُوبِ الزَّكَاةِ سَقَطَتْ، وَلَوْ هَلَكَ بَعْضُهُ سَقَطَ بِقَدْرِهِ،"]]},{"id":"tu27_23","label":"كِتَابُ الزَّكَاةِ · ٢٣","segs":[["matn","وَلَوْ أَهْلَكَهُ الْمَالِكُ ضَمِنَ، وَلَوْ هَلَكَ بَعْدَ طَلَبِ السَّاعِي فَقَوْلَانِ. وَيَصِحُّ التَّعْجِيلُ لِسِنِينَ، وَلِنُصُبٍ أَيْضًا بَعْدَ مَا مَلَكَ النِّصَابَ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"tu28","title":"بَابُ الْمَعْدِنِ وَالرِّكَازِ","units":[{"id":"tu28_1","label":"بَابُ الْمَعْدِنِ وَالرِّكَازِ · ١","segs":[["matn","وَمَنْ وَجَدَ مَعْدِنًا مِنْ جَوْهَرٍ ذَائِبٍ فِي أَرْضٍ مُبَاحَةٍ، فَفِيهِ الْخُمُسُ، وَالْبَاقِي لَهُ، وَلَوْ وَجَدَهُ فِي دَارِهِ فَلَا شَيْءَ فِيهِ، بِخِلَافِ الْكَنْزِ، وَلَوْ وَجَدَهُ فِي أَرْضِهِ فَرِوَايَتَانِ."]]},{"id":"tu28_2","label":"بَابُ الْمَعْدِنِ وَالرِّكَازِ · ٢","segs":[["matn","وَمَنْ وَجَدَ كَنْزًا فَفِيهِ الْخُمُسُ وَلَوْ كَانَ مَتَاعًا، وَالْبَاقِي لُقَطَةٌ فِي الضَّرْبِ الْإِسْلَامِيِّ. وَفِي الْجَاهِلِيِّ هُوَ لِلْوَاجِدِ، إِنْ كَانَتِ الْأَرْضُ مُبَاحَةً، وَإِنْ لَمْ تَكُنْ فَلِمَالِكِهَا أَوَّلَ الْفَتْحِ،"]]},{"id":"tu28_3","label":"بَابُ الْمَعْدِنِ وَالرِّكَازِ · ٣","segs":[["matn","فَإِنْ جُهِلَ فَلِأَقْصَى مَالِكٍ يُعْرَفُ فِي الْإِسْلَامِ، فَإِنْ خَفِيَ الضَّرْبُ جُعِلَ جَاهِلِيًّا. وَلَا شَيْءَ فِي الْفَيْرُوزَجِ، وَالْيَاقُوتِ، وَاللُّؤْلُؤِ، وَالْعَنْبَرِ. وَفِي الزِّئْبَقِ الْخُمُسُ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"tu29","title":"بَابُ زَكَاةِ النَّبَاتِ","units":[{"id":"tu29_1","label":"بَابُ زَكَاةِ النَّبَاتِ · ١","segs":[["matn","يَجِبُ عُشْرُ كُلِّ نَابِتٍ بِمَاءِ السَّمَاءِ، أَوْ سَيْحًا، إِلَّا الْحَطَبَ وَالْقَصَبَ وَالْحَشِيشَ، مِنْ غَيْرِ شَرْطِ نِصَابٍ، أَوْ حَوْلٍ، أَوْ عَقْلٍ، أَوْ بُلُوغٍ."]]},{"id":"tu29_2","label":"بَابُ زَكَاةِ النَّبَاتِ · ٢","segs":[["matn","فَإِنْ جَعَلَ أَرْضَهُ مَحْطَبَةً، أَوْ مَقْصَبَةً، أَوْ مُحْتَشًّا، وَجَبَ فِيهِ الْعُشْرُ. وَمَا سُقِيَ بِغَرْبٍ، أَوْ دَالِيَةٍ، فَفِيهِ نِصْفُ الْعُشْرِ، وَإِنْ سُقِيَ سَيْحًا وَبِدَالِيَةٍ حُكِمَ بِأَكْثَرِ الْحَوْلِ، وَفِي الْعَسَلِ الْعُشْرُ،"]]},{"id":"tu29_3","label":"بَابُ زَكَاةِ النَّبَاتِ · ٣","segs":[["matn","وَلَوْ وُجِدَ فِي الْجَبَلِ فَفِيهِ الْعُشْرُ، كَالثَّمَرِ، وَلَا يُطْرَحُ أَجْرُ الْعُمَّالِ، وَنَفَقَةُ الْبَقَرِ قَبْلَ الْعُشْرِ. وَلَا شَيْءَ فِي الْقِيرِ، وَالنِّفْطِ."]]},{"id":"tu29_4","label":"بَابُ زَكَاةِ النَّبَاتِ · ٤","segs":[["matn","مَصَارِفُ الزَّكَاةِ سَبْعَةٌ: الْفَقِيرُ: وَهُوَ مَنْ لَهُ أَدْنَى شَيْءٍ. وَالْمِسْكِينُ: وَهُوَ مَنْ لَا شَيْءَ لَهُ، وَقِيلَ: بِالْعَكْسِ. وَالْعَامِلُ: غَيْرُ الْهَاشِمِيِّ وَلَوْ كَانَ غَنِيًّا."]]},{"id":"tu29_5","label":"بَابُ زَكَاةِ النَّبَاتِ · ٥","segs":[["matn","وَالْمُكَاتَبُ، وَالْمَدْيُونُ، وَالْغَازِي الْمُنْقَطِعُ، وَقِيلَ: الْحَاجُّ الْمُنْقَطِعُ، وَمَنْ مَالُهُ بَعِيدٌ عَنْهُ، وَلِلْمَالِكِ أَنْ يَعُمَّ كُلَّ الْمَصَارِفِ وَأَنْ يَخُصَّ بَعْضَهَا، وَلَا يَدْفَعُ إِلَى غَنِيٍّ،"]]},{"id":"tu29_6","label":"بَابُ زَكَاةِ النَّبَاتِ · ٦","segs":[["matn","وَإِنْ كَانَ نِصَابُهُ غَيْرَ تَامٍّ وَلَا إِلَى ذِمِّيٍّ، بِخِلَافِ غَيْرِ الزَّكَاةِ، وَلَا يُبْنَى مِنْهَا مَسْجِدٌ، وَلَا يُكَفَّنُ بِهَا مَيِّتٌ، وَلَا يُقْضَى دَيْنُهُ،"]]},{"id":"tu29_7","label":"بَابُ زَكَاةِ النَّبَاتِ · ٧","segs":[["matn","وَلَا يُعْتَقُ بِهَا عَبْدٌ، وَلَا يَدْفَعُهَا الْمُزَكِّي إِلَى أُصُولِهِ وَفُرُوعِهِ، وَزَوْجَتِهِ، وَزَوْجِهَا، وَمُكَاتَبِهِ، وَمُدَبَّرِهِ، وَأُمِّ وَلَدٍ وَعَبْدٍ أُعْتِقَ بَعْضُهُ، وَلَا إِلَى مَمْلُوكِ غَنِيٍّ، وَوَلَدِهِ الصَّغِيرِ، بِخِلَافِ امْرَأَتِهِ، وَلَا إِلَى هَاشِمِيٍّ وَمَوْلَاهُ."]]},{"id":"tu29_8","label":"بَابُ زَكَاةِ النَّبَاتِ · ٨","segs":[["matn","وَلَوْ ظَنَّهُ مَصْرِفًا فَأَعْطَاهُ فَأَخْطَأَ سَقَطَتْ عَنْهُ، إِلَّا فِي مُكَاتَبِهِ، وَلَوْ أَعْطَاهُ شَاكًّا لَمْ تَسْقُطْ، إِلَّا أَنْ يَتَحَقَّقَ أَنَّهُ مَصْرِفٌ."]]},{"id":"tu29_9","label":"بَابُ زَكَاةِ النَّبَاتِ · ٩","segs":[["matn","وَيُكْرَهُ إِعْطَاؤُهُ وَاحِدًا مِنَ الزَّكَاةِ نِصَابًا، وَيُكْرَهُ نَقْلُهَا إِلَى بَلَدٍ آخَرَ، إِلَّا إِلَى قَرِيبٍ، أَوْ أَحْوَجَ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"tu30","title":"بَابُ صَدَقَةِ الْفِطْرِ","units":[{"id":"tu30_1","label":"بَابُ صَدَقَةِ الْفِطْرِ · ١","segs":[["matn","تَجِبُ عَلَى كُلِّ مُسْلِمٍ حُرٍّ مَالِكٍ نِصَابًا، فَاضِلًا عَنْ حَاجَتِهِ الْأَصْلِيَّةِ، وَإِنْ كَانَ غَيْرَ نَامٍ عَنْهُ، وَعَنْ وَلَدِهِ الصَّغِيرِ الَّذِي لَا شَيْءَ لَهُ، وَعَنْ عَبِيدِهِ لِلْخِدْمَةِ، وَلَوْ أَنَّهُ كَافِرٌ، بِخِلَافِ وَلَدِهِ الْكَبِيرِ وَزَوْجَتِهِ، وَلَوْ أَدَّى عَنْهُمَا تَبَرُّعًا وَلَمْ يَعْلَمَا أَجْزَأَهُمَا."]]},{"id":"tu30_2","label":"بَابُ صَدَقَةِ الْفِطْرِ · ٢","segs":[["matn","وَلَا تَجِبُ عَنْ مُكَاتَبِهِ، بِخِلَافِ مُدَبَّرِهِ، وَأُمِّ وَلَدِهِ، وَلَا عَنْ عَبْدٍ، أَوْ عَبِيدٍ بَيْنَ اثْنَيْنِ. وَهِيَ: نِصْفُ صَاعٍ مِنْ بُرٍّ وَزْنًا، أَوْ دَقِيقِهِ، أَوْ سَوِيقِهِ، أَوْ صَاعٌ مِنْ تَمْرٍ، أَوْ شَعِيرٍ، أَوْ دَقِيقِهِ، أَوْ سَوِيقِهِ."]]},{"id":"tu30_3","label":"بَابُ صَدَقَةِ الْفِطْرِ · ٣","segs":[["matn","وَفِي الزَّبِيبِ رِوَايَتَانِ، وَالدَّقِيقُ أَفْضَلُ مِنَ الْبُرِّ، وَالدَّرَاهِمُ أَفْضَلُ مِنْهُمَا، وَقِيلَ: الْبُرُّ أَفْضَلُ مِنْهُمَا."]]},{"id":"tu30_4","label":"بَابُ صَدَقَةِ الْفِطْرِ · ٤","segs":[["matn","وَالصَّاعُ: ثَمَانِيَةُ أَرْطَالٍ بِالْعِرَاقِيِّ. وَوَقْتُهَا: فَجْرُ يَوْمِ الْفِطْرِ، وَيُسْتَحَبُّ دَفْعُهَا قَبْلَ الْخُرُوجِ إِلَى صَلَاةِ الْعِيدِ. وَيَصِحُّ تَعْجِيلُهَا مُطْلَقًا، وَلَا تَسْقُطُ بِالتَّأْخِيرِ بِخِلَافِ الْأُضْحِيَّةِ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"tu31","title":"كِتَابُ الصَّوْمِ","units":[{"id":"tu31_1","label":"كِتَابُ الصَّوْمِ · ١","segs":[["matn","يَصِحُّ صَوْمُ رَمَضَانَ مِنَ الصَّحِيحِ الْمُقِيمِ بِمُطْلَقِ النِّيَّةِ، وَنِيَّةِ النَّفْلِ، وَنِيَّةِ وَاجِبٍ آخَرَ."]]},{"id":"tu31_2","label":"كِتَابُ الصَّوْمِ · ٢","segs":[["matn","وَالنَّذْرُ الْمُعَيَّنُ يَصِحُّ بِمُطْلَقِ النِّيَّةِ، وَبِنِيَّةِ النَّفْلِ لَا بِنِيَّةِ وَاجِبٍ آخَرَ، وَكِلَاهُمَا يَصِحُّ بِنِيَّةٍ مِنَ اللَّيْلِ وَالنَّهَارِ قَبْلَ الضَّحْوَةِ الْكُبْرَى، لَا بَعْدَهَا كَالنَّفْلِ."]]},{"id":"tu31_3","label":"كِتَابُ الصَّوْمِ · ٣","segs":[["matn","وَالْأَفْضَلُ التَّبْيِيتُ، وَلَوْ نَوَى الْمَرِيضُ وَالْمُسَافِرُ بِرَمَضَانَ وَاجِبًا آخَرَ صَحَّ، وَلَوْ تَطَوَّعَ بِهِ فَفِيهِ رِوَايَتَانِ، وَالنَّذْرُ الْمُطْلَقُ، وَالْكَفَّارَةُ، وَقَضَاءُ رَمَضَانَ وَنَحْوُهَا لَا يَصِحُّ بِنِيَّةٍ فِي النَّهَارِ."]]},{"id":"tu31_4","label":"كِتَابُ الصَّوْمِ · ٤","segs":[["matn","وَيُسْتَحَبُّ طَلَبُ الْهِلَالِ لَيْلَةَ ثَلَاثِينَ مِنْ شَعْبَانَ وَرَمَضَانَ، فَإِنْ لَمْ يَرَوْا فَلَا صَوْمَ، وَلَا فِطْرَ. وَيُكْرَهُ صَوْمُ يَوْمِ الشَّكِّ، إِلَّا أَنْ يُوَافِقَ وِرْدًا لَهُ. وَمَنْ رَأَى الْهِلَالَ وَحْدَهُ فَرُدَّتْ شَهَادَتُهُ صَامَ."]]},{"id":"tu31_5","label":"كِتَابُ الصَّوْمِ · ٥","segs":[["matn","فَإِنْ أَفْطَرَ بَعْدَ الرَّدِّ لَزِمَهُ الْقَضَاءُ لَا غَيْرُ، وَكَذَا لَوْ أَفْطَرَ قَبْلَهُ عِنْدَ الْبَعْضِ، وَلَوْ صَامَ ثَلَاثِينَ يَوْمًا لَمْ يُفْطِرْ وَحْدَهُ، فَإِنْ أَفْطَرَ فَلَا كَفَّارَةَ عَلَيْهِ."]]},{"id":"tu31_6","label":"كِتَابُ الصَّوْمِ · ٦","segs":[["matn","وَيُقْبَلُ فِي هِلَالِ رَمَضَانَ فِي الْغَيْمِ شَهَادَةُ وَاحِدٍ عَدْلٍ، وَلَوْ كَانَ عَبْدًا، أَوْ أَمَةً، أَوْ مَحْدُودًا فِي قَذْفٍ."]]},{"id":"tu31_7","label":"كِتَابُ الصَّوْمِ · ٧","segs":[["matn","فَإِذَا صَامُوا ثَلَاثِينَ يَوْمًا، وَلَمْ يَرَوْا فَفِي الْفِطْرِ خِلَافٌ، بِخِلَافِ شَهَادَةِ اثْنَيْنِ، وَفِي الصَّحْوِ لَا بُدَّ مِنْ أَهْلِ مَحَلَّةٍ، أَوْ خَمْسِينَ رَجُلًا."]]},{"id":"tu31_8","label":"كِتَابُ الصَّوْمِ · ٨","segs":[["matn","وَفِي هِلَالِ شَوَّالٍ فِي الْغَيْمِ لَا بُدَّ مِنْ رَجُلَيْنِ حُرَّيْنِ، أَوْ رَجُلٍ وَامْرَأَتَيْنِ كَالْأَضْحَى. وَلَا يَلْزَمُ أَحَدَ الْمِصْرَيْنِ بِرُؤْيَةِ الْمِصْرِ الْآخَرِ، إِلَّا إِذَا اتَّحَدَتِ الْمَطَالِعُ."]]},{"id":"tu31_9","label":"كِتَابُ الصَّوْمِ · ٩","segs":[["matn","وَلَوْ أَكْمَلُوا شَعْبَانَ ثُمَّ صَامُوا رَمَضَانَ فَكَانَ ثَمَانِيَةً وَعِشْرِينَ، فَإِنْ كَانُوا عَدُّوا شَعْبَانَ عَنْ رُؤْيَةِ هِلَالِهِ قَضَوْا يَوْمًا، وَإِلَّا قَضَوْا يَوْمَيْنِ."]]},{"id":"tu31_10","label":"كِتَابُ الصَّوْمِ · ١٠","segs":[["matn","وَلَوْ رُئِيَ الْهِلَالُ قَبْلَ الزَّوَالِ فَهُوَ لِلَّيْلَةِ الْمَاضِيَةِ، وَإِنْ رُئِيَ بَعْدَهُ فَهُوَ لِلَّيْلَةِ الْمُسْتَقْبَلَةِ. وَوَقْتُ الصَّوْمِ: مِنْ طُلُوعِ الْفَجْرِ الثَّانِي إِلَى غُرُوبِ الشَّمْسِ. وَالصَّوْمُ: هُوَ الْكَفُّ عَنِ الْأَكْلِ وَالشُّرْبِ وَالْجِمَاعِ، نَهَارًا مَعَ النِّيَّةِ."]]}],"group":"كِتَابُ الصَّوْمِ"},{"id":"tu32","title":"فَصْلٌ","units":[{"id":"tu32_1","label":"فَصْلٌ · ١","segs":[["matn","وَمَنْ أَكَلَ، أَوْ شَرِبَ، أَوْ جَامَعَ نَاسِيًا لَمْ يُفْطِرْ، بِخِلَافِ الْمُكْرَهِ، وَالْمُخْطِئِ. وَلَوْ أَنْزَلَ بِاحْتِلَامٍ، أَوْ فِكْرٍ، أَوْ نَظَرٍ، أَوْ أَصْبَحَ جُنُبًا مِنْ جِمَاعٍ، أَوِ ادَّهَنَ، أَوْ قَبَّلَ، لَمْ يُفْطِرْ."]]},{"id":"tu32_2","label":"فَصْلٌ · ٢","segs":[["matn","وَلَوْ أَنْزَلَ بِقُبْلَةٍ، أَوْ لَمْسٍ، لَزِمَهُ الْقَضَاءُ لَا غَيْرُ. وَتُبَاحُ الْقُبْلَةُ لِلصَّائِمِ إِنْ أَمِنَ عَلَى نَفْسِهِ."]]},{"id":"tu32_3","label":"فَصْلٌ · ٣","segs":[["matn","وَلَوْ دَخَلَ حَلْقَهُ ذُبَابٌ، أَوْ غُبَارٌ، أَوْ دُخَانٌ، وَهُوَ ذَاكِرٌ لِصَوْمِهِ لَمْ يُفْطِرْ، بِخِلَافِ الْمَطَرِ وَالثَّلْجِ. وَلَوْ تَنَخَّعَ وَابْتَلَعَ مَا تَنَخَّعَ، أَوِ ابْتَلَعَ رِيقَهُ الْمَغْلُوبَ بِالدَّمِ، لَمْ يُفْطِرْ."]]},{"id":"tu32_4","label":"فَصْلٌ · ٤","segs":[["matn","وَإِنِ ابْتَلَعَ مَا بَيْنَ أَسْنَانِهِ مِنْ عَشَائِهِ دُونَ حِمَّصَةٍ، لَمْ يُفْطِرْ، إِلَّا إِذَا أَخْرَجَهُ ثُمَّ رَدَّهُ، وَبِقَدْرِ الْحِمَّصَةِ يُفْطِرُ وَلَا كَفَّارَةَ عَلَيْهِ."]]},{"id":"tu32_5","label":"فَصْلٌ · ٥","segs":[["matn","وَلَوِ ابْتَلَعَ سِمْسِمَةً لَزِمَتْهُ الْكَفَّارَةُ، وَإِنْ مَضَغَهَا لَمْ يُفْطِرْ إِلَّا أَنْ يَجِدَ طَعْمَهَا فِي حَلْقِهِ. وَلَوْ أَكَلَ عَجِينًا، أَوْ دَقِيقًا، أَوِ ابْتَلَعَ حَصَاةً، أَوْ نَحْوَهَا، لَزِمَهُ الْقَضَاءُ لَا غَيْرُ."]]},{"id":"tu32_6","label":"فَصْلٌ · ٦","segs":[["matn","وَلَوْ أَكَلَ مِسْكًا، أَوْ كَافُورًا، أَوْ زَعْفَرَانًا، أَوْ تُرَابًا مَشُوبًا، أَوْ وَرَقَ شَجَرٍ يُعْتَادُ أَكْلُهَا لَزِمَتْهُ الْكَفَّارَةُ."]]},{"id":"tu32_7","label":"فَصْلٌ · ٧","segs":[["matn","وَلَوْ مَضَغَ لُقْمَةً نَاسِيًا فَذَكَرَ فَابْتَلَعَهَا وَجَبَتِ الْكَفَّارَةُ، وَلَوْ أَخْرَجَهَا ثُمَّ ابْتَلَعَهَا لَمْ تَجِبْ. وَلَوْ أَفْطَرَ عَمْدًا، ثُمَّ مَرِضَ، أَوْ حَاضَتْ لَمْ تَجِبِ الْكَفَّارَةُ."]]},{"id":"tu32_8","label":"فَصْلٌ · ٨","segs":[["matn","وَلَوْ سَافَرَ طَائِعًا وَجَبَتْ. وَلِلْمَرِيضِ الْفِطْرُ يَوْمَ نَوْبَةِ حُمَّاهُ، وَلِلْمَرْأَةِ أَيْضًا يَوْمَ عَادَةِ حَيْضِهَا بِنَاءً عَلَى الْعَادَةِ، فَإِنْ أَفْطَرَ وَلَمْ يَأْتِ الْحُمَّى وَالْحَيْضُ، وَجَبَتِ الْكَفَّارَةُ."]]},{"id":"tu32_9","label":"فَصْلٌ · ٩","segs":[["matn","فَإِنْ غَلَبَهُ الْقَيْءُ لَمْ يُفْطِرْ مُطْلَقًا، وَإِنْ تَعَمَّدَ مِلْءَ فِيهِ أَفْطَرَ وَلَا كَفَّارَةَ. وَمَنْ أَكَلَ غِذَاءً، أَوْ شَرِبَ دَوَاءً، أَوْ جَامَعَ عَامِدًا فِي أَحَدِ السَّبِيلَيْنِ، لَزِمَتْهُ الْكَفَّارَةُ."]]},{"id":"tu32_10","label":"فَصْلٌ · ١٠","segs":[["matn","وَلَا كَفَّارَةَ بِالْجِمَاعِ فِيمَا دُونَ الْفَرْجِ وَلَوْ أَنْزَلَ. وَلَا كَفَّارَةَ عَلَى الْمَرْأَةِ لَوْ كَانَتْ نَائِمَةً، أَوْ مَجْنُونَةً، أَوْ مُكْرَهَةً. وَلَا كَفَّارَةَ فِي إِفْسَادِ صَوْمِ غَيْرِ رَمَضَانَ أَدَاءً."]]},{"id":"tu32_11","label":"فَصْلٌ · ١١","segs":[["matn","وَمَنِ احْتَقَنَ، أَوِ اسْتَعَطَ، أَوْ أَقْطَرَ فِي أُذُنِهِ دَوَاءً، أَوْ دُهْنًا، أَوْ دَاوَى جَائِفَةً، أَوْ آمَّةً بِدَوَاءٍ رَطْبٍ، لَزِمَهُ الْقَضَاءُ، لَا غَيْرُ."]]},{"id":"tu32_12","label":"فَصْلٌ · ١٢","segs":[["matn","وَإِنْ أَقْطَرَ فِي أُذُنِهِ مَاءً، أَوْ فِي ذَكَرِهِ دُهْنًا، لَمْ يُفْطِرْ. وَمَنْ ذَاقَ شَيْئًا وَمَجَّهُ لَمْ يُفْطِرْ. وَيُكْرَهُ لِلصَّائِمِ الذَّوْقُ، إِلَّا حَالَةَ الشِّرَاءِ."]]},{"id":"tu32_13","label":"فَصْلٌ · ١٣","segs":[["matn","وَيُكْرَهُ لِلْمَرْأَةِ مَضْغُ الطَّعَامِ لِوَلَدِهَا بِغَيْرِ ضَرُورَةٍ، وَمَضْغُ الْعِلْكِ مَكْرُوهٌ لِلصَّائِمِ، وَقِيلَ: يُفْسِدُ إِنْ كَانَ مُتَفَتِّتًا أَوْ أَسْوَدَ، وَلَا يُكْرَهُ لِلْمَرْأَةِ الْمُفْطِرَةِ، وَفِي الرَّجُلِ خِلَافٌ."]]},{"id":"tu32_14","label":"فَصْلٌ · ١٤","segs":[["matn","وَيُبَاحُ لِلصَّائِمِ الْكُحْلُ، وَلَوْ وَجَدَ طَعْمَهُ فِي حَلْقِهِ، وَدَهْنُ الشَّارِبِ إِذَا قَصَدَ بِهِمَا غَيْرَ زِينَةٍ، وَكَذَا لِلْمُفْطِرِ. وَلَا يُكْرَهُ السِّوَاكُ لِلصَّائِمِ بِمِسْوَاكٍ رَطْبٍ، أَوْ يَابِسٍ. وَلَا الْفَصْدُ، وَلَا الْحِجَامَةُ."]]}],"group":"كِتَابُ الصَّوْمِ"},{"id":"tu33","title":"فَصْلٌ","units":[{"id":"tu33_1","label":"فَصْلٌ · ١","segs":[["matn","الْمَرِيضُ إِذَا خَافَ شِدَّةَ مَرَضِهِ، أَوْ تَأَخُّرَ بُرْئِهِ أَفْطَرَ، وَقَضَى. وَالْمُسَافِرُ أَفْطَرَ مُطْلَقًا، وَصَوْمُهُ أَفْضَلُ، إِنْ لَمْ تَنَلْهُ مَشَقَّةٌ."]]},{"id":"tu33_2","label":"فَصْلٌ · ٢","segs":[["matn","فَإِنْ مَاتَا فِي السَّفَرِ وَالْمَرَضِ فَلَا قَضَاءَ عَلَيْهِمَا، وَإِنْ صَحَّ الْمَرِيضُ، أَوْ أَقَامَ الْمُسَافِرُ، ثُمَّ مَاتَا، وَجَبَ الْإِيصَاءُ بِقَدْرِ مَا أَدْرَكَا."]]},{"id":"tu33_3","label":"فَصْلٌ · ٣","segs":[["matn","وَقَضَاءُ رَمَضَانَ إِنْ شَاءَ فَرَّقَهُ، وَإِنْ شَاءَ تَابَعَهُ، وَالتَّتَابُعُ أَفْضَلُ، وَلَا فِدْيَةَ بِتَأْخِيرِهِ عَنْ رَمَضَانَ ثَانٍ. وَلِلْحَامِلِ وَالْمُرْضِعِ الْإِفْطَارُ خَوْفًا عَلَى وَلَدَيْهِمَا، أَوْ أَنْفُسِهِمَا، وَلَا فِدْيَةَ عَلَيْهِمَا."]]},{"id":"tu33_4","label":"فَصْلٌ · ٤","segs":[["matn","وَالشَّيْخُ الْعَاجِزُ عَنِ الصَّوْمِ يُفْطِرُ، وَيَفْدِي عَنْ كُلِّ يَوْمٍ نِصْفَ صَاعٍ مِنْ بُرٍّ، أَوْ صَاعًا مِنْ تَمْرٍ، أَوْ شَعِيرٍ. فَإِنْ قَدَرَ عَلَى الصَّوْمِ بَعْدَ الْفِدْيَةِ قَضَى."]]},{"id":"tu33_5","label":"فَصْلٌ · ٥","segs":[["matn","وَمَنْ أَوْصَى بِقَضَاءِ رَمَضَانَ أَطْعَمَ عَنْهُ وَلِيُّهُ كَمَا مَرَّ وَإِنْ لَمْ يُوصِ لَا يَجِبُ، وَالصَّلَاةُ كَالصَّوْمِ، وَكُلُّ صَلَاةٍ كَصَوْمِ يَوْمٍ، وَلَا يَصُومُ عَنْهُ وَلِيُّهُ، وَلَا يُصَلِّي."]]},{"id":"tu33_6","label":"فَصْلٌ · ٦","segs":[["matn","وَمَنْ أَسْلَمَ، أَوْ بَلَغَ، أَوْ طَهُرَتْ، أَوْ أَفَاقَ، أَوْ قَدِمَ مِنْ سَفَرٍ، أَوْ بَرِئَ مِنْ مَرَضٍ، أَوْ أَفْطَرَ خَطَأً، أَوْ عَمْدًا، أَمْسَكَ بَقِيَّةَ يَوْمِهِ، تَشَبُّهًا بِالصَّائِمِينَ، بِخِلَافِ الْحَائِضِ وَالنُّفَسَاءِ فِي حَالِ الصَّوْمِ، وَلَوْ أَكَلَ فَلَا قَضَاءَ عَلَيْهِ؛ لِتَرْكِ التَّشَبُّهِ."]]},{"id":"tu33_7","label":"فَصْلٌ · ٧","segs":[["matn","وَمَنْ سَافَرَ بَعْدَ الْفَجْرِ وَنَوَى الْفِطْرَ ثُمَّ قَدِمَ، أَوْ صَحَّ مِنْ مَرَضِهِ قَبْلَ الزَّوَالِ؛ لَزِمَهُ الصَّوْمُ، وَلَوْ أَفْطَرَ فَلَا كَفَّارَةَ عَلَيْهِ."]]},{"id":"tu33_8","label":"فَصْلٌ · ٨","segs":[["matn","وَإِذَا عَلِمَ الْمُسَافِرُ أَنَّهُ يَدْخُلُ فِي يَوْمِهِ مِصْرَهُ، أَوْ مَوْضِعَ إِقَامَتِهِ، كُرِهَ لَهُ الْفِطْرُ."]]},{"id":"tu33_9","label":"فَصْلٌ · ٩","segs":[["matn","وَمَنْ أُغْمِيَ عَلَيْهِ، أَوْ جُنَّ فِي رَمَضَانَ، قَضَى مَا بَعْدَ يَوْمِ الْإِغْمَاءِ وَالْجُنُونِ خَاصَّةً. وَالْجُنُونُ الْمُسْتَوْعِبُ مُسْقِطٌ لِلْقَضَاءِ، بِخِلَافِ الْإِغْمَاءِ، وَبِخِلَافِ الْجُنُونِ غَيْرِ الْمُسْتَوْعِبِ."]]},{"id":"tu33_10","label":"فَصْلٌ · ١٠","segs":[["matn","وَمَنْ لَمْ يَنْوِ فِي رَمَضَانَ صَوْمًا، وَلَا فِطْرًا، لَزِمَهُ الْقَضَاءُ، وَمَنْ أَصْبَحَ غَيْرَ نَاوٍ لِلصَّوْمِ، وَنَوَى قَبْلَ الزَّوَالِ، فَأَكَلَ، فَلَا كَفَّارَةَ عَلَيْهِ."]]},{"id":"tu33_11","label":"فَصْلٌ · ١١","segs":[["matn","وَالْحَائِضُ، وَالنُّفَسَاءُ، تُفْطِرُ وَتَقْضِي، بِخِلَافِ الصَّلَاةِ. وَمَنْ ظَنَّ بَقَاءَ اللَّيْلِ فَتَسَحَّرَ، أَوْ غُرُوبَ الشَّمْسِ فَأَفْطَرَ، وَبَانَ خَطَؤُهُ، لَزِمَهُ الْقَضَاءُ وَالتَّشَبُّهُ لَا غَيْرُ."]]},{"id":"tu33_12","label":"فَصْلٌ · ١٢","segs":[["matn","وَلَوْ شَكَّ فِي طُلُوعِ الْفَجْرِ، فَالْأَفْضَلُ أَنْ لَا يُفْطِرَ، وَلَوْ أَفْطَرَ فَلَا قَضَاءَ عَلَيْهِ. وَلَوْ شَكَّ فِي غُرُوبِ الشَّمْسِ، يَجِبُ أَنْ لَا يُفْطِرَ، وَلَوْ أَفْطَرَ لَزِمَهُ الْقَضَاءُ لَا غَيْرُ."]]},{"id":"tu33_13","label":"فَصْلٌ · ١٣","segs":[["matn","وَالسُّحُورُ مُسْتَحَبٌّ، وَكَذَا تَأْخِيرُهُ، وَيُسْتَحَبُّ تَعْجِيلُ الْإِفْطَارِ. وَمَنْ أَكَلَ نَاسِيًا، فَظَنَّ أَنَّهُ أَفْطَرَ، أَوْ عَلِمَ أَنَّهُ لَمْ يُفْطِرْ، فَأَكَلَ عَمْدًا، لَزِمَهُ الْقَضَاءُ لَا غَيْرُ."]]},{"id":"tu33_14","label":"فَصْلٌ · ١٤","segs":[["matn","وَيَحْرُمُ صَوْمُ يَوْمِ الْعِيدَيْنِ، وَأَيَّامِ التَّشْرِيقِ. وَلَا يُكْرَهُ صَوْمُ السِّتَّةِ مِنْ شَوَّالٍ مَوْصُولَةً بِرَمَضَانَ. وَيُكْرَهُ صَوْمُ الْوِصَالِ، فَإِنْ أَفْطَرَ فِي الْأَيَّامِ الْخَمْسَةِ الْمُحَرَّمَةِ فَقَوْلَانِ."]]},{"id":"tu33_15","label":"فَصْلٌ · ١٥","segs":[["matn","وَيُكْرَهُ صَوْمُ الصَّمْتِ، وَهُوَ: أَنْ لَا يَتَكَلَّمَ فِي صَوْمِهِ، وَيُكْرَهُ صَوْمُ يَوْمِ السَّبْتِ، أَوْ عَاشُورَاءَ وَحْدَهُ. وَيُسْتَحَبُّ صَوْمُ يَوْمِ الْخَمِيسِ، وَالْجُمُعَةِ، وَأَيَّامِ الْبِيضِ، وَيَوْمِ عَرَفَةَ لِغَيْرِ الْحَاجِّ."]]},{"id":"tu33_16","label":"فَصْلٌ · ١٦","segs":[["matn","وَلَا تَصُومُ الْمَرْأَةُ تَطَوُّعًا بِغَيْرِ إِذْنِ زَوْجِهَا، إِلَّا أَنْ يَكُونَ صَائِمًا، وَلَا الْعَبْدُ بِغَيْرِ إِذْنِ مَوْلَاهُ وَإِنْ كَانَ لَا يَضُرُّ بِمَوْلَاهُ."]]},{"id":"tu33_17","label":"فَصْلٌ · ١٧","segs":[["matn","وَكَفَّارَةُ صَوْمِ رَمَضَانَ: عِتْقُ رَقَبَةٍ، فَإِنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ، فَإِنْ عَجَزَ فَإِطْعَامُ سِتِّينَ مِسْكِينًا كَمَا مَرَّ، وَلَوْ أَفْطَرَ مِرَارًا فِي رَمَضَانَ، أَوْ رَمَضَانَيْنِ، كَفَتْهُ كَفَّارَةٌ وَاحِدَةٌ، إِلَّا إِذَا تَخَلَّلَتِ الْكَفَّارَةُ."]]},{"id":"tu33_18","label":"فَصْلٌ · ١٨","segs":[["matn","وَيُبَاحُ الْفِطْرُ فِي التَّطَوُّعِ بِعُذْرِ الضِّيَافَةِ، وَنَحْوِهَا. وَلَوْ شَرَعَ فِي صَوْمٍ، أَوْ صَلَاةٍ ظَنَّهَا عَلَيْهِ، ثُمَّ عَلِمَ انْتِفَاءَهَا، فَالْأَفْضَلُ الْإِتْمَامُ، وَلَوْ أَفْسَدَ فَلَا قَضَاءَ عَلَيْهِ. وَاللَّهُ أَعْلَمُ."]]}],"group":"كِتَابُ الصَّوْمِ"},{"id":"tu34","title":"كِتَابُ الْحَجِّ","units":[{"id":"tu34_1","label":"كِتَابُ الْحَجِّ · ١","segs":[["matn","هُوَ فَرْضٌ عَلَى الْفَوْرِ، مَرَّةً فِي الْعُمُرِ. عَلَى كُلِّ مُكَلَّفٍ، صَحِيحٍ، بَصِيرٍ، قَادِرٍ عَلَى زَادٍ وَرَاحِلَةٍ، غَيْرِ عُقْبَةٍ، وَنَفَقَةِ ذَهَابِهِ وَرُجُوعِهِ، فَاضِلًا عَمَّا لَا بُدَّ مِنْهُ لِعِيَالِهِ، إِلَى وَقْتِ رُجُوعِهِ، بِشَرْطِ أَمْنِ الطَّرِيقِ."]]},{"id":"tu34_2","label":"كِتَابُ الْحَجِّ · ٢","segs":[["matn","فَإِنْ بُذِلَ لَهُ ذَلِكَ، لَمْ يَجِبْ. وَلَوْ حَجَّ فَقِيرٌ وَقَعَ فَرْضًا. وَالْمَحْرَمُ، أَوِ الزَّوْجُ، شَرْطٌ فِي الْمَرْأَةِ إِذَا كَانَ سَفَرًا. وَنَفَقَةُ الْمَحْرَمِ عَلَيْهَا."]]},{"id":"tu34_3","label":"كِتَابُ الْحَجِّ · ٣","segs":[["matn","وَالْمَحْرَمُ الْعَبْدُ، وَالذِّمِّيُّ إِذَا كَانَ مَأْمُونًا كَالْحُرِّ الْمُسْلِمِ. وَلَا عِبْرَةَ بِصَبِيٍّ، أَوْ مَجْنُونٍ. وَلِلزَّوْجِ مَنْعُهَا مَعَ الْمَحْرَمِ عَنِ النَّفْلِ، وَالْمَنْذُورِ، لَا عَنِ الْفَرْضِ."]]},{"id":"tu34_4","label":"كِتَابُ الْحَجِّ · ٤","segs":[["matn","وَوَقْتُهُ: شَوَّالٌ، وَذُو الْقَعْدَةِ، وَعَشْرُ ذِي الْحِجَّةِ. وَيُكْرَهُ تَقْدِيمُ الْإِحْرَامِ عَلَى شَوَّالٍ. وَالْإِحْرَامُ شَرْطٌ أَيْضًا."]]},{"id":"tu34_5","label":"كِتَابُ الْحَجِّ · ٥","segs":[["matn","وَأَرْكَانُ الْحَجِّ: الْوُقُوفُ بِعَرَفَةَ، وَطَوَافُ الزِّيَارَةِ. وَوَاجِبَاتُهُ: الْوُقُوفُ بِمُزْدَلِفَةَ، وَالسَّعْيُ بَيْنَ الصَّفَا وَالْمَرْوَةِ، وَرَمْيُ الْجِمَارِ، وَالْحَلْقُ، أَوِ التَّقْصِيرُ، وَطَوَافُ الصَّدَرِ. وَرَكْعَتَا الطَّوَافِ."]]},{"id":"tu34_6","label":"كِتَابُ الْحَجِّ · ٦","segs":[["matn","وَسُنَنُهُ: طَوَافُ الْقُدُومِ، وَالرَّمَلُ فِيهِ، وَالْهَرْوَلَةُ فِي السَّعْيِ بَيْنَ الْمِيلَيْنِ الْأَخْضَرَيْنِ، وَالْمَبِيتُ بِمِنًى فِي أَيَّامِ مِنًى. وَالْعُمْرَةُ سُنَّةٌ مُؤَكَّدَةٌ. وَرُكْنُهَا: الطَّوَافُ. وَوَاجِبَاتُهَا: السَّعْيُ، وَالْحَلْقُ، أَوِ التَّقْصِيرُ."]]},{"id":"tu34_7","label":"كِتَابُ الْحَجِّ · ٧","segs":[["matn","وَمِيقَاتُ الْإِحْرَامِ لِلْمَدَنِيِّ: ذُو الْحُلَيْفَةِ، وَلِلْعِرَاقِيِّ: ذَاتُ عِرْقٍ، وَلِلشَّامِيِّ: الْجُحْفَةُ، وَلِلنَّجْدِيِّ: قَرْنٌ، وَلِلْيَمَانِيِّ: يَلَمْلَمُ. وَلِمَنْ جَاءَ مِنْ غَيْرِ هَذِهِ الْمَوَاضِعِ، مَا يُحَاذِي وَاحِدًا مِنْهَا."]]},{"id":"tu34_8","label":"كِتَابُ الْحَجِّ · ٨","segs":[["matn","وَالْإِحْرَامُ مِنْ وَطَنِهِ أَفْضَلُ، إِنْ وَثِقَ مِنْ نَفْسِهِ بِاجْتِنَابِ مَحْظُورَاتِهِ، وَلَا يَجُوزُ لِهَؤُلَاءِ إِذَا قَصَدُوا دُخُولَ مَكَّةَ لِحَجٍّ أَوْ غَيْرِهِ، تَأْخِيرُ الْإِحْرَامِ عَنْهَا."]]},{"id":"tu34_9","label":"كِتَابُ الْحَجِّ · ٩","segs":[["matn","وَأَهْلُ هَذِهِ الْمَوَاضِعِ وَمَنْ دُونَهُمْ مِيقَاتُهُمُ: الْحِلُّ الَّذِي بَيْنَهُمْ وَبَيْنَ الْحَرَمِ. وَلِلْمَكِّيِّ، مِيقَاتُهُ لِلْحَجِّ: الْحَرَمُ. وَلِلْعُمْرَةِ: الْحِلُّ أَفْضَلُ."]]}],"group":"كِتَابُ الْحَجِّ"},{"id":"tu35","title":"فَصْلٌ","units":[{"id":"tu35_1","label":"فَصْلٌ · ١","segs":[["matn","إِذَا أَرَادَ الْإِحْرَامَ: قَصَّ شَارِبَهُ، وَقَلَّمَ أَظْفَارَهُ، وَحَلَقَ عَانَتَهُ، ثُمَّ تَوَضَّأَ، أَوِ اغْتَسَلَ، وَهُوَ أَفْضَلُ، وَلَبِسَ إِزَارًا وَرِدَاءً، جَدِيدَيْنِ، أَبْيَضَيْنِ، وَهُوَ أَفْضَلُ، أَوْ غَسِيلَيْنِ، وَتَطَيَّبَ، وَادَّهَنَ إِنْ وَجَدَ، وَصَلَّى رَكْعَتَيْنِ، وَيَسْأَلُ اللَّهَ التَّيْسِيرَ، ثُمَّ لَبَّى نَاوِيًا نُسُكَهُ، رَافِعًا صَوْتَهُ."]]},{"id":"tu35_2","label":"فَصْلٌ · ٢","segs":[["matn","وَالتَّلْبِيَةُ مَعْرُوفَةٌ. وَهِيَ مَرَّةً شَرْطٌ، وَالزِّيَادَةُ سُنَّةٌ. وَيَتَّقِي الْمُحْرِمُ: الرَّفَثَ، وَالْفُسُوقَ، وَالْجِدَالَ، وَقَتْلَ صَيْدِ الْبَرِّ، وَالدَّلَالَةَ، وَالْإِشَارَةَ. وَيُبَاحُ لَهُ كُلُّ صَيْدِ الْبَحْرِ."]]},{"id":"tu35_3","label":"فَصْلٌ · ٣","segs":[["matn","وَيَتْرُكُ لُبْسَ الْمَخِيطِ، وَالْعِمَامَةِ، وَالْقَلَنْسُوَةِ، وَالْخُفَّيْنِ التَّامَّيْنِ، وَتَغْطِيَةَ الرَّأْسِ، وَالْوَجْهِ، وَالدُّهْنَ، وَالتَّطَيُّبَ، وَحَلْقَ الشَّعْرِ وَقَصَّهُ، وَقَصَّ الظُّفُرِ، وَلُبْسَ الْمَصْبُوغِ، إِلَّا مَغْسُولًا لَا يَنْفُضُ، وَلَا يَغْسِلُ شَعْرَهُ بِخِطْمِيٍّ، وَلَا بِسِدْرٍ، وَلَا يَحُكُّ رَأْسَهُ إِلَّا بِرِفْقٍ إِنْ كَانَ عَلَيْهِ شَعْرٌ."]]},{"id":"tu35_4","label":"فَصْلٌ · ٤","segs":[["matn","وَلَهُ أَنْ يَغْتَسِلَ، وَيَدْخُلَ الْحَمَّامَ، وَيَسْتَظِلَّ بِبَيْتٍ، أَوْ خَيْمَةٍ، أَوْ مَحْمِلٍ، وَيَشُدَّ الْهِمْيَانَ، وَيُكْثِرُ التَّلْبِيَةَ بِصَوْتٍ رَفِيعٍ بَعْدَ الصَّلَوَاتِ الْخَمْسِ، وَكُلَّمَا عَلَا شَرَفًا، أَوْ هَبَطَ وَادِيًا، أَوْ لَقِيَ رَكْبًا، وَبِالْأَسْحَارِ."]]},{"id":"tu35_5","label":"فَصْلٌ · ٥","segs":[["matn","فَإِذَا دَخَلَ مَكَّةَ، طَافَ لِلْقُدُومِ سَبْعَةَ أَشْوَاطٍ وَرَاءَ الْحَطِيمِ، يَرْمُلُ فِي الثَّلَاثَةِ الْأُوَلِ، ثُمَّ يُصَلِّي رَكْعَتَيْنِ عِنْدَ الْمَقَامِ."]]},{"id":"tu35_6","label":"فَصْلٌ · ٦","segs":[["matn","ثُمَّ سَعَى بَيْنَ الصَّفَا وَالْمَرْوَةِ سَبْعَةَ أَشْوَاطٍ، يُهَرْوِلُ فِيمَا بَيْنَ الْمِيلَيْنِ الْأَخْضَرَيْنِ، ثُمَّ يُقِيمُ بِمَكَّةَ حَرَامًا، يَطُوفُ مَا شَاءَ بِلَا رَمَلٍ وَلَا سَعْيٍ، وَيَخْتِمُ كُلَّ طَوَافٍ بِرَكْعَتَيْنِ،"]]},{"id":"tu35_7","label":"فَصْلٌ · ٧","segs":[["matn","ثُمَّ يَخْرُجُ غَدَاةَ التَّرْوِيَةِ إِلَى مِنًى، ثُمَّ يَتَوَجَّهُ إِلَى عَرَفَاتٍ فَإِذَا زَالَتِ الشَّمْسُ صَلَّى الْإِمَامُ بِالنَّاسِ الظُّهْرَ وَالْعَصْرَ فِي وَقْتِ الظُّهْرِ بِأَذَانٍ وَإِقَامَتَيْنِ،"]]},{"id":"tu35_8","label":"فَصْلٌ · ٨","segs":[["matn","وَلَا يَجْمَعُ الْمُنْفَرِدُ، وَالْإِمَامُ شَرْطٌ فِيهَا، ثُمَّ يَقِفُ الْإِمَامُ بِعَرَفَةَ رَاكِبًا بِقُرْبِ الْجَبَلِ، وَعَرَفَاتٌ كُلُّهَا مَوْقِفٌ إِلَّا بَطْنَ عُرَنَةَ، فَإِذَا غَرَبَتِ الشَّمْسُ، أَفَاضَ إِلَى مُزْدَلِفَةَ، وَوَقَفَ بِقُرْبِ قُزَحَ."]]},{"id":"tu35_9","label":"فَصْلٌ · ٩","segs":[["matn","وَمُزْدَلِفَةُ كُلُّهَا مَوْقِفٌ إِلَّا وَادِيَ مُحَسِّرٍ. وَيُصَلِّي بِالنَّاسِ الْمَغْرِبَ وَالْعِشَاءَ فِي وَقْتِ الْعِشَاءِ، بِأَذَانٍ وَإِقَامَةٍ وَاحِدَةٍ، وَلَا يَجْمَعُ الْمُنْفَرِدُ، وَمَنْ صَلَّى الْمَغْرِبَ فِي الطَّرِيقِ أَعَادَ، وَيَبِيتُ بِهَا، وَيُصَلِّي بِهِمُ الْفَجْرَ بِغَلَسٍ، ثُمَّ يَقِفُ بِالْمَشْعَرِ الْحَرَامِ وَيَدْعُو."]]},{"id":"tu35_10","label":"فَصْلٌ · ١٠","segs":[["matn","فَإِذَا أَسْفَرَ أَفَاضَ إِلَى مِنًى. فَيَرْمِي جَمْرَةَ الْعَقَبَةِ مِنْ بَطْنِ الْوَادِي بِسَبْعٍ، مِثْلَ حَصَى الْخَذْفِ. يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ، وَلَا يَقِفُ عِنْدَهَا."]]},{"id":"tu35_11","label":"فَصْلٌ · ١١","segs":[["matn","وَيَقْطَعُ التَّلْبِيَةَ مَعَ أَوَّلِ حَصَاةٍ، وَلَوْ رَمَى السَّبْعَ جُمْلَةً فَهِيَ وَاحِدَةٌ. وَيَجُوزُ الرَّمْيُ بِجِنْسِ الْأَرْضِ، لَا بِالذَّهَبِ، وَالْفِضَّةِ."]]},{"id":"tu35_12","label":"فَصْلٌ · ١٢","segs":[["matn","ثُمَّ يَذْبَحُ إِنْ شَاءَ، ثُمَّ يَحْلِقُ رُبُعَ رَأْسِهِ، وَهُوَ أَفْضَلُ، أَوْ يُقَصِّرُ، وَيَحِلُّ لَهُ كُلُّ شَيْءٍ إِلَّا النِّسَاءَ. ثُمَّ يَطُوفُ طَوَافَ الزِّيَارَةِ."]]},{"id":"tu35_13","label":"فَصْلٌ · ١٣","segs":[["matn","وَوَقْتُهُ: أَيَّامُ النَّحْرِ. وَأَفْضَلُهَا أَوَّلُهَا، وَيَحِلُّ لَهُ النِّسَاءُ. ثُمَّ يَعُودُ إِلَى مِنًى، وَيَرْمِي الْجِمَارَ الثَّلَاثَ بَعْدَ الزَّوَالِ فِي الْيَوْمِ الثَّانِي، وَالثَّالِثِ، وَالرَّابِعِ."]]},{"id":"tu35_14","label":"فَصْلٌ · ١٤","segs":[["matn","فَإِذَا أَرَادَ الرُّجُوعَ إِلَى بَلَدِهِ، طَافَ طَوَافَ الصَّدَرِ. وَمَنْ وَقَفَ بِعَرَفَةَ لَحْظَةً، مَا بَيْنَ الزَّوَالِ يَوْمَ عَرَفَةَ، وَفَجْرِ يَوْمِ النَّحْرِ أَجْزَأَهُ، وَلَوْ كَانَ نَائِمًا، أَوْ مُغْمًى عَلَيْهِ، أَوْ جَاهِلًا بِهَا."]]},{"id":"tu35_15","label":"فَصْلٌ · ١٥","segs":[["matn","وَالْمَرْأَةُ فِي أَفْعَالِ الْحَجِّ كَالرَّجُلِ، إِلَّا فِي كَشْفِ الرَّأْسِ، وَلُبْسِ الْمَخِيطِ، وَرَفْعِ الصَّوْتِ بِالتَّلْبِيَةِ، وَالرَّمَلِ، وَالْهَرْوَلَةِ، وَالْحَلْقِ، فَإِنَّهَا تُخَالِفُهُ فِيهَا."]]}],"group":"كِتَابُ الْحَجِّ"},{"id":"tu36","title":"فَصْلٌ","units":[{"id":"tu36_1","label":"فَصْلٌ · ١","segs":[["matn","الْقِرَانُ أَفْضَلُ مِنَ التَّمَتُّعِ، وَالْإِفْرَادِ. وَصِفَتُهُ: أَنْ يُهِلَّ بِالْعُمْرَةِ وَالْحَجِّ مَعًا مِنَ الْمِيقَاتِ، فَإِذَا دَخَلَ مَكَّةَ بَدَأَ بِالْعُمْرَةِ، ثُمَّ بِالْحَجِّ،"]]},{"id":"tu36_2","label":"فَصْلٌ · ٢","segs":[["matn","فَإِذَا رَمَى الْجَمْرَةَ يَوْمَ النَّحْرِ، أَرَاقَ دَمًا إِنْ قَدَرَ، وَإِلَّا صَامَ ثَلَاثَةَ أَيَّامٍ، آخِرُهَا يَوْمُ عَرَفَةَ، وَسَبْعَةَ أَيَّامٍ إِذَا رَجَعَ. وَالتَّمَتُّعُ أَفْضَلُ مِنَ الْإِفْرَادِ."]]},{"id":"tu36_3","label":"فَصْلٌ · ٣","segs":[["matn","وَصِفَتُهُ: أَنْ يُهِلَّ بِالْعُمْرَةِ مِنَ الْمِيقَاتِ، فَإِذَا دَخَلَ مَكَّةَ أَدَّى الْعُمْرَةَ وَحَلَّ مِنْهَا، ثُمَّ يُحْرِمُ بِالْحَجِّ يَوْمَ التَّرْوِيَةِ مِنَ الْحَرَمِ، وَيَفْعَلُ مَا يَفْعَلُهُ الْمُفْرِدُ، وَعَلَيْهِ الدَّمُ، أَوْ بَدَلُهُ كَالْقَارِنِ."]]}],"group":"كِتَابُ الْحَجِّ"},{"id":"tu37","title":"فَصْلٌ","units":[{"id":"tu37_1","label":"فَصْلٌ · ١","segs":[["matn","إِذَا طَيَّبَ الْمُحْرِمُ عُضْوًا، لَزِمَهُ دَمُ شَاةٍ، وَإِنْ كَانَ أَقَلَّ لَزِمَهُ صَدَقَةٌ. أَيْ: نِصْفُ صَاعٍ مِنْ بُرٍّ."]]},{"id":"tu37_2","label":"فَصْلٌ · ٢","segs":[["matn","وَإِنْ خَضَبَ رَأْسَهُ بِحِنَّاءٍ، لَزِمَهُ دَمٌ، وَإِنْ لَبَّدَهُ لَزِمَهُ دَمَانِ، وَإِنِ ادَّهَنَ بِزَيْتٍ، أَوْ لَبِسَ مَخِيطًا يَوْمًا، أَوْ غَطَّى رَأْسَهُ يَوْمًا، أَوْ حَلَقَ رُبُعَ رَأْسِهِ، أَوْ رُبُعَ لِحْيَتِهِ، أَوْ كُلَّ رَقَبَتِهِ، أَوْ أَحَدَ إِبْطَيْهِ، لَزِمَهُ دَمٌ."]]},{"id":"tu37_3","label":"فَصْلٌ · ٣","segs":[["matn","وَإِنْ كَانَ أَقَلَّ فِي الْكُلِّ، لَزِمَهُ صَدَقَةٌ. وَإِنْ قَصَّ مِنْ شَارِبِهِ شَيْئًا، فَعَلَيْهِ حُكُومَةُ عَدْلٍ. وَإِنْ حَلَقَ مَوَاضِعَ الْمَحَاجِمِ، أَوْ قَصَّ فِي مَجْلِسٍ كُلَّ أَظْفَارِهِ، أَوْ رُبُعَهَا، لَزِمَهُ دَمٌ."]]},{"id":"tu37_4","label":"فَصْلٌ · ٤","segs":[["matn","وَإِنْ قَصَّ الْكُلَّ فِي أَرْبَعَةِ مَجَالِسَ، لَزِمَهُ أَرْبَعَةُ دِمَاءٍ. وَإِنْ قَصَّ أَقَلَّ مِنْ خَمْسَةٍ مُجْتَمِعَةٍ، أَوْ خَمْسَةٍ مُتَفَرِّقَةٍ، لَزِمَهُ لِكُلِّ ظُفْرٍ صَدَقَةٌ."]]},{"id":"tu37_5","label":"فَصْلٌ · ٥","segs":[["matn","وَإِنْ تَطَيَّبَ، أَوْ لَبِسَ، أَوْ حَلَقَ بِعُذْرٍ، يُخَيَّرُ بَيْنَ دَمٍ، أَوْ ثَلَاثَةِ أَصْوُعٍ مِنْ بُرٍّ، يُطْعِمُهَا لِسِتَّةِ مَسَاكِينَ، أَوْ صَوْمِ ثَلَاثَةِ أَيَّامٍ."]]},{"id":"tu37_6","label":"فَصْلٌ · ٦","segs":[["matn","وَإِنْ قَبَّلَ، أَوْ لَمَسَ بِشَهْوَةٍ، لَزِمَهُ دَمٌ. وَإِنْ جَامَعَ قَبْلَ الْوُقُوفِ بِعَرَفَةَ، فَسَدَ حَجُّهُ، وَعَلَيْهِ شَاةٌ، وَيُتِمُّهُ، وَيَقْضِيهِ، وَلَا يُفَارِقُ امْرَأَتَهُ فِي الْقَضَاءِ."]]},{"id":"tu37_7","label":"فَصْلٌ · ٧","segs":[["matn","وَإِنْ جَامَعَ بَعْدَ الْوُقُوفِ، لَمْ يَفْسُدْ حَجُّهُ، وَعَلَيْهِ بَدَنَةٌ. وَإِنْ جَامَعَ بَعْدَ الْحَلْقِ، فَعَلَيْهِ شَاةٌ. وَجِمَاعُ النَّاسِي، وَالْعَامِدِ سَوَاءٌ. وَمَنْ طَافَ لِلْقُدُومِ، أَوْ لِلصَّدَرِ مُحْدِثًا، فَعَلَيْهِ صَدَقَةٌ."]]},{"id":"tu37_8","label":"فَصْلٌ · ٨","segs":[["matn","وَإِنْ طَافَ جُنُبًا، فَعَلَيْهِ شَاةٌ. وَمَنْ طَافَ لِلزِّيَارَةِ مُحْدِثًا، فَعَلَيْهِ شَاةٌ. وَإِنْ طَافَ جُنُبًا، فَعَلَيْهِ بَدَنَةٌ. وَمَنْ تَرَكَ مِنْ طَوَافِ الزِّيَارَةِ ثَلَاثَةَ أَشْوَاطٍ فَمَا دُونَهَا، فَعَلَيْهِ شَاةٌ."]]},{"id":"tu37_9","label":"فَصْلٌ · ٩","segs":[["matn","وَإِنْ تَرَكَ أَرْبَعَةً، فَهُوَ مُحْرِمٌ أَبَدًا حَتَّى يَطُوفَهَا، وَمَنْ تَرَكَ مِنْ طَوَافِ الصَّدَرِ ثَلَاثَةَ أَشْوَاطٍ، فَعَلَيْهِ صَدَقَةٌ. وَإِنْ تَرَكَ أَرْبَعَةً فَعَلَيْهِ دَمٌ."]]},{"id":"tu37_10","label":"فَصْلٌ · ١٠","segs":[["matn","وَمَنْ تَرَكَ السَّعْيَ، أَوْ أَفَاضَ مِنْ عَرَفَةَ قَبْلَ الْإِمَامِ، أَوْ تَرَكَ الْوُقُوفَ بِمُزْدَلِفَةَ، أَوْ رَمْيَ كُلِّ الْجِمَارِ، أَوْ رَمْيَ وَظِيفَةِ يَوْمٍ، أَوْ أَكْثَرِهَا، لَزِمَهُ دَمٌ، فَإِنْ كَانَ أَقَلَّ لَزِمَهُ صَدَقَةٌ."]]},{"id":"tu37_11","label":"فَصْلٌ · ١١","segs":[["matn","وَمَنْ أَخَّرَ الْحَلْقَ، أَوْ طَوَافَ الزِّيَارَةِ عَنْ وَقْتِهِ، لَزِمَهُ دَمٌ، وَكَذَلِكَ الْحَلْقُ فِي وَقْتِهِ خَارِجَ الْحَرَمِ."]]}],"group":"كِتَابُ الْحَجِّ"},{"id":"tu38","title":"فَصْلٌ","units":[{"id":"tu38_1","label":"فَصْلٌ · ١","segs":[["matn","مُحْرِمٌ قَتَلَ صَيْدًا، أَوْ سَبُعًا غَيْرَ صَائِلٍ، عَمْدًا، أَوْ سَهْوًا، أَوْ عَوْدًا، أَوْ بَدْءًا، أَوْ دَلَّ عَلَيْهِ مَنْ قَتَلَهُ. فَعَلَيْهِ قِيمَتُهُ بِقَوْلِ عَدْلَيْنِ، وَيُخَيَّرُ فِيهَا بَيْنَ الْهَدْيِ، وَالطَّعَامِ، وَالصِّيَامِ."]]},{"id":"tu38_2","label":"فَصْلٌ · ٢","segs":[["matn","وَلَوْ عَيَّبَ الصَّيْدَ، ضَمِنَ نُقْصَانَهُ. وَلَوْ أَزَالَ امْتِنَاعَهُ، ضَمِنَ كُلَّ الْقِيمَةِ وَلَوْ كَسَرَ بَيْضَ صَيْدٍ، ضَمِنَهُ، وَضَمِنَ فَرْخَهُ الْمَيِّتَ إِنْ خَرَجَ مِنْهُ."]]},{"id":"tu38_3","label":"فَصْلٌ · ٣","segs":[["matn","وَلَا شَيْءَ فِي قَتْلِ الْغُرَابِ الْمُؤْذِي، وَالْحِدَأَةِ، وَالْحَيَّةِ، وَالْعَقْرَبِ، وَالْفَأْرَةِ، وَالْكَلْبِ الْعَقُورِ، وَالذِّئْبِ، وَالنَّمْلِ، وَالْبَرَاغِيثِ، وَالْقُرَادِ، وَالْبَقِّ، وَالذُّبَابِ."]]},{"id":"tu38_4","label":"فَصْلٌ · ٤","segs":[["matn","وَمَنْ قَتَلَ قَمْلَةً، أَوْ جَرَادَةً، تَصَدَّقَ بِكَفٍّ مِنْ طَعَامٍ، أَوْ بِتَمْرَةٍ. وَيَجِبُ الْجَزَاءُ بِأَكْلِ الصَّيْدِ مُضْطَرًّا. وَيَحِلُّ لِلْمُحْرِمِ ذَبْحُ غَيْرِ الصَّيْدِ، وَالْحَمَامُ الْمُسَرْوَلُ، وَالظَّبْيُ الْمُسْتَأْنَسُ، صَيْدٌ، بِخِلَافِ الْبَعِيرِ النَّادِّ."]]},{"id":"tu38_5","label":"فَصْلٌ · ٥","segs":[["matn","وَيَحِلُّ لِلْمُحْرِمِ لَحْمُ صَيْدٍ اصْطَادَهُ حَلَالٌ، وَذَبَحَهُ بِلَا وَاسِطَةِ مُحْرِمٍ. وَفِي صَيْدِ الْحَرَمِ إِذَا ذَبَحَهُ الْحَلَالُ، قِيمَتُهُ يَتَصَدَّقُ بِهَا، لَا غَيْرُ."]]},{"id":"tu38_6","label":"فَصْلٌ · ٦","segs":[["matn","وَكَذَا فِي حَشِيشِهِ، وَشَجَرِهِ، غَيْرِ الْمَمْلُوكِ، وَالْمُنْبَتِ عَادَةً، مَا لَمْ يَجِفَّ وَلَا يُرْعَى حَشِيشُ الْحَرَمِ، وَلَا يُقْطَعُ مِنْهُ غَيْرُ الْإِذْخِرِ، وَيَحِلُّ قَلْعُ الْكَمْأَةِ."]]},{"id":"tu38_7","label":"فَصْلٌ · ٧","segs":[["matn","وَمَا يُوجِبُ عَلَى الْمُفْرِدِ دَمًا، يُوجِبُ عَلَى الْقَارِنِ دَمَيْنِ. وَلَوْ قَتَلَ مُحْرِمَانِ صَيْدًا. فَعَلَى كُلِّ وَاحِدٍ مِنْهُمَا جَزَاءٌ. وَلَوْ قَتَلَ حَلَالَانِ صَيْدَ الْحَرَمِ، فَعَلَيْهِمَا جَزَاءٌ وَاحِدٌ. وَبَيْعُ الْمُحْرِمِ الصَّيْدَ، وَشِرَاؤُهُ بَاطِلٌ."]]}],"group":"كِتَابُ الْحَجِّ"},{"id":"tu39","title":"فَصْلٌ","units":[{"id":"tu39_1","label":"فَصْلٌ · ١","segs":[["matn","مُحْرِمٌ مَنَعَهُ عَدُوٌّ، أَوْ مَرَضٌ، جَازَ لَهُ التَّحَلُّلُ بِبَعْثِ شَاةٍ تُذْبَحُ فِي يَوْمٍ يُعْلِمُهُ؛ لِيَتَحَلَّلَ بَعْدَ الذَّبْحِ. وَيَتَوَقَّتُ دَمُ الْإِحْصَارِ بِالْحَرَمِ، لَا بِيَوْمِ النَّحْرِ."]]},{"id":"tu39_2","label":"فَصْلٌ · ٢","segs":[["matn","بِخِلَافِ دَمِ الْمُتْعَةِ، وَالْقِرَانِ. وَالْمُحْصَرُ بِالْحَجِّ إِذَا تَحَلَّلَ، فَعَلَيْهِ حَجَّةٌ، وَعُمْرَةٌ. وَعَلَى الْمُحْصَرِ بِالْعُمْرَةِ: الْقَضَاءُ. وَعَلَى الْقَارِنِ: حَجَّةٌ، وَعُمْرَتَانِ."]]},{"id":"tu39_3","label":"فَصْلٌ · ٣","segs":[["matn","وَلَوْ زَالَ الْإِحْصَارُ قَبْلَ الذَّبْحِ، فَإِنْ قَدَرَ عَلَى إِدْرَاكِ الْهَدْيِ، وَالْحَجِّ لَزِمَهُ التَّوَجُّهُ، وَإِلَّا فَلَا. وَمَنْ قَدَرَ عَلَى الْوُقُوفِ، أَوِ الطَّوَافِ، أَوْ مُنِعَ بَعْدَ الْوُقُوفِ، فَلَيْسَ بِمُحْصَرٍ."]]},{"id":"tu39_4","label":"فَصْلٌ · ٤","segs":[["matn","وَمَنْ فَاتَهُ الْوُقُوفُ، حَتَّى طَلَعَ الْفَجْرُ يَوْمَ النَّحْرِ فَقَدْ فَاتَهُ الْحَجُّ فَيَتَحَلَّلُ بِعُمْرَةٍ وَيَقْضِي الْحَجَّ وَلَا دَمَ عَلَيْهِ."]]},{"id":"tu39_5","label":"فَصْلٌ · ٥","segs":[["matn","وَالْعُمْرَةُ لَا تَفُوتُ. وَهِيَ جَائِزَةٌ فِي كُلِّ وَقْتٍ، إِلَّا يَوْمَ عَرَفَةَ، وَيَوْمَ النَّحْرِ، وَأَيَّامَ التَّشْرِيقِ، وَهِيَ سُنَّةٌ."]]},{"id":"tu39_6","label":"فَصْلٌ · ٦","segs":[["matn","وَتَجُوزُ النِّيَابَةُ فِي نَفْلِ الْحَجِّ مُطْلَقًا، وَفِي فَرْضِهِ عِنْدَ الْعَجْزِ الدَّائِمِ إِلَى الْمَوْتِ، وَدَمُ الْقِرَانِ عَلَى الْمَأْمُورِ، وَدَمُ الْإِحْصَارِ عَلَى الْآمِرِ. وَالْهَدْيُ: مِنَ الْإِبِلِ، وَالْبَقَرِ، وَالْغَنَمِ."]]},{"id":"tu39_7","label":"فَصْلٌ · ٧","segs":[["matn","وَالْعَيْبُ مَانِعٌ كَالْأُضْحِيَّةِ. وَيَجُوزُ الْأَكْلُ مِنْ هَدْيِ التَّطَوُّعِ، وَالْمُتْعَةِ، وَالْقِرَانِ خَاصَّةً. وَيَتَوَقَّتُ دَمُ الْمُتْعَةِ، وَالْقِرَانِ خَاصَّةً، بِيَوْمِ النَّحْرِ، وَيَجُوزُ التَّصَدُّقُ بِهَا عَلَى مَسَاكِينِ الْحَرَمِ، وَغَيْرِهِمْ. وَاللَّهُ أَعْلَمُ."]]}],"group":"كِتَابُ الْحَجِّ"},{"id":"tu40","title":"كِتَابُ الْجِهَادِ","units":[{"id":"tu40_1","label":"كِتَابُ الْجِهَادِ · ١","segs":[["matn","هُوَ فَرْضُ كِفَايَةٍ، وَإِنْ لَمْ يَبْدَأِ الْكُفَّارُ. وَلَا جِهَادَ عَلَى عَبْدٍ، وَامْرَأَةٍ، وَأَعْمَى، وَمُقْعَدٍ، وَأَقْطَعَ، إِلَّا إِذَا هَجَمَ الْعَدُوُّ."]]},{"id":"tu40_2","label":"كِتَابُ الْجِهَادِ · ٢","segs":[["matn","وَيُقَدَّمُ طَلَبُ الْإِسْلَامِ، ثُمَّ الْجِزْيَةِ، فَإِنْ أَبَوْهُمَا قُوتِلُوا بِالسِّلَاحِ، وَالْمَنْجَنِيقِ، وَالْمَاءِ، وَالنَّارِ، وَقَطْعِ الشَّجَرِ، وَإِفْسَادِ الزَّرْعِ. وَيُرْمَوْنَ مَقْصُودِينَ، وَلَوْ تَتَرَّسُوا بِالْمُسْلِمِينَ."]]},{"id":"tu40_3","label":"كِتَابُ الْجِهَادِ · ٣","segs":[["matn","وَيُكْرَهُ إِخْرَاجُ النِّسَاءِ، وَالْمَصَاحِفِ إِنْ خِيفَ عَلَيْهِمَا. وَيَحْرُمُ الْغُلُولُ، وَالْمُثْلَةُ، وَالْغَدْرُ، وَقَتْلُ الْمَجْنُونِ، وَالصَّبِيِّ، وَالْمَرْأَةِ غَيْرِ الْمَلِكَةِ، وَالْهَرِمِ، وَالْأَعْمَى، وَالْمُقْعَدِ، وَنَحْوِهِمْ، إِلَّا دَفْعًا لِشَرِّ قِتَالِهِ، أَوْ رَأْيِهِ."]]},{"id":"tu40_4","label":"كِتَابُ الْجِهَادِ · ٤","segs":[["matn","وَيُكْرَهُ لِلْمُسْلِمِ قَتْلُ أَبِيهِ الْكَافِرِ، إِلَّا دَفْعًا كَالْمُسْلِمِ. وَلِلْإِمَامِ الصُّلْحُ مَجَّانًا، وَبِمَالٍ، أَخْذًا، أَوْ دَفْعًا، وَنَقْضُهُ بَعْدَ الْإِعْلَامِ مَتَى رَآهُ مَصْلَحَةً، وَإِنْ بَدَؤُوا بِخِيَانَةٍ لَمْ يَجِبِ الْإِعْلَامُ."]]},{"id":"tu40_5","label":"كِتَابُ الْجِهَادِ · ٥","segs":[["matn","وَيُكْرَهُ بَيْعُ السِّلَاحِ، وَالْحَدِيدِ، وَالْخَيْلِ مِنْهُمْ، وَلَوْ كَانُوا سِلْمًا بِخِلَافِ الطَّعَامِ، وَاللِّبَاسِ وَإِذَا أَمَّنَهُمْ حُرٌّ صَحَّ، وَلَزِمَ، إِلَّا أَنْ يَرَى الْإِمَامُ نَقْضَهُ."]]},{"id":"tu40_6","label":"كِتَابُ الْجِهَادِ · ٦","segs":[["matn","وَلَا يَصِحُّ أَمَانُ ذِمِّيٍّ، وَأَسِيرٍ، وَتَاجِرٍ، وَمُسْلِمٍ غَيْرِ مُهَاجِرٍ، وَعَبْدٍ غَيْرِ مَأْذُونٍ فِي الْقِتَالِ."]]}],"group":"كِتَابُ الْجِهَادِ"},{"id":"tu41","title":"فَصْلٌ","units":[{"id":"tu41_1","label":"فَصْلٌ · ١","segs":[["matn","وَإِذَا فَتَحَ الْإِمَامُ بَلَدًا قَهْرًا، فَلَهُ الْخِيَارُ فِي قِسْمَتِهِ بَيْنَ الْغَانِمِينَ، وَإِبْقَائِهِ عَلَيْهِمْ بِالْجِزْيَةِ وَالْخَرَاجِ، وَلَهُ الْخِيَارُ أَيْضًا فِي قَتْلِ الْأَسْرَى إِنْ لَمْ يُسْلِمُوا، وَاسْتِرْقَاقِهِمْ وَلَوْ أَسْلَمُوا، وَجَعْلِهِمْ ذِمَّةً، وَلَا يُطْلِقُهُمْ بِمَالٍ وَلَا يُفَادِي بِهِمْ أَسْرَانَا."]]},{"id":"tu41_2","label":"فَصْلٌ · ٢","segs":[["matn","وَإِنْ تَعَذَّرَ نَقْلُ مَوَاشِيهِمْ ذَبَحَهَا، وَحَرَّقَهَا، لَا غَيْرُ. وَحَرَّقَ الْأَسْلِحَةَ، وَمَا لَا يَحْتَرِقُ يَدْفِنُهُ. وَلَا يَقْسِمُ غَنِيمَةً فِي دَارِ الْحَرْبِ إِلَّا لِلْإِيدَاعِ، وَالرِّدْءُ فِي الْغَنِيمَةِ كَالْمُقَاتِلِ، بِخِلَافِ السُّوقِيِّ."]]},{"id":"tu41_3","label":"فَصْلٌ · ٣","segs":[["matn","وَالْمَدَدُ قَبْلَ إِخْرَاجِ الْغَنِيمَةِ إِلَى دَارِ الْإِسْلَامِ كَالْأَصْلِ، وَمَنْ مَاتَ قَبْلَ إِخْرَاجِ الْغَنِيمَةِ سَقَطَ حَقُّهُ، وَبَعْدَهُ لَا يَسْقُطُ."]]},{"id":"tu41_4","label":"فَصْلٌ · ٤","segs":[["matn","وَلِلْعَسْكَرِ الِانْتِفَاعُ بِالْغَنِيمَةِ قَبْلَ الْإِخْرَاجِ، أَكْلًا، وَعَلْفًا، وَدَهْنًا، وَإِيقَادًا، وَقِتَالًا بِسِلَاحٍ وَنَحْوِهَا بِلَا قِسْمَةٍ، مِنْ غَيْرِ بَيْعٍ، وَتَمَوُّلٍ."]]},{"id":"tu41_5","label":"فَصْلٌ · ٥","segs":[["matn","بِخِلَافِ الثِّيَابِ، وَالدَّوَابِّ، وَبَعْدَ الْإِخْرَاجِ يَرُدُّونَ مَا فَضَلَ مَعَهُمْ مِنْ ذَلِكَ. وَخُمْسُ الْغَنِيمَةِ يُقْسَمُ أَثْلَاثًا بَيْنَ الْيَتَامَى، وَالْمَسَاكِينِ، وَابْنِ السَّبِيلِ، يُقَدَّمُ مِنْهُمْ فُقَرَاءُ ذَوِي الْقُرْبَى خَاصَّةً."]]},{"id":"tu41_6","label":"فَصْلٌ · ٦","segs":[["matn","وَذِكْرُ اللَّهِ تَعَالَى فِي الْخُمُسِ؛ لِلتَّبَرُّكِ بِاسْمِهِ. وَسَهْمُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَقَطَ بِمَوْتِهِ، كَالصَّفِيِّ. وَأَرْبَعَةُ الْأَخْمَاسِ بَيْنَ الْغَانِمِينَ، لِلْفَارِسِ سَهْمَانِ، وَلِلرَّاجِلِ سَهْمٌ."]]},{"id":"tu41_7","label":"فَصْلٌ · ٧","segs":[["matn","وَالْبِرْذَوْنُ وَالْعَرَبِيُّ سَوَاءٌ. وَلَا سَهْمَ لِبَعِيرٍ، وَبَغْلٍ. وَيُعْتَبَرُ كَوْنُهُ فَارِسًا، أَوْ رَاجِلًا عِنْدَ مُجَاوَزَةِ الدَّرْبِ، لَا عِنْدَ الْقِتَالِ."]]},{"id":"tu41_8","label":"فَصْلٌ · ٨","segs":[["matn","وَيَرْضَخُ الْإِمَامُ لِلْعَبْدِ، وَالصَّبِيِّ، وَالْمَرْأَةِ، وَالذِّمِّيِّ مَا يَرَاهُ. وَلَا يُخَمَّسُ مَا أَخَذَهُ وَاحِدٌ، أَوِ اثْنَانِ، مُغِيرَيْنِ؛ بَلْ مَا أَخَذَهُ جَمَاعَةٌ لَهَا مَنْعَةٌ."]]},{"id":"tu41_9","label":"فَصْلٌ · ٩","segs":[["matn","وَيَجُوزُ التَّنْفِيلُ بِالسَّلَبِ، وَغَيْرِهِ، تَحْرِيضًا عَلَى الْقِتَالِ. وَالتُّرْكُ، وَالرُّومُ، يَمْلِكُ كُلُّ طَائِفَةٍ مِنْهُمْ مَا اسْتَوْلَتْ عَلَيْهِ مِنْ نُفُوسِ الطَّائِفَةِ الْأُخْرَى، وَأَمْوَالِهَا."]]},{"id":"tu41_10","label":"فَصْلٌ · ١٠","segs":[["matn","وَيَمْلِكُ الْكُفَّارُ كُلُّهُمْ أَمْوَالَنَا بِالِاسْتِيلَاءِ، لَا نُفُوسَنَا إِلَّا خَالِصَ رَقِيقِنَا. وَالْمَالِكُ الْقَدِيمُ، أَحَقُّ بِمَالِهِ قَبْلَ الْقِسْمَةِ مَجَّانًا، وَبَعْدَهَا بِالْقِيمَةِ، أَوْ بِالثَّمَنِ إِنْ كَانَ مُشْتَرِيًا."]]},{"id":"tu41_11","label":"فَصْلٌ · ١١","segs":[["matn","مُسْلِمٌ دَخَلَ دَارَ الْحَرْبِ تَاجِرًا يَحْرُمُ عَلَيْهِ الْخِيَانَةُ، وَالْغَدْرُ بِهِمْ، فَإِنْ خَانَ فِي شَيْءٍ وَأَخْرَجَهُ، تَصَدَّقَ بِهِ."]]},{"id":"tu41_12","label":"فَصْلٌ · ١٢","segs":[["matn","وَلَوْ دَخَلَ حَرْبِيٌّ إِلَيْنَا بِأَمَانٍ، يُقَالُ لَهُ: إِنْ أَقَمْتَ سَنَةً جُعِلْتَ ذِمِّيًّا، فَإِنْ أَقَامَ سَنَةً صَارَ ذِمِّيًّا، فَلَا يُمَكَّنُ مِنَ الرُّجُوعِ."]]},{"id":"tu41_13","label":"فَصْلٌ · ١٣","segs":[["matn","وَالْجِزْيَةُ عَلَى الْغَنِيِّ كُلَّ سَنَةٍ: ثَمَانِيَةٌ وَأَرْبَعُونَ دِرْهَمًا، وَعَلَى وَسَطِ الْحَالِ: أَرْبَعَةٌ وَعِشْرُونَ، وَعَلَى الْفَقِيرِ الْمُعْتَمِلِ اثْنَا عَشَرَ. وَتُوضَعُ الْجِزْيَةُ عَلَى الْكِتَابِيِّ، وَالْمَجُوسِيِّ، وَعَابِدِ الْوَثَنِ مِنَ الْعَجَمِ."]]},{"id":"tu41_14","label":"فَصْلٌ · ١٤","segs":[["matn","وَلَا تُوضَعُ عَلَى عَابِدِ الْوَثَنِ مِنَ الْعَرَبِ، وَلَا الْمُرْتَدِّ، وَلَا جِزْيَةَ عَلَى مَنْ لَا يُقْتَلُ. وَتُؤْخَذُ مِنَ الْقِسِّيسِينَ، وَالرُّهْبَانِ، وَأَصْحَابِ الصَّوَامِعِ الْمُعْتَمِلِينَ."]]},{"id":"tu41_15","label":"فَصْلٌ · ١٥","segs":[["matn","وَمَنْ أَسْلَمَ، أَوْ مَاتَ وَعَلَيْهِ جِزْيَةٌ، سَقَطَتْ. وَإِنِ اجْتَمَعَتْ جِزْيَتَانِ تَدَاخَلَتَا. وَيُكَلَّفُ الذِّمِّيُّ إِحْضَارَهَا بِنَفْسِهِ، فَيُعْطِيهَا قَائِمًا، وَالْقَابِضُ مِنْهُ قَاعِدًا."]]},{"id":"tu41_16","label":"فَصْلٌ · ١٦","segs":[["matn","وَفِي رِوَايَةٍ: يَأْخُذُ بِتَلْبِيبِهِ وَيَهُزُّهُ، وَيَقُولُ لَهُ: أَعْطِ الْجِزْيَةَ يَا ذِمِّيُّ. وَفِي رِوَايَةٍ: يَا عَدُوَّ اللَّهِ. وَتَجِبُ بِأَوَّلِ الْحَوْلِ، وَيُمْهَلُ إِلَى آخِرِهِ تَيْسِيرًا."]]}],"group":"كِتَابُ الْجِهَادِ"},{"id":"tu42","title":"فَصْلٌ","units":[{"id":"tu42_1","label":"فَصْلٌ · ١","segs":[["matn","وَلَا يَجُوزُ إِحْدَاثُ بِيعَةٍ، وَلَا كَنِيسَةٍ، فِي دَارِ الْإِسْلَامِ، وَيُعَادُ مَا انْهَدَمَ كَمَا كَانَ، وَلَا يُنْقَلُ."]]},{"id":"tu42_2","label":"فَصْلٌ · ٢","segs":[["matn","وَيُمَيَّزُ أَهْلُ الذِّمَّةِ عَنِ الْمُسْلِمِينَ فِي زِيِّهِمْ، وَمَرَاكِبِهِمْ، وَسُرُوجِهِمْ، وَقَلَانِسِهِمْ، وَلَا يَرْكَبُونَ الْخَيْلَ، وَلَا يَحْمِلُونَ السِّلَاحَ، وَيُجْعَلُ عَلَى أَبْوَابِهِمْ عَلَامَةٌ، حَتَّى لَا يَقِفَ عَلَيْهَا سَائِلٌ يَدْعُو لَهُمْ."]]},{"id":"tu42_3","label":"فَصْلٌ · ٣","segs":[["matn","وَيُمَيَّزُ نِسَاؤُهُمْ عَنْ نِسَائِنَا فِي الطُّرُقِ، وَالْحَمَّامَاتِ بِعَلَامَةٍ، وَيُؤْمَرُ الذِّمِّيُّ بِشَدِّ الزُّنَّارِ مِنَ الصُّوفِ الْغَلِيظِ، دُونَ الْإِبْرِيسَمِ. وَيُمْنَعُ مِنْ لِبَاسٍ يَخْتَصُّ بِهِ أَهْلُ الْعِلْمِ، وَالزُّهْدِ، وَالشَّرَفِ، كَالصُّوفِ وَنَحْوِهِ."]]},{"id":"tu42_4","label":"فَصْلٌ · ٤","segs":[["matn","وَلَا يُبْدَأُ بِالسَّلَامِ، وَلَا بَأْسَ بِرَدِّ سَلَامِهِ، وَلَا يَزِيدُ الرَّادُّ عَلَى قَوْلِهِ: وَعَلَيْكُمْ. وَلَوْ قَالَ فِي جَوَابِهِ: السَّلَامُ عَلَى مَنِ اتَّبَعَ الْهُدَى جَازَ."]]},{"id":"tu42_5","label":"فَصْلٌ · ٥","segs":[["matn","وَلَوْ قَالَ لِلذِّمِّيِّ: أَطَالَ اللَّهُ بَقَاءَكَ لَمْ يَجُزْ، إِلَّا إِذَا نَوَى بِهِ إِطَالَةَ بَقَائِهِ لِإِسْلَامِهِ، أَوْ لِمَنْفَعَةِ الْجِزْيَةِ. وَيُضَيَّقُ عَلَيْهِ الطَّرِيقُ."]]},{"id":"tu42_6","label":"فَصْلٌ · ٦","segs":[["matn","وَلَا يَنْتَقِضُ عَهْدُ الذِّمَّةِ، إِلَّا بِأَنْ يَلْحَقَ بِدَارِ الْحَرْبِ، أَوْ يَغْلِبُوا عَلَى مَوْضِعٍ وَيُحَارِبُونَا، فَعِنْدَ ذَلِكَ هُمْ كَالْمُرْتَدِّينَ، إِلَّا أَنَّهُمْ يُسْتَرَقُّونَ بِخِلَافِ الْمُرْتَدِّينَ."]]},{"id":"tu42_7","label":"فَصْلٌ · ٧","segs":[["matn","وَمَالُ الْخَرَاجِ، وَالْجِزْيَةِ، وَهَدَايَا أَهْلِ الْحَرْبِ، تُصْرَفُ فِي مَصَالِحِ الْمُسْلِمِينَ، كَسَدِّ الثُّغُورِ، وَبِنَاءِ الْقَنَاطِرِ، وَالْجُسُورِ، وَأَرْزَاقِ الْقُضَاةِ، وَالْعُلَمَاءِ، وَالْغُزَاةِ مَعَ أَوْلَادِهِمْ، وَالْعُمَّالِ. وَمَنْ مَاتَ قَبْلَ الْقَبْضِ سَقَطَ نَصِيبُهُ."]]}],"group":"كِتَابُ الْجِهَادِ"},{"id":"tu43","title":"فَصْلٌ","units":[{"id":"tu43_1","label":"فَصْلٌ · ١","segs":[["matn","وَمَنِ ارْتَدَّ عُرِضَ عَلَيْهِ الْإِسْلَامُ، وَكُشِفَتْ شُبْهَتُهُ، وَحُبِسَ ثَلَاثَةَ أَيَّامٍ اسْتِحْبَابًا، وَقِيلَ: وُجُوبًا فَإِنْ لَمْ يُسْلِمْ قُتِلَ، فَإِنْ قَتَلَهُ رَجُلٌ قَبْلَ عَرْضِ الْإِسْلَامِ عَلَيْهِ كُرِهَ، وَلَا شَيْءَ عَلَيْهِ."]]},{"id":"tu43_2","label":"فَصْلٌ · ٢","segs":[["matn","وَالْمُرْتَدَّةُ لَا تُقْتَلُ، بَلْ تُحْبَسُ حَتَّى تُسْلِمَ، وَكَذَا الصَّبِيُّ الْمُمَيِّزُ. وَيَزُولُ مِلْكُ الْمُرْتَدِّ عَنْ أَمْوَالِهِ، زَوَالًا مَوْقُوفًا، فَإِنْ أَسْلَمَ عَادَ مِلْكُهُ، وَإِنْ مَاتَ، أَوْ قُتِلَ، فَكَسْبُ إِسْلَامِهِ لِوَرَثَتِهِ، وَكَسْبُ رِدَّتِهِ فَيْءٌ، وَيَعْتِقُ مُدَبَّرُوهُ، وَأُمَّهَاتُ أَوْلَادِهِ، وَتَحِلُّ الدُّيُونُ الَّتِي عَلَيْهِ."]]},{"id":"tu43_3","label":"فَصْلٌ · ٣","segs":[["matn","وَالْمُرْتَدَّةُ كَسْبُهَا لِوَرَثَتِهَا. وَلَحَاقُهُ بِدَارِ الْحَرْبِ مَعَ الْحُكْمِ بِهِ، كَالْمَوْتِ. وَتَصَرُّفَاتُ الْمُرْتَدِّ، أَقْسَامٌ: نَافِذٌ: كَالطَّلَاقِ، وَالِاسْتِيلَادِ، وَقَبُولِ الْهِبَةِ، وَإِسْقَاطِ الشُّفْعَةِ."]]},{"id":"tu43_4","label":"فَصْلٌ · ٤","segs":[["matn","وَبَاطِلٌ: كَالنِّكَاحِ، وَالذَّبْحِ. وَمَوْقُوفٌ: كَالْمُفَاوَضَةِ، وَالْبَيْعِ، وَالشِّرَاءِ، وَالرَّهْنِ، وَالْإِجَارَةِ، وَالْهِبَةِ، وَالْإِعْتَاقِ، وَالتَّدْبِيرِ. وَلَا تَصِحُّ رِدَّةُ مَجْنُونٍ، وَيَصِحُّ إِسْلَامُ الصَّبِيِّ الْمُمَيِّزِ."]]}],"group":"كِتَابُ الْجِهَادِ"},{"id":"tu44","title":"فَصْلٌ","units":[{"id":"tu44_1","label":"فَصْلٌ · ١","segs":[["matn","وَالْخَوَارِجُ يُدْعَوْنَ إِلَى الْإِسْلَامِ، وَتُكْشَفُ شُبْهَتُهُمْ، وَلَا يَبْدَأُ بِهِمُ الْإِمَامُ بِالْقِتَالِ، حَتَّى يَبْدَؤُوهُ بِهِ، أَوْ يَجْتَمِعُوا لَهُ، فَعِنْدَ ذَلِكَ يُقَاتِلُهُمْ، حَتَّى يُفَرِّقَهُمْ فَإِنْ كَانَتْ لَهُمْ فِئَةٌ، أَجْهَزَ عَلَى جَرِيحِهِمْ، وَاتَّبَعَ مُوَلِّيَهُمْ، وَإِلَّا فَلَا."]]},{"id":"tu44_2","label":"فَصْلٌ · ٢","segs":[["matn","وَلَا تُسْبَى ذَرَارِيُّهُمْ، وَلَا تُغْنَمُ أَمْوَالُهُمْ. وَيَجُوزُ الْقِتَالُ بِأَسْلِحَتِهِمْ، وَرُكُوبُ خَيْلِهِمْ عِنْدَ الْحَاجَةِ. وَيَحْبِسُ الْإِمَامُ أَمْوَالَهُمْ حَتَّى يَتُوبُوا، فَيَرُدُّهَا عَلَيْهِمْ."]]},{"id":"tu44_3","label":"فَصْلٌ · ٣","segs":[["matn","وَمَا جَبَوْهُ مِنَ الزَّكَاةِ، وَالْعُشْرِ، وَالْخَرَاجِ، مِنَ الْبِلَادِ الَّتِي غَلَبُوا عَلَيْهَا لَمْ يُثَنَّ، وَيُفْتَى الْمَأْخُوذُ مِنْهُ بِإِعَادَةِ الزَّكَاةِ، وَالْعُشْرِ، إِنْ كَانَ الْآخِذُونَ أَغْنِيَاءَ، بِخِلَافِ الْخَرَاجِ."]]},{"id":"tu44_4","label":"فَصْلٌ · ٤","segs":[["matn","وَلَوْ قَتَلَ بَعْضُهُمْ بَعْضًا، ثُمَّ ظَهَرْنَا عَلَيْهِمْ، فَهُوَ هَدَرٌ. وَلَوْ غَلَبُوا عَلَى بَلَدٍ، فَقَتَلَ رَجُلٌ مِنْ أَهْلِهِ رَجُلًا آخَرَ، ثُمَّ ظَهَرْنَا عَلَى الْبَلَدِ قَبْلَ اسْتِقْرَارِ مُلْكِهِمْ، وَإِجْرَاءِ أَحْكَامِهِمْ، وَجَبَ الْقِصَاصُ، وَإِلَّا فَهُوَ هَدَرٌ."]]},{"id":"tu44_5","label":"فَصْلٌ · ٥","segs":[["matn","وَلَا يَأْثَمُ الْعَادِلُ، وَلَا يَضْمَنُ بِإِتْلَافِ مَالِ الْبَاغِي، أَوْ نَفْسِهِ. وَالْبَاغِي يَأْثَمُ فِيمَا يَفْعَلُ بِالْعَادِلِ، وَلَا يَضْمَنُ."]]},{"id":"tu44_6","label":"فَصْلٌ · ٦","segs":[["matn","وَلَوْ قَتَلَ الْعَادِلُ الْبَاغِيَ وَرِثَهُ، وَلَوْ قَتَلَهُ الْبَاغِي وَقَالَ: قَتَلْتُهُ مُحِقًّا وَرِثَهُ، وَإِنْ قَالَ: قَتَلْتُهُ مُبْطِلًا لَمْ يَرِثْهُ."]]}],"group":"كِتَابُ الْجِهَادِ"},{"id":"tu45","title":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ","units":[{"id":"tu45_1","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ١","segs":[["matn","يَجُوزُ الصَّيْدُ بِالْكَلْبِ، وَالْفَهْدِ، وَالْبَازِيِّ، وَالصَّقْرِ، وَكُلِّ جَارِحٍ مُعَلَّمٍ، إِلَّا الْخِنْزِيرَ. وَقِيلَ: إِلَّا الْأَسَدَ، وَالذِّئْبَ، وَالدُّبَّ، وَالْحِدَأَةَ. وَتَعَلُّمُ الْكَلْبِ، وَنَحْوِهِ بِتَرْكِهِ الْأَكْلَ ثَلَاثَ مَرَّاتٍ، فَيَحِلُّ مَا اصْطَادَهُ فِي الثَّالِثَةِ."]]},{"id":"tu45_2","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ٢","segs":[["matn","وَقِيلَ: تَعَلُّمُهُ بِقَوْلِ الصَّيَّادِينَ: إِنَّهُ تَعَلَّمَ. وَتَعَلُّمُ الْبَازِي، وَنَحْوِهِ، بِإِجَابَتِهِ إِذَا دُعِيَ. فَإِذَا أَرْسَلَ الْجَارِحَ الْمُعَلَّمَ، وَسَمَّى عِنْدَ إِرْسَالِهِ، فَجَرَحَ صَيْدًا، أَوْ مَاتَ حَلَّ."]]},{"id":"tu45_3","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ٣","segs":[["matn","وَإِنْ لَمْ يَجْرَحْهُ لَمْ يَحِلَّ. وَكَذَا لَوْ خَنَقَهُ، أَوْ كَسَرَهُ. فَإِنْ أَكَلَ مِنْهُ الْكَلْبُ أَوِ الْفَهْدُ، لَمْ يَحِلَّ بِخِلَافِ الْبَازِي."]]},{"id":"tu45_4","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ٤","segs":[["matn","وَلَا يَحِلُّ مَا اصْطَادَهُ قَبْلَ هَذَا، مُحْرَزًا كَانَ فِي الْبَيْتِ، أَوْ فِي الصَّحْرَاءِ، وَلَا مَا يَصِيدُهُ بَعْدَهُ، حَتَّى يَصِيرَ مُعَلَّمًا بِمَا ذَكَرْنَا."]]},{"id":"tu45_5","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ٥","segs":[["matn","وَلَوْ فَرَّ بَازٌ مِنْ صَاحِبِهِ، وَلَمْ يُجِبْهُ إِذَا دَعَاهُ، ثُمَّ صَادَ، فَحُكْمُهُ حُكْمُ الْكَلْبِ فِي الْوُجُوهِ كُلِّهَا."]]},{"id":"tu45_6","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ٦","segs":[["matn","وَلَوْ شَرِبَ الْكَلْبُ مِنْ دَمِ الصَّيْدِ، وَلَمْ يَأْكُلْ مِنْهُ حَلَّ، وَكَذَا لَوْ أَكَلَ مَا أَعْطَاهُ صَاحِبُهُ مِنْهُ، أَوْ خَطِفَهُ مِنْ صَاحِبِهِ فَأَكَلَ مِنْهُ."]]},{"id":"tu45_7","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ٧","segs":[["matn","وَلَوْ قَطَعَ مِنَ الصَّيْدِ قِطْعَةً فَأَكَلَهَا، ثُمَّ اتَّبَعَهُ فَقَتَلَهُ، وَلَمْ يَأْكُلْ مِنْهُ لَمْ يَحِلَّ. وَلَوْ أَلْقَى مَا قَطَعَهُ وَاتَّبَعَهُ فَقَتَلَهُ، وَلَمْ يَأْكُلْ مِنْهُ، حَتَّى أَخَذَهُ صَاحِبُهُ، ثُمَّ مَرَّ بِتِلْكَ الْقِطْعَةِ فَأَكَلَهَا، حَلَّ."]]},{"id":"tu45_8","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ٨","segs":[["matn","وَإِنْ أَدْرَكَ الْمُرْسِلُ الصَّيْدَ حَيًّا، مِثْلَ حَيَاةِ الْمَذْبُوحِ، وَجَبَتْ ذَكَاتُهُ، فَإِنْ تَرَكَهَا حَتَّى مَاتَ لَمْ يَحِلَّ، وَكَذَا الْبَازِيُّ، وَالصَّقْرُ، وَالسَّهْمُ،"]]},{"id":"tu45_9","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ٩","segs":[["matn","وَكَذَا إِنْ لَمْ يَتَمَكَّنْ لِضِيقِ الْوَقْتِ، أَوْ لِفَقْدِ الْآلَةِ كَالْأَهْلِيِّ، إِنْ لَمْ يَتَمَكَّنْ مِنْ ذَبْحِهِ، لَا يَحِلُّ بِذَكَاةِ الِاضْطِرَارِ. وَلَوْ وَقَعَ الصَّيْدُ عِنْدَ مَجُوسِيٍّ، وَقَدَرَ عَلَى ذَبْحِهِ، ثُمَّ مَاتَ لَمْ يُؤْكَلْ."]]},{"id":"tu45_10","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ١٠","segs":[["matn","وَلَوْ أَرْسَلَ كَلْبَهُ عَلَى صَيْدٍ فَأَخَذَ غَيْرَهُ حَلَّ، وَلَوْ أَرْسَلَهُ عَلَى صَيْدٍ كَثِيرٍ، وَسَمَّى مَرَّةً وَاحِدَةً، يَحِلُّ كُلُّ مَا قَتَلَهُ بِتِلْكَ التَّسْمِيَةِ، بِخِلَافِ الشَّاتَيْنِ اللَّتَيْنِ لَمْ تُضْجَعْ إِحْدَاهُمَا فَوْقَ الْأُخْرَى."]]},{"id":"tu45_11","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ١١","segs":[["matn","وَكُمُونُ الْفَهْدِ لَا يَقْطَعُ حُكْمَ إِرْسَالِهِ، وَكَذَا الْكَلْبُ إِذَا اعْتَادَ عَادَتَهُ. وَإِذَا أَخَذَ الْجَارِحُ صَيْدًا بَعْدَ صَيْدٍ بِإِرْسَالٍ وَاحِدٍ، حَلَّ الْكُلُّ، مَا لَمْ يُعْرِضْ لِاسْتِرَاحَةٍ، كَمَا لَوْ جَثَمَ عَلَى الصَّيْدِ زَمَانًا طَوِيلًا فَمَرَّ بِهِ صَيْدٌ آخَرُ فَقَتَلَهُ، لَمْ يَحِلَّ الثَّانِي."]]},{"id":"tu45_12","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ١٢","segs":[["matn","وَلَوْ مَرَّ السَّهْمُ مِنَ الصَّيْدِ الْمَقْصُودِ إِلَى صَيْدٍ آخَرَ فَقَتَلَهُ حَلَّا."]]},{"id":"tu45_13","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ١٣","segs":[["matn","وَلَوْ أَرْسَلَ بَازِيَّهُ عَلَى صَيْدٍ، فَنَزَلَ عَلَى شَيْءٍ، ثُمَّ طَارَ وَأَخَذَهُ، حَلَّ إِنْ قَصُرَ الزَّمَانُ، بِقَدْرِ مَا يَكُونُ تَمَكُّنًا لَا اسْتِرَاحَةً."]]},{"id":"tu45_14","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ١٤","segs":[["matn","وَلَوْ أَخَذَ جَارِحٌ مُعَلَّمٌ صَيْدًا، وَلَمْ يُعْلَمْ هَلْ أَرْسَلَهُ أَحَدٌ أَمْ لَا؟ لَمْ يَحِلَّ."]]},{"id":"tu45_15","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ١٥","segs":[["matn","وَإِنْ شَارَكَهُ كَلْبٌ غَيْرُ مُعَلَّمٍ، أَوْ كَلْبُ مَجُوسِيٍّ، أَوْ كَلْبٌ لَمْ يُذْكَرِ اسْمُ اللَّهِ عَلَيْهِ عَمْدًا، لَمْ يَحِلَّ. وَلَوْ رَدَّهُ عَلَيْهِ، وَلَمْ يَجْرَحْهُ مَعَهُ، حَلَّ وَكُرِهَ."]]},{"id":"tu45_16","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ١٦","segs":[["matn","وَلَوْ رَدَّهُ عَلَيْهِ مَجُوسِيٌّ، أَوْ أَغْرَاهُ بِهِ، فَزَادَ عَدْوُهُ لَمْ يُكْرَهْ. وَكَذَا لَوْ لَمْ يَرُدَّهُ عَلَيْهِ الثَّانِي، بَلْ حَمَلَ عَلَيْهِ فَزَادَ عَدْوُهُ."]]},{"id":"tu45_17","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ١٧","segs":[["matn","وَلَوْ أَرْسَلَهُ مَجُوسِيٌّ فَأَغْرَاهُ بِهِ مُسْلِمٌ، فَزَادَ عَدْوُهُ لَمْ يَحِلَّ. وَتُعْتَبَرُ الْأَهْلِيَّةُ وَعَدَمُهَا عِنْدَ الْإِرْسَالِ، لَا عِنْدَ الْأَخْذِ. وَكُلُّ مَنْ لَا تَحِلُّ ذَكَاتُهُ، فَهُوَ كَالْمَجُوسِيِّ فِيمَا قُلْنَا."]]},{"id":"tu45_18","label":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ · ١٨","segs":[["matn","وَالْمُسْلِمُ وَغَيْرُهُ سَوَاءٌ فِي صَيْدِ السَّمَكِ، وَالْجَرَادِ. وَلَوِ انْفَلَتَ كَلْبُ مَجُوسِيٍّ، وَلَمْ يُرْسِلْهُ صَاحِبُهُ، فَأَغْرَاهُ مُسْلِمٌ بِالصَّيْدِ، فَأَخَذَهُ حَلَّ."]]}],"group":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ"},{"id":"tu46","title":"فَصْلٌ","units":[{"id":"tu46_1","label":"فَصْلٌ · ١","segs":[["matn","وَمَنْ سَمِعَ حِسًّا ظَنَّهُ حِسَّ صَيْدٍ فَرَمَاهُ، أَوْ أَرْسَلَ عَلَيْهِ جَارِحًا، فَأَصَابَ غَيْرَهُ، حَلَّ الْمُصَابُ إِذَا كَانَ الْمَسْمُوعُ حِسَّ صَيْدٍ، وَلَوْ كَانَ خِنْزِيرًا."]]},{"id":"tu46_2","label":"فَصْلٌ · ٢","segs":[["matn","بِخِلَافِ مَا لَوْ ظَهَرَ أَنَّهُ آدَمِيٌّ، أَوْ حَيَوَانٌ أَهْلِيٌّ، فَإِنَّهُ لَا يَحِلُّ الْمُصَابُ. وَالطَّيْرُ الْمُسْتَأْنَسُ، وَالظَّبْيُ الْمَرْبُوطُ، أَهْلِيَّانِ حُكْمًا."]]},{"id":"tu46_3","label":"فَصْلٌ · ٣","segs":[["matn","وَلَوْ أَصَابَ الْمَسْمُوعَ حِسُّهُ وَقَدْ ظَنَّهُ آدَمِيًّا، فَظَهَرَ صَيْدًا حَلَّ. وَلَوْ رَمَى إِلَى طَائِرٍ فَأَصَابَ صَيْدًا، أَوْ مَرَّ الطَّائِرُ وَلَمْ يَعْلَمْ أَنَّهُ وَحْشِيٌّ، أَوْ أَهْلِيٌّ حَلَّ الصَّيْدُ."]]},{"id":"tu46_4","label":"فَصْلٌ · ٤","segs":[["matn","بِخِلَافِ مَا لَوْ رَمَى إِلَى بَعِيرٍ فَأَصَابَ صَيْدًا، وَلَمْ يَعْلَمْ أَنَّهُ نَادٌّ، أَمْ لَا. وَإِنْ عَلِمَ أَنَّهُ نَادٌّ حَلَّ. وَلَوْ رَمَى إِلَى سَمَكَةٍ، أَوْ جَرَادَةٍ، فَأَصَابَ صَيْدًا، حَلَّ فِي إِحْدَى الرِّوَايَتَيْنِ."]]},{"id":"tu46_5","label":"فَصْلٌ · ٥","segs":[["matn","وَإِذَا وَقَعَ السَّهْمُ بِالصَّيْدِ، أَوْ جَرَحَهُ الْجَارِحُ، فَتَحَامَلَ حَتَّى غَابَ عَنِ الصَّائِدِ، وَلَمْ يَزَلْ فِي طَلَبِهِ حَتَّى أَصَابَهُ مَيِّتًا حَلَّ."]]},{"id":"tu46_6","label":"فَصْلٌ · ٦","segs":[["matn","وَإِنْ قَعَدَ عَنْ طَلَبِهِ، ثُمَّ أَصَابَهُ مَيِّتًا، لَمْ يَحِلَّ، وَكَذَا لَوْ وَجَدَ بِهِ جِرَاحَةً أُخْرَى."]]},{"id":"tu46_7","label":"فَصْلٌ · ٧","segs":[["matn","وَلَوْ رَمَى صَيْدًا فَوَقَعَ فِي مَاءٍ، أَوْ عَلَى سَطْحٍ، أَوْ جَبَلٍ، أَوْ شَجَرَةٍ، أَوْ صَخْرَةٍ، أَوْ حَائِطٍ، أَوْ جَرَّةٍ،"]]},{"id":"tu46_8","label":"فَصْلٌ · ٨","segs":[["matn","ثُمَّ وَقَعَ مِنْهُ إِلَى الْأَرْضِ، أَوْ رَمَاهُ فِي جَبَلٍ فَتَرَدَّى مِنْ مَوْضِعٍ إِلَى مَوْضِعٍ حَتَّى وَصَلَ إِلَى الْأَرْضِ فَوَقَعَ عَلَى رُمْحٍ مَنْصُوبٍ، أَوْ قَصَبَةٍ قَائِمَةٍ، أَوْ حَرْفِ آجُرَّةٍ، لَمْ يَحِلَّ، إِلَّا إِذَا أَبَانَ رَأْسَهُ بِالرَّمْيَةِ."]]},{"id":"tu46_9","label":"فَصْلٌ · ٩","segs":[["matn","وَلَوْ وَقَعَ عَلَى الْأَرْضِ حَيًّا فَمَاتَ، أَوْ عَلَى جَبَلٍ، أَوْ ظَهْرِ بَيْتٍ، أَوْ آجُرَّةٍ، مَوْضُوعَةٍ، أَوْ صَخْرَةٍ، فَاسْتَقَرَّ عَلَيْهَا حَلَّ، إِلَّا أَنْ يُصِيبَهُ حَدُّ الصَّخْرَةِ، فَيَشُقَّ بَطْنَهُ، فَيَحْرُمَ."]]},{"id":"tu46_10","label":"فَصْلٌ · ١٠","segs":[["matn","وَإِنْ كَانَ الطَّيْرُ مَائِيًّا، وَرَمَاهُ فِي الْمَاءِ حَلَّ، إِنْ لَمْ يَنْغَمِسْ بِالْجِرَاحَةِ فِيهِ."]]},{"id":"tu46_11","label":"فَصْلٌ · ١١","segs":[["matn","وَلَا يَحِلُّ الصَّيْدُ بِالْبُنْدُقَةِ، وَعَرْضِ الْمِعْرَاضِ، وَالْعَصَا الَّتِي لَا حَدَّ لَهَا يَجْرَحُ، وَالْحَجَرِ الثَّقِيلِ وَلَوْ جَرَحَ، وَلَوْ كَانَ خَفِيفًا وَفِيهِ حِدَّةٌ حَلَّ."]]},{"id":"tu46_12","label":"فَصْلٌ · ١٢","segs":[["matn","وَلَوْ رَمَاهُ بِمَرْوَةٍ مُحَدَّدَةٍ، وَلَمْ تَجْرَحْهُ لَمْ يَحِلَّ. وَلَوْ أَبَانَ رَأْسَهُ، أَوْ قَطَعَ أَوْدَاجَهُ حَلَّ، وَلَوْ رَمَاهُ بِسَيْفٍ، أَوْ سِكِّينٍ، حَلَّ إِنْ جَرَحَهُ بِحَدِّهِ."]]},{"id":"tu46_13","label":"فَصْلٌ · ١٣","segs":[["matn","وَإِذَا جَرَحَ السَّهْمُ، أَوِ الْكَلْبُ، الصَّيْدَ جَرْحًا غَيْرَ مُدْمٍ، قِيلَ: يَحِلُّ، وَهُوَ الْأَظْهَرُ."]]},{"id":"tu46_14","label":"فَصْلٌ · ١٤","segs":[["matn","وَقِيلَ: لَا يَحِلُّ، وَقِيلَ: يَحِلُّ فِي الْجِرَاحَةِ الْكَبِيرَةِ لَا فِي الصَّغِيرَةِ، وَلَوْ ذَبَحَ شَاةً وَلَمْ يَسِلْ مِنْهَا دَمٌ، فَعَلَى الْقَوْلَيْنِ."]]},{"id":"tu46_15","label":"فَصْلٌ · ١٥","segs":[["matn","وَقِيلَ: إِنْ تَحَرَّكَتْ حَلَّتْ، وَلَوْ خَرَجَ الدَّمُ وَلَمْ تَتَحَرَّكْ لَا يَحِلُّ. وَلَوْ أَصَابَ السَّهْمُ ظِلْفَ الصَّيْدِ، أَوْ قَرْنَهُ، حَلَّ إِنْ أَدْمَاهُ."]]},{"id":"tu46_16","label":"فَصْلٌ · ١٦","segs":[["matn","وَلَوْ رَمَى صَيْدًا فَقَطَعَ عُضْوَهُ، أَوْ أَقَلَّ مِنْ نِصْفِ رَأْسِهِ، حَلَّ الصَّيْدُ لَا الْمَقْطُوعُ. وَإِنْ قُطِعَ نِصْفَيْنِ، أَوْ قَطَعَهُ أَثْلَاثًا، وَالْأَكْثَرُ مِنْ مُؤَخَّرِهِ، أَوْ قَطَعَ نِصْفَ رَأْسِهِ، أَوْ أَكْثَرَهُ، حَلَّ الْكُلُّ."]]},{"id":"tu46_17","label":"فَصْلٌ · ١٧","segs":[["matn","وَلَوْ تَعَلَّقَ الْعُضْوُ الْمَقْطُوعُ بِجِلْدِهِ، فَإِنْ كَانَ يَلْتَئِمُ لَوْ تَرَكَهُ، حَلَّ الْعُضْوُ، وَإِلَّا فَلَا. وَلَا يَحِلُّ صَيْدُ الْمَجُوسِيِّ، وَالْمُرْتَدِّ، وَالْوَثَنِيِّ، وَالْمُحْرِمِ، بِخِلَافِ الْيَهُودِيِّ، وَالنَّصْرَانِيِّ."]]},{"id":"tu46_18","label":"فَصْلٌ · ١٨","segs":[["matn","وَمَنْ رَمَى صَيْدًا، فَأَصَابَهُ، وَلَمْ يُثْخِنْهُ، فَرَمَاهُ آخَرُ فَقَتَلَهُ، فَهُوَ لَهُ، وَيَحِلُّ. وَإِنْ أَثْخَنَهُ الْأَوَّلُ فَهُوَ لَهُ، وَلَمْ يَحِلَّ."]]},{"id":"tu46_19","label":"فَصْلٌ · ١٩","segs":[["matn","وَيَضْمَنُ الثَّانِي قِيمَتَهُ مَجْرُوحًا بِجِرَاحَةِ الْأَوَّلِ، إِنْ عُلِمَ حُصُولُ الْقَتْلِ بِالثَّانِي. وَإِنْ عُلِمَ حُصُولُهُ بِهِمَا، أَوْ شُكَّ، ضَمِنَ الثَّانِي مَا نَقَصَتْهُ جِرَاحَتُهُ، وَنِصْفَ قِيمَتِهِ مَجْرُوحًا بِجِرَاحَتَيْنِ، وَنِصْفَ قِيمَةِ لَحْمِهِ."]]},{"id":"tu46_20","label":"فَصْلٌ · ٢٠","segs":[["matn","وَإِنْ كَانَ الرَّامِي الثَّانِي هُوَ الْأَوَّلَ، فَحُكْمُ الْإِبَاحَةِ مَا قُلْنَا، وَصَارَ كَمَا لَوْ رَمَى صَيْدًا عَلَى جَبَلٍ فَأَثْخَنَهُ، ثُمَّ رَمَاهُ ثَانِيًا فَأَنْزَلَهُ، لَا يَحِلُّ."]]},{"id":"tu46_21","label":"فَصْلٌ · ٢١","segs":[["matn","وَيَحِلُّ صَيْدُ مَا لَا يُؤْكَلُ لَحْمُهُ. وَلَوْ رَمَى صَيْدًا وَرَمَاهُ آخَرُ، فَأَصَابَ سَهْمُ الثَّانِي سَهْمَ الْأَوَّلِ، فَرَدَّهُ إِلَى صَيْدٍ آخَرَ، فَقَتَلَهُ، حَلَّ إِنْ سَمَّى الثَّانِي."]]},{"id":"tu46_22","label":"فَصْلٌ · ٢٢","segs":[["matn","وَلَوْ رَمَى صَيْدًا بِمِعْرَاضٍ، أَوْ بِبُنْدُقَةٍ، فَأَصَابَ سَهْمًا، فَرَفَعَهُ فَقَتَلَ صَيْدًا جَرْحًا حَلَّ."]]},{"id":"tu46_23","label":"فَصْلٌ · ٢٣","segs":[["matn","وَلَوْ نَصَبَ شَبَكَةً لِلصَّيْدِ فِي أَرْضِ الْغَيْرِ، فَوَقَعَ فِيهَا صَيْدٌ فَهُوَ لَهُ. وَلَوْ نَصَبَهَا لِلْجَفَافِ، لَمْ يَكُنْ لَهُ حَقٌّ حَتَّى يَأْخُذَهُ."]]},{"id":"tu46_24","label":"فَصْلٌ · ٢٤","segs":[["matn","وَمَنْ أَخَذَ صَيْدًا، أَوْ فَرْخَهُ، أَوْ بَيْضَهُ فِي دَارِ رَجُلٍ، أَوْ أَرْضِهِ، فَهُوَ لَهُ، إِلَّا أَنْ يُغْلِقَ صَاحِبُ الدَّارِ الْبَابَ لِإِحْرَازِهِ، فَحِينَئِذٍ يَمْلِكُهُ."]]},{"id":"tu46_25","label":"فَصْلٌ · ٢٥","segs":[["matn","وَلَوْ نَصَبَ شَبَكَةً فَوَقَعَ فِيهَا صَيْدٌ، أَوْ رَمَى شِصًّا، فَتَعَلَّقَتْ بِهِ سَمَكَةٌ، فَاضْطَرَبَا حَتَّى انْقَطَعَتِ الشَّبَكَةُ، وَخَيْطُ الشِّصِّ، وَخَلَصَا فَصَادَهُمَا آخَرُ، فَهُمَا لَهُ."]]},{"id":"tu46_26","label":"فَصْلٌ · ٢٦","segs":[["matn","وَلَوْ لَمْ يَخْلُصْ حَتَّى جَاءَ الصَّائِدُ، وَقَدَرَ عَلَى أَخْذِهِ، ثُمَّ خَلَصَ وَانْفَلَتَ فَهُوَ عَلَى مِلْكِهِ. وَكَذَا لَوْ رَمَى بِالسَّمَكَةِ خَارِجَ الْمَاءِ فَاضْطَرَبَتْ، ثُمَّ وَقَعَتْ فِي الْمَاءِ."]]},{"id":"tu46_27","label":"فَصْلٌ · ٢٧","segs":[["matn","وَلَوْ رَمَى صَيْدًا فَصَرَعَهُ، وَغُشِيَ عَلَيْهِ، ثُمَّ أَفَاقَ وَطَارَ، فَأَخَذَهُ آخَرُ فَهُوَ لَهُ. وَلَوْ جَرَحَهُ جِرَاحَةً مُثْخِنَةً، ثُمَّ بَرَأَ وَطَارَ، فَأَخَذَهُ آخَرُ فَهُوَ لِلْأَوَّلِ."]]}],"group":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ"},{"id":"tu47","title":"فَصْلٌ","units":[{"id":"tu47_1","label":"فَصْلٌ · ١","segs":[["matn","وَيَحْرُمُ أَكْلُ كُلِّ ذِي نَابٍ مِنَ السِّبَاعِ، وَذِي مِخْلَبٍ مِنَ الطَّيْرِ، وَيَحْرُمُ الضَّبُعُ، وَالثَّعْلَبُ، وَالْيَرْبُوعُ، وَابْنُ عِرْسٍ، وَالرَّخَمَةُ، وَالْبُغَاثُ، وَالْغُدَافُ، وَالْحِدَأَةُ، وَالْغُرَابُ الْأَبْقَعُ الَّذِي يَأْكُلُ الْجِيَفَ."]]},{"id":"tu47_2","label":"فَصْلٌ · ٢","segs":[["matn","وَيَحِلُّ غُرَابُ الزَّرْعِ، وَالْعَقْعَقُ، وَاللَّقْلَقُ. وَيَحْرُمُ الضَّبُّ، وَالْقُنْفُذُ، وَالسُّلَحْفَاةُ، وَالزُّنْبُورُ، وَالْحَشَرَاتُ كُلُّهَا، إِلَّا الْجَرَادَ، وَلَوْ مَاتَ حَتْفَ أَنْفِهِ. وَلَحْمُ الْفَرَسِ حَرَامٌ مُطْلَقًا."]]},{"id":"tu47_3","label":"فَصْلٌ · ٣","segs":[["matn","وَبَقَرُ الْوَحْشِ، وَحُمُرُ الْوَحْشِ، وَغَنَمُ الْجَبَلِ، حَلَالٌ. وَلَا يَحِلُّ مِنْ حَيَوَانِ الْمَاءِ، إِلَّا أَنْوَاعُ السَّمَكِ كُلُّهَا، وَلَا يَحِلُّ الطَّافِي مِنْهُ، وَهُوَ الَّذِي مَاتَ حَتْفَ أَنْفِهِ."]]},{"id":"tu47_4","label":"فَصْلٌ · ٤","segs":[["matn","وَيَحِلُّ مَا فِي بَطْنِهِ مِنَ السَّمَكِ. وَلَوْ قَطَعَهُ فَمَاتَ، حَلَّ الْمَقْطُوعُ وَالْبَاقِي. وَفِي مَوْتِهِ بِالْحَرِّ، وَالْبَرْدِ، أَوْ كُدْرَتِهِ، رِوَايَتَانِ."]]},{"id":"tu47_5","label":"فَصْلٌ · ٥","segs":[["matn","وَلَوْ حَصَرَ سَمَكًا فِي أَجَمَةٍ، أَوْ نَحْوِهَا، فَمَاتَ؛ لِضِيقِ الْمَكَانِ حَلَّ. وَمَا انْحَسَرَ عَنْهُ الْمَاءُ، أَوْ أَلْقَاهُ إِلَى السَّاحِلِ حَيًّا، فَمَاتَ يَحِلُّ."]]},{"id":"tu47_6","label":"فَصْلٌ · ٦","segs":[["matn","وَلَوْ وَجَدَ عَلَى الْأَرْضِ سَمَكَةً مَيْتَةً، تَحِلُّ. وَلَوْ وَجَدَ نِصْفَ سَمَكَةٍ فِي الْمَاءِ، لَمْ تَحِلَّ، إِلَّا إِذَا ظَهَرَ أَنَّهَا مَقْطُوعَةٌ بِسَيْفٍ، أَوْ نَحْوِهِ."]]},{"id":"tu47_7","label":"فَصْلٌ · ٧","segs":[["matn","وَلَوِ اشْتَرَى سَمَكَةً فِي خَيْطٍ، وَهِيَ فِي الْمَاءِ، وَقَبَضَ الْخَيْطَ، ثُمَّ دَفَعَهُ إِلَى الْبَائِعِ،"]]},{"id":"tu47_8","label":"فَصْلٌ · ٨","segs":[["matn","وَقَالَ: احْفَظْهَا لِي، فَابْتَلَعَتْهَا سَمَكَةٌ أُخْرَى، فَالثَّانِيَةُ لِلْبَائِعِ، وَيُخْرِجُ الْأُولَى وَيُسَلِّمُهَا إِلَى الْمُشْتَرِي، مِنْ غَيْرِ خِيَارٍ، وَإِنْ نَقَصَهَا الِابْتِلَاعُ. وَلَوِ ابْتَلَعَتِ الْمَرْبُوطَةُ أُخْرَى، فَهُمَا لِلْمُشْتَرِي، قَبَضَهَا أَوْ لَا."]]}],"group":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ"},{"id":"tu48","title":"فَصْلٌ","units":[{"id":"tu48_1","label":"فَصْلٌ · ١","segs":[["matn","وَذَبِيحَةُ الْمُسْلِمِ، وَالْكِتَابِيِّ حَلَالٌ. بِخِلَافِ ذَبِيحَةِ الْمَجُوسِيِّ، وَذَبِيحَةِ الْمُحْرِمِ الصَّيْدَ، وَمَا ذُبِحَ مِنَ الصَّيْدِ فِي الْحَرَمِ وَلَوْ كَانَ الذَّابِحُ حَلَالًا."]]},{"id":"tu48_2","label":"فَصْلٌ · ٢","segs":[["matn","وَالصَّبِيُّ، وَالْمَجْنُونُ، وَالسَّكْرَانُ، إِنْ كَانَ يَقْدِرُ عَلَى الذَّبْحِ، وَيَعْقِلُ التَّسْمِيَةَ، حَلَّ وَإِلَّا فَلَا. وَمَتْرُوكُ التَّسْمِيَةِ عَمْدًا مَيْتَةٌ، وَمَتْرُوكُهَا نَاسِيًا حَلَالٌ."]]},{"id":"tu48_3","label":"فَصْلٌ · ٣","segs":[["matn","وَوَقْتُ التَّسْمِيَةِ فِي غَيْرِ الصَّيْدِ عِنْدَ الذَّبْحِ، وَفِي الصَّيْدِ عِنْدَ الرَّمْيِ، أَوْ إِرْسَالِ الْجَارِحِ. وَلَوْ أَضْجَعَ شَاةً وَسَمَّى، وَذَبَحَ غَيْرَهَا بِتِلْكَ التَّسْمِيَةِ، لَمْ تَحِلَّ، بِخِلَافِ الْإِرْسَالِ، وَالرَّمْيِ."]]},{"id":"tu48_4","label":"فَصْلٌ · ٤","segs":[["matn","وَلَوْ أَضْجَعَ شَاةً وَسَمَّى، ثُمَّ رَمَى السِّكِّينَ، وَذَبَحَ بِأُخْرَى حَلَّ. وَلَوْ سَمَّى عَلَى سَهْمٍ، ثُمَّ رَمَى بِغَيْرِهِ فَقَتَلَ، لَمْ يَحِلَّ."]]},{"id":"tu48_5","label":"فَصْلٌ · ٥","segs":[["matn","وَلَوْ قَالَ فِي تَسْمِيَتِهِ: بِسْمِ اللَّهِ، مُحَمَّدًا رَسُولَ اللَّهِ، أَوْ مُحَمَّدٌ رَسُولُ اللَّهِ بِالرَّفْعِ، أَوِ اللَّهُمَّ تَقَبَّلْ مِنِّي، أَوْ مِنْ فُلَانٍ، حَلَّ وَكُرِهَ."]]},{"id":"tu48_6","label":"فَصْلٌ · ٦","segs":[["matn","وَلَوْ قَالَ: وَمُحَمَّدٍ بِالْجَرِّ لَمْ يَحِلَّ، وَلَوْ قَالَ: بِسْمِلْ بِغَيْرِ هَاءٍ وَقَصَدَ بِهِ التَّسْمِيَةَ، حَلَّ. وَلَوْ قَالَ: اللَّهُمَّ اغْفِرْ لِي، وَقَصَدَ بِهِ التَّسْمِيَةَ لَمْ يَحِلَّ."]]},{"id":"tu48_7","label":"فَصْلٌ · ٧","segs":[["matn","وَلَوْ سَبَّحَ، أَوْ حَمِدَ، أَوْ كَبَّرَ، وَقَصَدَ التَّسْمِيَةَ حَلَّ. وَلَوْ عَطَسَ عِنْدَ الذَّبْحِ، فَحَمِدَ اللَّهَ، لَمْ يَحِلَّ فِي الْأَصَحِّ."]]},{"id":"tu48_8","label":"فَصْلٌ · ٨","segs":[["matn","وَلَوْ سَمَّى، ثُمَّ عَمِلَ عَمَلًا آخَرَ قَبْلَ الذَّبْحِ، إِنْ كَانَ قَلِيلًا، كَشُرْبِ الْمَاءِ، أَوْ تَكْلِيمِ إِنْسَانٍ، حَلَّ، وَإِلَّا فَلَا. وَالذَّبْحُ بَيْنَ الْحَلْقِ، وَاللَّبَّةِ."]]},{"id":"tu48_9","label":"فَصْلٌ · ٩","segs":[["matn","وَالْعُرُوقُ الْمَقْطُوعَةُ فِيهِ أَرْبَعَةٌ: الْحُلْقُومُ، وَالْمَرِيءُ، وَالْوَدَجَانِ. وَلَا بُدَّ مِنْ قَطْعِ ثَلَاثَةٍ مِنْهَا أَيَّهَا كَانَتْ. وَيَجُوزُ الذَّبْحُ بِكُلِّ مُحَدَّدٍ أَنْهَرَ الدَّمَ، إِلَّا السِّنَّ الْمُتَّصِلَ، وَالظُّفُرَ، وَالْقَرْنَ، فَإِنَّ الْمَذْبُوحَ بِهَا مَيْتَةٌ."]]},{"id":"tu48_10","label":"فَصْلٌ · ١٠","segs":[["matn","وَالذَّبْحُ بِالْمُنْفَصِلِ مِنْهَا مَكْرُوهٌ، وَكَذَا بِالْعَظْمِ، وَبِكُلِّ مَا فِيهِ إِبْطَاءُ الْإِمَاتَةِ. وَيُسْتَحَبُّ إِحْدَادُ السِّكِّينِ قَبْلَ الْإِضْجَاعِ، وَيُكْرَهُ بَعْدَهُ. وَمَنْ بَلَغَ بِالسِّكِّينِ النُّخَاعَ، أَوْ قَطَعَ الرَّأْسَ، حَلَّ وَكُرِهَ."]]},{"id":"tu48_11","label":"فَصْلٌ · ١١","segs":[["matn","وَكُلُّ زِيَادَةِ تَعْذِيبٍ لَا يُحْتَاجُ إِلَيْهَا مَكْرُوهٌ، كَجَرِّ الْمَذْبُوحِ بِرِجْلِهِ إِلَى الْمَذْبَحِ، وَسَلْخِهِ قَبْلَ أَنْ يَتِمَّ مَوْتُهُ، وَكَذَا لَوْ مَاتَ وَلَمْ يَبْرُدْ أَيْضًا عِنْدَ الْبَعْضِ."]]},{"id":"tu48_12","label":"فَصْلٌ · ١٢","segs":[["matn","وَلَوْ ذُبِحَ مِنَ الْقَفَا وَبَقِيَ حَيًّا حَتَّى قَطَعَ الْعُرُوقَ الثَّلَاثَةَ حَلَّ وَكُرِهَ، وَإِلَّا فَلَا."]]},{"id":"tu48_13","label":"فَصْلٌ · ١٣","segs":[["matn","وَمَا اسْتَأْنَسَ مِنَ الصَّيْدِ فَذَكَاتُهُ الذَّبْحُ، وَمَا تَوَحَّشَ مِنَ النَّعَمِ بِصِيَالٍ، أَوْ نَدٍّ، فَذَكَاتُهُ الْجَرْحُ، بِشَرْطِ قَصْدِ الذَّكَاةِ، لَا دَفْعِ الصِّيَالِ فَقَطْ."]]},{"id":"tu48_14","label":"فَصْلٌ · ١٤","segs":[["matn","وَكَذَا الْبَعِيرُ الْوَاقِعُ إِذَا لَمْ يُمْكِنْ ذَبْحُهُ، وَلَمْ يُتَوَهَّمْ مَوْتُهُ بَعْدَ الْجَرْحِ بِالْمَاءِ. وَالشَّاةُ إِنْ نَدَّتْ فِي الصَّحْرَاءِ فَهِيَ وَحْشِيَّةٌ، وَإِنْ نَدَّتْ فِي الْمِصْرِ فَلَا."]]},{"id":"tu48_15","label":"فَصْلٌ · ١٥","segs":[["matn","بِخِلَافِ الْبَعِيرِ، وَالْبَقَرِ. وَالْمُسْتَحَبُّ فِي الْإِبِلِ: النَّحْرُ، وَيُكْرَهُ الذَّبْحُ. وَفِي الْبَقَرِ، وَالْغَنَمِ الذَّبْحُ، وَيُكْرَهُ النَّحْرُ. وَالْجَنِينُ الْمَيِّتُ فِي الذَّبِيحَةِ حَرَامٌ، وَإِنْ تَمَّ خَلْقُهُ."]]},{"id":"tu48_16","label":"فَصْلٌ · ١٦","segs":[["matn","وَالْمُنْخَنِقَةُ، وَالْمَوْقُوذَةُ، وَالْمُتَرَدِّيَةُ، وَالنَّطِيحَةُ، وَفَرِيسَةُ السَّبُعِ، وَالذِّئْبِ، إِذَا ذُبِحَتْ وَفِيهَا حَيَاةٌ مِثْلُ حَيَاةِ الْمَذْبُوحِ حَلَّتْ. وَيُكْرَهُ ذَبْحُ الْحَامِلِ الْمُقْرِبِ."]]},{"id":"tu48_17","label":"فَصْلٌ · ١٧","segs":[["matn","وَلَوْ رَمَى حَمَامَةً لَهُ فِي الْهَوَاءِ، إِنْ كَانَتْ ضَالَّةً عَنْ مَنْزِلِهِ يَحِلُّ، وَإِنْ كَانَتْ تَهْتَدِي إِلَيْهِ لَمْ يَحِلَّ، إِلَّا إِذَا أَصَابَ مَذْبَحَهَا."]]},{"id":"tu48_18","label":"فَصْلٌ · ١٨","segs":[["matn","وَكَذَا الظَّبْيُ الْمُسْتَأْنَسُ، لَوْ خَرَجَ إِلَى الصَّحْرَاءِ فَرَمَاهُ رَجُلٌ، إِنْ أَصَابَ مَذْبَحَهُ حَلَّ، وَإِلَّا فَلَا."]]}],"group":"كِتَابُ الصَّيْدِ وَالذَّبَائِحِ"},{"id":"tu49","title":"كِتَابُ الْكَرَاهِيَةِ","units":[{"id":"tu49_1","label":"كِتَابُ الْكَرَاهِيَةِ · ١","segs":[["matn","كُلُّ مَكْرُوهٍ فِي كِتَابِ الْكَرَاهِيَةِ، فَهُوَ حَرَامٌ عِنْدَ مُحَمَّدٍ رَحِمَهُ اللَّهُ. وَعِنْدَ أَبِي حَنِيفَةَ، وَأَبِي يُوسُفَ رَحِمَهُمَا اللَّهُ هُوَ إِلَى الْحَرَامِ أَقْرَبُ."]]},{"id":"tu49_2","label":"كِتَابُ الْكَرَاهِيَةِ · ٢","segs":[["matn","فَلِهَذَا عَبَّرْنَا عَنْ أَكْثَرِ الْمَكْرُوهَاتِ بِالْحَرَامِ. وَيَحْرُمُ الْأَكْلُ، وَالشُّرْبُ، وَالِادِّهَانُ، وَالتَّطَيُّبُ، فِي آنِيَةِ الذَّهَبِ، وَالْفِضَّةِ، لِلرِّجَالِ وَالنِّسَاءِ."]]},{"id":"tu49_3","label":"كِتَابُ الْكَرَاهِيَةِ · ٣","segs":[["matn","وَكَذَا كُلُّ اسْتِعْمَالٍ كَالْأَكْلِ بِمِلْعَقَةِ الْفِضَّةِ وَالِاكْتِحَالِ بِمِيلِهَا، وَاتِّخَاذُ الْمُكْحُلَةِ، وَالْمِرْآةِ، وَالدَّوَاةِ مِنَ الْفِضَّةِ، وَيَحِلُّ آنِيَةُ الزُّجَاجِ، وَالْبِلَّوْرِ، وَالْعَقِيقِ، وَالنُّحَاسِ، وَالرَّصَاصِ، وَنَحْوِهَا."]]},{"id":"tu49_4","label":"كِتَابُ الْكَرَاهِيَةِ · ٤","segs":[["matn","وَيَحِلُّ الشُّرْبُ فِي الْإِنَاءِ الْمُفَضَّضِ، وَالْمُضَبَّبِ بِالْفِضَّةِ، وَالْجُلُوسُ عَلَى السَّرِيرِ، وَالْكُرْسِيِّ، وَالسَّرْجِ الْمُفَضَّضِ، بِشَرْطِ اتِّقَاءِ مَوْضِعِ الْفِضَّةِ فِي الْكُلِّ. وَكَذَا اللِّجَامُ، وَالرِّكَابُ، وَالثَّفَرُ، وَهَذَا فِيمَا يَخْلُصُ مِنْهُ شَيْءٌ."]]},{"id":"tu49_5","label":"كِتَابُ الْكَرَاهِيَةِ · ٥","segs":[["matn","فَأَمَّا التَّمْوِيهُ الَّذِي لَا يَخْلُصُ مِنْهُ شَيْءٌ، فَمُبَاحٌ مُطْلَقًا، كَالْعَلَمِ فِي الثَّوْبِ، وَمِسْمَارِ الذَّهَبِ فِي الْفَصِّ، وَيَحِلُّ تَذْهِيبُ السَّقْفِ، وَالسَّيْفِ."]]},{"id":"tu49_6","label":"كِتَابُ الْكَرَاهِيَةِ · ٦","segs":[["matn","وَمَنْ دُعِيَ إِلَى ضِيَافَةٍ، فَوَجَدَ ثَمَّ لَعِبًا، أَوْ غِنَاءً يَقْعُدُ إِنْ كَانَ غَيْرَ قُدْوَةٍ، وَيَمْنَعُ إِنْ قَدَرَ."]]},{"id":"tu49_7","label":"كِتَابُ الْكَرَاهِيَةِ · ٧","segs":[["matn","وَإِنْ كَانَ قُدْوَةً كَالْقَاضِي، وَالْمُفْتِي، وَنَحْوِهِمَا، يَمْنَعُ وَيَقْعُدُ، فَإِنْ عَجَزَ يَخْرُجُ. وَإِنْ كَانَ ذَلِكَ عَلَى الْمَائِدَةِ، أَوْ كَانُوا يَشْرَبُونَ الْخَمْرَ، خَرَجَ وَإِنْ لَمْ يَكُنْ قُدْوَةً."]]},{"id":"tu49_8","label":"كِتَابُ الْكَرَاهِيَةِ · ٨","segs":[["matn","وَإِنْ عَلِمَ قَبْلَ الْحُضُورِ لَا يَحْضُرُ فِي الْوُجُوهِ كُلِّهَا. وَيَحْرُمُ شُرْبُ لَبَنِ الْأُتُنِ وَأَبْوَالِ الْإِبِلِ: لِلتَّدَاوِي وَأَكْلُ لَحْمِ الْإِبِلِ، وَالْبَقَرِ الْجَلَّالَةِ، وَشُرْبُ لَبَنِهَا."]]},{"id":"tu49_9","label":"كِتَابُ الْكَرَاهِيَةِ · ٩","segs":[["matn","بِخِلَافِ الدَّجَاجَةِ الْمُخَلَّاةِ، فَإِنْ حُبِسَتْ وَعُلِفَتْ حَلَّتْ، وَهُوَ مُقَدَّرٌ فِي الْإِبِلِ بِأَرْبَعِينَ يَوْمًا، وَفِي الْبَقَرِ بِعِشْرِينَ يَوْمًا، وَفِي الشَّاةِ بِعَشَرَةِ أَيَّامٍ، وَفِي الدَّجَاجَةِ بِثَلَاثَةِ أَيَّامٍ."]]},{"id":"tu49_10","label":"كِتَابُ الْكَرَاهِيَةِ · ١٠","segs":[["matn","وَلَوْ رَضِعَ جَدْيٌ لَبَنَ الْخِنْزِيرِ فَهُوَ كَالْجَلَّالَةِ. وَالْحَطَبُ الْمَوْجُودُ فِي الْمَاءِ حَلَالٌ، إِنْ لَمْ يَكُنْ لَهُ قِيمَةٌ. وَالثَّمَرُ السَّاقِطُ تَحْتَ الشَّجَرِ لَا يَحِلُّ فِي الْمِصْرِ."]]},{"id":"tu49_11","label":"كِتَابُ الْكَرَاهِيَةِ · ١١","segs":[["matn","وَأَمَّا خَارِجَ الْمِصْرِ فَإِنْ كَانَ مِمَّا يَبْقَى كَالْجَوْزِ، وَاللَّوْزِ، لَا يَحِلُّ، وَإِنْ كَانَ مِمَّا لَا يَبْقَى حَلَّ، حَتَّى يَنْهَى عَنْهُ صَاحِبُهُ، وَيَحِلُّ الثَّمَرُ الْمَوْجُودُ فِي الْمَاءِ الْجَارِي، وَإِنْ كَثُرَ."]]},{"id":"tu49_12","label":"كِتَابُ الْكَرَاهِيَةِ · ١٢","segs":[["matn","وَلَوْ وَقَعَ مَا نُثِرَ مِنَ السُّكَّرِ، وَالدَّرَاهِمِ، فِي حِجْرِ رَجُلٍ، فَأَخَذَهُ غَيْرُهُ، حَلَّ، إِلَّا أَنْ يَكُونَ الْأَوَّلُ تَهَيَّأَ لَهُ، أَوْ ضَمَّهُ."]]},{"id":"tu49_13","label":"كِتَابُ الْكَرَاهِيَةِ · ١٣","segs":[["matn","وَكَذَا لَوْ وَضَعَ طَسْتًا عَلَى سَطْحِهِ، فَاجْتَمَعَ فِيهِ مَاءُ الْمَطَرِ، إِنْ وَضَعَهُ لِذَلِكَ فَهُوَ لَهُ، وَإِنْ لَمْ يَضَعْهُ لِذَلِكَ فَهُوَ لِمَنْ أَخَذَهُ."]]},{"id":"tu49_14","label":"كِتَابُ الْكَرَاهِيَةِ · ١٤","segs":[["matn","وَيَحْرُمُ أَكْلُ التُّرَابِ، وَالطِّينِ. وَيَحِلُّ خِضَابُ الْيَدِ وَالرِّجْلِ لِلنِّسَاءِ، مَا لَمْ يَكُنْ فِيهِ تَمَاثِيلُ. وَيَحْرُمُ لِلرِّجَالِ، وَالصِّبْيَانِ مُطْلَقًا. وَلَا بَأْسَ بِخِضَابِ الرَّأْسِ، وَاللِّحْيَةِ، بِالْحِنَّاءِ، وَالْوَسِمَةِ لِلرِّجَالِ وَالنِّسَاءِ."]]}],"group":"كِتَابُ الْكَرَاهِيَةِ"},{"id":"tu50","title":"فَصْلٌ","units":[{"id":"tu50_1","label":"فَصْلٌ · ١","segs":[["matn","وَيَحِلُّ لُبْسُ الْحَرِيرِ وَالْقَزِّ لِلنِّسَاءِ، لَا لِلرِّجَالِ، وَلَوْ كَانُوا مُقَاتِلِينَ، إِلَّا الْعَلَمَ الْحَرِيرَ، أَوِ الْمَنْسُوجَ بِالذَّهَبِ، قَدْرَ أَرْبَعَةِ أَصَابِعَ عَرْضًا، وَيَحِلُّ تَوَسُّدُهُ، وَالنَّوْمُ عَلَيْهِ لَهُمَا، بِخِلَافِ اللِّحَافِ."]]},{"id":"tu50_2","label":"فَصْلٌ · ٢","segs":[["matn","وَيَحِلُّ تَعْلِيقُ السُّتْرَةِ عَلَى الْبَابِ لِلْحَاجَةِ. وَيَحْرُمُ تِكَّةُ الْحَرِيرِ، وَالدِّيبَاجِ، وَلَبِنَتُهُمَا. وَيَحِلُّ لُبْسُ مَا سَدَاهُ حَرِيرٌ مُطْلَقًا. وَمَا لُحْمَتُهُ حَرِيرٌ، يَحِلُّ فِي الْحَرْبِ خَاصَّةً."]]},{"id":"tu50_3","label":"فَصْلٌ · ٣","segs":[["matn","وَلَا يَحِلُّ لِلرِّجَالِ مِنَ الذَّهَبِ شَيْءٌ، وَيَحِلُّ لَهُمْ مِنَ الْفِضَّةِ الْخَاتَمُ، وَالْمِنْطَقَةُ، وَحِلْيَةُ السَّيْفِ. وَالتَّخَتُّمُ بِالْحَجَرِ، وَالْحَدِيدِ، وَالصُّفْرِ، حَرَامٌ لِلرِّجَالِ وَالنِّسَاءِ."]]},{"id":"tu50_4","label":"فَصْلٌ · ٤","segs":[["matn","وَالْمُعْتَبَرُ الْحَلْقَةُ، فَيَجُوزُ أَنْ يَكُونَ الْفَصُّ حَجَرًا. وَيَجْعَلُ الرَّجُلُ الْفَصَّ إِلَى بَاطِنِ كَفِّهِ. وَالْأَفْضَلُ لِغَيْرِ الْقَاضِي، وَالسُّلْطَانِ، مِمَّنْ لَا يَحْتَاجُ إِلَى الْخَتْمِ تَرْكُهُ."]]},{"id":"tu50_5","label":"فَصْلٌ · ٥","segs":[["matn","وَلَا يَتَجَاوَزُ وَزْنُهُ مِثْقَالًا. وَلَا يُشَدُّ السِّنُّ الْمُتَحَرِّكُ بِالذَّهَبِ، بَلْ بِالْفِضَّةِ. وَلَوْ قُطِعَ أَنْفُهُ، أَوْ سَقَطَ سِنُّهُ، عَوَّضَهُ بِفِضَّةٍ، فَإِنْ أَنْتَنَ عَوَّضَهُ بِذَهَبٍ."]]},{"id":"tu50_6","label":"فَصْلٌ · ٦","segs":[["matn","وَيَحْرُمُ إِلْبَاسُ الصِّبْيَانِ الذَّهَبَ، وَالْحَرِيرَ، وَالْإِثْمُ عَلَى الْمُلْبِسِ. وَيَحْرُمُ حَمْلُ الْمِنْدِيلِ تَكَبُّرًا، وَيَحِلُّ لِمَسْحِ الْعَرَقِ، وَبَلَلِ الْوُضُوءِ، وَالْمُخَاطِ، وَالرِّيقِ، وَنَحْوِهَا، كَالتَّرَبُّعِ يَحِلُّ لِلْحَاجَةِ، وَيَحْرُمُ تَكَبُّرًا."]]},{"id":"tu50_7","label":"فَصْلٌ · ٧","segs":[["matn","وَيَحِلُّ رَبْطُ الرَّتِيمَةِ. وَيَحْرُمُ النَّظَرُ إِلَى غَيْرِ الْوَجْهِ، وَالْكَفَّيْنِ، مِنَ الْحُرَّةِ الْأَجْنَبِيَّةِ. وَفِي الْقَدَمِ: رِوَايَتَانِ. فَإِنْ خَافَ الشَّهْوَةَ لَمْ يَنْظُرْ إِلَى الْوَجْهِ أَيْضًا، إِلَّا لِحَاجَةٍ، وَكَذَا لَوْ شَكَّ."]]},{"id":"tu50_8","label":"فَصْلٌ · ٨","segs":[["matn","وَلَا يَحِلُّ لِلشَّابِّ مَسُّ الْوَجْهِ، وَالْكَفَّيْنِ، وَإِنْ أَمِنَ الشَّهْوَةَ، إِلَّا مِنْ عَجُوزٍ لَا تَشْتَهِي، فَتَحِلُّ لِلْمُصَافَحَةِ. وَكَذَا لَوْ كَانَ شَيْخًا، وَأَمِنَ عَلَيْهِ، وَعَلَيْهَا."]]},{"id":"tu50_9","label":"فَصْلٌ · ٩","segs":[["matn","فَإِنْ خَافَ عَلَيْهَا يَحْرُمُ. وَالصَّغِيرَةُ الَّتِي لَا تُشْتَهَى يَحِلُّ مَسُّهَا. وَيَحِلُّ لِلْقَاضِي عِنْدَ الْحُكْمِ، وَلِلشَّاهِدِ عِنْدَ الْأَدَاءِ خَاصَّةً، وَلِلْخَاطِبِ النَّظَرُ مَعَ خَوْفِ الشَّهْوَةِ، وَلَكِنْ يَقْصِدُ بِهِ الْحُكْمَ، وَالشَّهَادَةَ، وَإِقَامَةَ السُّنَّةِ بِقَدْرِ الْإِمْكَانِ، لَا قَضَاءَ الشَّهْوَةِ."]]},{"id":"tu50_10","label":"فَصْلٌ · ١٠","segs":[["matn","وَيَحِلُّ لِلطَّبِيبِ النَّظَرُ إِلَى مَوْضِعِ الْمَرَضِ مِنْهَا، إِنْ لَمْ يُمْكِنْهُ تَعْلِيمُ امْرَأَةٍ، ثُمَّ يَسْتُرُ مَا وَرَاءَ مَوْضِعِ الْمَرَضِ، وَيَنْظُرُ، وَيَغُضُّ بَصَرَهُ مَا اسْتَطَاعَ، وَكَذَا الْخَافِضَةُ، وَالْخَاتِنُ، وَالْحَاقِنُ. وَيَنْظُرُ الرَّجُلُ مِنَ الرَّجُلِ إِلَى جَمِيعِ بَدَنِهِ، إِلَّا عَوْرَتَهُ."]]},{"id":"tu50_11","label":"فَصْلٌ · ١١","segs":[["matn","وَيَمَسُّ مَا يَنْظُرُ إِلَيْهِ، وَتَنْظُرُ الْمَرْأَةُ مِنَ الرَّجُلِ إِلَى ذَلِكَ إِنْ أَمِنَتِ الشَّهْوَةَ، وَفِي رِوَايَةٍ: أَنَّهَا لَا تَنْظُرُ مِنْهُ إِلَّا إِلَى مَا يَنْظُرُ هُوَ إِلَيْهِ مِنْ مَحَارِمِهِ، وَتَنْظُرُ الْمَرْأَةُ مِنَ الْمَرْأَةِ إِلَى مَا يَنْظُرُ الرَّجُلُ إِلَيْهِ مِنَ الرَّجُلِ."]]},{"id":"tu50_12","label":"فَصْلٌ · ١٢","segs":[["matn","وَيَنْظُرُ مِنْ أَمَتِهِ الَّتِي تَحِلُّ لَهُ، وَزَوْجَتِهِ، إِلَى جَمِيعِ بَدَنِهَا، وَيَنْظُرُ مِنْ مَحَارِمِهِ إِلَى مَا وَرَاءَ الْبَطْنِ، وَالظَّهْرِ، وَالْفَخِذِ."]]},{"id":"tu50_13","label":"فَصْلٌ · ١٣","segs":[["matn","وَالْمَحْرَمُ: كُلُّ مَنْ يَحْرُمُ نِكَاحُهُ عَلَى التَّأْبِيدِ، بِنَسَبٍ، أَوْ رَضَاعٍ، أَوْ صِهْرِيَّةٍ، وَلَوْ أَنَّهَا بِزِنًا. وَيَمَسُّ ذَلِكَ أَيْضًا. فَإِنْ خَافَ عَلَيْهِ، أَوْ عَلَيْهَا، لَمْ يَنْظُرْ، وَلَمْ يَمَسَّ. وَلَا بَأْسَ بِالْخَلْوَةِ بِهَا وَالسَّفَرِ مَعَهَا."]]},{"id":"tu50_14","label":"فَصْلٌ · ١٤","segs":[["matn","وَيَنْظُرُ مِنْ أَمَةِ غَيْرِهِ إِذَا أَمِنَ الشَّهْوَةَ إِلَى مَا يَنْظُرُ إِلَيْهِ مِنْ مَحَارِمِهِ، وَلَوْ كَانَتْ أُمَّ وَلَدِهِ، أَوْ مُكَاتَبَتَهُ، أَوْ مُدَبَّرَتَهُ، أَوْ مُسْتَسْعَاتَهُ."]]},{"id":"tu50_15","label":"فَصْلٌ · ١٥","segs":[["matn","وَفِي الْخَلْوَةِ بِهَا، وَالسَّفَرِ مَعَهَا قَوْلَانِ. وَيَحِلُّ لَهُ مَسُّ ذَلِكَ وَقْتَ الشِّرَاءِ، وَإِنْ خَافَ الشَّهْوَةَ."]]},{"id":"tu50_16","label":"فَصْلٌ · ١٦","segs":[["matn","وَقِيلَ: يَحِلُّ لَهُ النَّظَرُ إِلَيْهَا وَقْتَ الشِّرَاءِ مَعَ خَوْفِ الشَّهْوَةِ، وَلَا يَحِلُّ الْمَسُّ مَعَهُ. وَالْخَصِيُّ، وَالْمَجْبُوبُ، وَالْمُخَنَّثُ، كَالْفَحْلِ فِي حُكْمِ النَّظَرِ، وَالْمَسِّ."]]},{"id":"tu50_17","label":"فَصْلٌ · ١٧","segs":[["matn","وَالْعَبْدُ كَالْأَجْنَبِيِّ فِي رُؤْيَةِ سَيِّدَتِهِ، وَيَحِلُّ لَهُ الدُّخُولُ عَلَيْهَا مِنْ غَيْرِ إِذْنٍ. وَيَعْزِلُ عَنْ أَمَتِهِ بِغَيْرِ إِذْنِهَا، وَعَنْ زَوْجَتِهِ الْحُرَّةِ بِإِذْنِهَا، وَيَعْزِلُ عَنْ زَوْجَتِهِ الْأَمَةِ بِإِذْنِ مَوْلَاهَا."]]},{"id":"tu50_18","label":"فَصْلٌ · ١٨","segs":[["matn","وَيُكْرَهُ تَقْبِيلُ الرَّجُلِ الرَّجُلَ، وَمُعَانَقَتُهُ وَلَا بَأْسَ بِالْمُصَافَحَةِ. وَقِيلَ: لَا بَأْسَ بِهِمَا أَيْضًا، إِذَا قَصَدَ الْمَبَرَّةَ، وَالْإِكْرَامَ. وَلَا بَأْسَ بِتَقْبِيلِ يَدِ الْعَالِمِ، وَالسُّلْطَانِ الْعَادِلِ."]]}],"group":"كِتَابُ الْكَرَاهِيَةِ"},{"id":"tu51","title":"فَصْلٌ","units":[{"id":"tu51_1","label":"فَصْلٌ · ١","segs":[["matn","وَيَحْرُمُ احْتِكَارُ أَقْوَاتِ النَّاسِ، وَالْبَهَائِمِ فَقَطْ فِي الْبَلَدِ الصَّغِيرِ. وَمَنِ احْتَكَرَ غَلَّةَ أَرْضِهِ، أَوْ مَا جَلَبَهُ مِنْ بَلَدٍ آخَرَ حَلَّ."]]},{"id":"tu51_2","label":"فَصْلٌ · ٢","segs":[["matn","وَيَحْرُمُ التَّسْعِيرُ، إِلَّا إِذَا تَعَيَّنَ دَفْعًا لِلضَّرَرِ الْعَامِّ. وَيَحْرُمُ بَيْعُ أَرَاضِي مَكَّةَ، وَإِجَارَتُهَا، وَلَا يَحْرُمُ بَيْعُ أَبْنِيَتِهَا. وَيُكْرَهُ التَّعْشِيرُ فِي الْمُصْحَفِ، وَالنَّقْطُ."]]},{"id":"tu51_3","label":"فَصْلٌ · ٣","segs":[["matn","وَقِيلَ: يُبَاحُ فِي زَمَانِنَا. وَيُبَاحُ تَحْلِيَةُ الْمُصْحَفِ، وَنَقْشُ الْمَسْجِدِ، وَزَخْرَفَتُهُ بِمَاءِ الذَّهَبِ، مِنْ غَيْرِ مَالِ الْوَقْفِ. وَيَحْرُمُ اسْتِخْدَامُ الْخِصْيَانِ. وَلَا بَأْسَ بِخِصَاءِ الْبَهَائِمِ، وَإِنْزَاءِ الْحَمِيرِ عَلَى الْخَيْلِ."]]},{"id":"tu51_4","label":"فَصْلٌ · ٤","segs":[["matn","وَلَا بَأْسَ بِعِيَادَةِ الذِّمِّيِّ. وَيَحْرُمُ قَوْلُهُ فِي الدُّعَاءِ: أَسْأَلُكَ بِمَعْقِدِ الْعِزِّ مِنْ عَرْشِكَ، وَبِحَقِّ فُلَانٍ، وَبِحَقِّ النَّبِيِّ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ."]]},{"id":"tu51_5","label":"فَصْلٌ · ٥","segs":[["matn","وَيَحْرُمُ اللَّعِبُ بِالنَّرْدِ، وَالشِّطْرَنْجِ، وَكُلُّ لَهْوٍ، إِلَّا الْمُنَاضَلَةَ، وَالْمُسَابَقَةَ بِالْخَيْلِ، وَمُلَاعَبَةَ الْأَهْلِ. وَيُبَاحُ السَّلَامُ عَلَى الْمَشْغُولِ بِالشِّطْرَنْجِ، وَالنَّرْدِ، بِنِيَّةِ التَّشْوِيشِ."]]},{"id":"tu51_6","label":"فَصْلٌ · ٦","segs":[["matn","وَقِيلَ: لَا يُبَاحُ. وَالْجَوْزُ الَّذِي يَلْعَبُ بِهِ الصِّبْيَانُ يَوْمَ الْعِيدِ يُؤْكَلُ، إِنْ لَمْ يُقَامِرُوا بِهِ."]]},{"id":"tu51_7","label":"فَصْلٌ · ٧","segs":[["matn","وَسَمَاعُ صَوْتِ الْمَلَاهِي كُلِّهَا حَرَامٌ، فَإِنْ سَمِعَ بَغْتَةً فَهُوَ مَعْذُورٌ، ثُمَّ يَجْتَهِدُ أَنْ لَا يَسْمَعَ مَهْمَا أَمْكَنَهُ، وَيَحِلُّ ضَرْبُ الدُّفِّ فِي الْعُرْسِ؛ لِإِعْلَانِ النِّكَاحِ."]]},{"id":"tu51_8","label":"فَصْلٌ · ٨","segs":[["matn","وَضَرْبُ الطَّبْلِ فِي الْحَجِّ، وَالْغَزْوِ؛ لِلْإِعْلَامِ، لَا لِلَّهْوِ. وَمَا يَأْخُذُهُ الْمُغَنِّي، وَالنَّائِحَةُ مِنْ غَيْرِ شَرْطٍ مُبَاحٌ، وَمَعَ شَرْطٍ حَرَامٌ."]]},{"id":"tu51_9","label":"فَصْلٌ · ٩","segs":[["matn","وَلَا تَرْكَبُ الْمَرْأَةُ عَلَى السَّرْجِ، إِلَّا لِلضَّرُورَةِ فِي سَفَرِ الْحَجِّ، فَتَرْكَبُ مُسْتَتِرَةً. وَمَنْ رَأَى مُنْكَرًا وَهُوَ مِمَّنْ يَفْعَلُهُ، يَلْزَمُهُ النَّهْيُ عَنْهُ."]]},{"id":"tu51_10","label":"فَصْلٌ · ١٠","segs":[["matn","حَامِلٌ اعْتَرَضَ الْوَلَدُ فِي بَطْنِهَا وَقْتَ الْوِلَادَةِ، وَخِيفَ عَلَيْهَا، وَلَمْ يُمْكِنْ إِخْرَاجُهُ إِلَّا بِقَطْعِهِ، لَمْ يَجُزْ قَطْعُهُ، إِلَّا إِذَا كَانَ مَيِّتًا."]]},{"id":"tu51_11","label":"فَصْلٌ · ١١","segs":[["matn","حَامِلٌ مَاتَتْ فَتَحَرَّكَ فِي بَطْنِهَا الْوَلَدُ، فَإِنْ غَلَبَ عَلَى الظَّنِّ حَيَاتُهُ وَبَقَاؤُهُ، يُشَقُّ بَطْنُهَا مِنَ الْجَانِبِ الْأَيْسَرِ، وَيُخْرَجُ."]]},{"id":"tu51_12","label":"فَصْلٌ · ١٢","segs":[["matn","وَيُبَاحُ لِلْمَرْأَةِ إِسْقَاطُ الْوَلَدِ، مَا لَمْ يَسْتَبِنْ شَيْءٌ مِنْ خَلْقِهِ. رَجُلٌ ابْتَلَعَ دُرَّةً، أَوْ ذَهَبًا لِغَيْرِهِ، ثُمَّ مَاتَ وَلَمْ يَتْرُكْ شَيْئًا، لَا يُشَقُّ بَطْنُهُ."]]},{"id":"tu51_13","label":"فَصْلٌ · ١٣","segs":[["matn","نَعَامَةٌ ابْتَلَعَتْ لُؤْلُؤَةً، أَوْ شَاةٌ نَشِبَ رَأْسُهَا فِي وِعَاءٍ، وَتَعَذَّرَ إِخْرَاجُهُ، يُنْظَرُ إِلَى أَكْثَرِهِمَا قِيمَةً، فَيَغْرَمُ مَالِكُهُ قِيمَةَ الْآخَرِ، وَيَصْنَعُ بِهِ مَا شَاءَ."]]},{"id":"tu51_14","label":"فَصْلٌ · ١٤","segs":[["matn","وَيُكْرَهُ قَتْلُ النَّمْلَةِ مَا لَمْ تَبْدَأْ بِالْإِيذَاءِ. وَقَتْلُ الْقَمْلَةِ يَجُوزُ مُطْلَقًا. وَيُكْرَهُ إِحْرَاقُ الْقَمْلَةِ، وَالْعَقْرَبِ، وَنَحْوِهِمَا بِالنَّارِ، وَطَرْحُهَا حَيَّةً مُبَاحٌ، وَلَيْسَ بِأَدَبٍ."]]},{"id":"tu51_15","label":"فَصْلٌ · ١٥","segs":[["matn","وَالْخِتَانُ لِلرِّجَالِ سُنَّةٌ، وَلِلنِّسَاءِ مَكْرُمَةٌ. وَتُضْرَبُ الدَّابَّةُ عَلَى النِّفَارِ، دُونَ الْعِثَارِ، وَرَكْضُ الدَّابَّةِ وَنَخْسُهَا لِلْعَرْضِ عَلَى الْمُشْتَرِي، أَوْ لِلَّهْوِ مَكْرُوهٌ، وَلِلْجِهَادِ وَغَيْرِهِ، مِنْ غَرَضٍ صَحِيحٍ مُبَاحٌ."]]},{"id":"tu51_16","label":"فَصْلٌ · ١٦","segs":[["matn","وَالسَّلَامُ سُنَّةٌ، وَرَدُّهُ فَرْضُ كِفَايَةٍ وَثَوَابُ الْمُسَلِّمِ أَكْثَرُ. وَلَا يَجِبُ رَدُّ سَلَامِ السَّائِلِ، وَلَا يَنْبَغِي أَنْ يُسَلِّمَ عَلَى مَنْ يَقْرَأُ الْقُرْآنَ."]]},{"id":"tu51_17","label":"فَصْلٌ · ١٧","segs":[["matn","وَتَشْمِيتُ الْعَاطِسِ، فَرْضُ كِفَايَةٍ. وَيُكْرَهُ تَعْلِيمُ الْبَازِي بِالطَّيْرِ الْحَيِّ، وَيُبَاحُ بِالْمَذْبُوحِ. وَيُكْرَهُ الْغُلُّ فِي عُنُقِ الْعَبْدِ، وَلَا يُكْرَهُ الْقَيْدُ لِخَوْفِ الْإِبَاقِ."]]},{"id":"tu51_18","label":"فَصْلٌ · ١٨","segs":[["matn","وَيُبَاحُ الْجُلُوسُ فِي الطَّرِيقِ لِلْبَيْعِ، إِذَا كَانَ وَاسِعًا لَا يَتَضَرَّرُ النَّاسُ بِهِ. وَتُكْرَهُ الْخِيَاطَةُ فِي الْمَسْجِدِ، وَكُلُّ عَمَلٍ مِنْ أَعْمَالِ الدُّنْيَا."]]},{"id":"tu51_19","label":"فَصْلٌ · ١٩","segs":[["matn","وَيُكْرَهُ الْجُلُوسُ فِيهِ لِلْمُصِيبَةِ ثَلَاثَةَ أَيَّامٍ، وَيُبَاحُ فِي غَيْرِهِ، وَالتَّرْكُ أَوْلَى. وَلَوْ جَلَسَ فِيهِ مُعَلِّمٌ، أَوْ وَرَّاقٌ، فَإِنْ كَانَ حِسْبَةً لَا بَأْسَ بِهِ، وَإِنْ كَانَ بِأُجْرَةٍ يُكْرَهُ، إِلَّا لِضَرُورَةٍ تَكُونُ بِهِمَا."]]},{"id":"tu51_20","label":"فَصْلٌ · ٢٠","segs":[["matn","وَيُكْرَهُ تَمَنِّي الْمَوْتِ لِضِيقِ الْمَعِيشَةِ، أَوْ لِلْغَضَبِ مِنْ وَلَدِهِ، أَوْ غَيْرِهِ، وَلَا بَأْسَ بِتَمَنِّيهِ لِتَغَيُّرِ أَهْلِ الزَّمَانِ، وَظُهُورِ الْمَعَاصِي؛ خَوْفًا مِنَ الْوُقُوعِ فِيهَا."]]},{"id":"tu51_21","label":"فَصْلٌ · ٢١","segs":[["matn","رَجُلٌ يَتَرَدَّدُ إِلَى الظَّلَمَةِ؛ لِيَدْفَعَ شَرَّهُمْ عَنْهُ، فَإِنْ كَانَ مُفْتِيًا، أَوْ مُقْتَدًى بِهِ، لَا يَحِلُّ لَهُ ذَلِكَ. وَاللَّهُ أَعْلَمُ."]]}],"group":"كِتَابُ الْكَرَاهِيَةِ"},{"id":"tu52","title":"كِتَابُ الْفَرَائِضِ","units":[{"id":"tu52_1","label":"كِتَابُ الْفَرَائِضِ · ١","segs":[["matn","الْفُرُوضُ الْمُقَدَّرَةُ فِي الْقُرْآنِ سِتَّةٌ: النِّصْفُ، وَالرُّبُعُ، وَالثُّمُنُ، وَالثُّلُثُ، وَالثُّلُثَانِ، وَالسُّدُسُ. وَأَصْحَابُهَا: اثْنَا عَشَرَ. أَرْبَعَةٌ مِنَ الرِّجَالِ، وَثَمَانٍ مِنَ النِّسَاءِ."]]},{"id":"tu52_2","label":"كِتَابُ الْفَرَائِضِ · ٢","segs":[["matn","أَمَّا الرِّجَالُ: فَالْأَبُ، وَالْجَدُّ، وَالْأَخُ لِأُمٍّ، وَالزَّوْجُ. وَأَمَّا النِّسَاءُ: فَالْأُمُّ، وَالْجَدَّةُ، وَالْبِنْتُ، وَبِنْتُ الِابْنِ، وَالْأُخْتُ لِأَبٍ وَأُمٍّ، أَوْ لِأَبٍ، أَوْ لِأُمٍّ، وَالزَّوْجَةُ."]]},{"id":"tu52_3","label":"كِتَابُ الْفَرَائِضِ · ٣","segs":[["matn","فَالْأَبُ لَهُ السُّدُسُ مَعَ الِابْنِ، أَوِ ابْنِ الِابْنِ، وَالتَّعْصِيبُ عِنْدَ عَدَمِ الْوَلَدِ، وَوَلَدِ الِابْنِ. وَكِلَاهُمَا مَعَ الْبِنْتِ، وَبِنْتِ الِابْنِ."]]},{"id":"tu52_4","label":"كِتَابُ الْفَرَائِضِ · ٤","segs":[["matn","وَالْجَدُّ فِي أَحْوَالِهِ كَالْأَبِ. وَالْأَخُ لِأُمٍّ لَهُ السُّدُسُ، وَلِلِاثْنَيْنِ فَصَاعِدًا الثُّلُثُ. وَالزَّوْجُ لَهُ النِّصْفُ عِنْدَ عَدَمِ الْوَلَدِ وَوَلَدِ الِابْنِ، وَالرُّبُعُ مَعَ أَحَدِهِمَا."]]},{"id":"tu52_5","label":"كِتَابُ الْفَرَائِضِ · ٥","segs":[["matn","وَالْأُمُّ لَهَا السُّدُسُ مَعَ الْوَلَدِ وَوَلَدِ الِابْنِ، وَالِاثْنَيْنِ مِنَ الْإِخْوَةِ وَالْأَخَوَاتِ فَصَاعِدًا مِنْ أَيِّ جِهَةٍ كَانُوا، وَالثُّلُثُ عِنْدَ عَدَمِ هَؤُلَاءِ."]]},{"id":"tu52_6","label":"كِتَابُ الْفَرَائِضِ · ٦","segs":[["matn","وَثُلُثُ مَا يَبْقَى فِي الْمَسْأَلَتَيْنِ وَهُمَا: زَوْجٌ، وَأَبَوَانِ، أَوْ زَوْجَةٌ وَأَبَوَانِ. وَلَوْ كَانَ مَكَانَ الْأَبِ جَدٌّ، فَلَهَا الثُّلُثُ كَامِلًا فِي الْأَصَحِّ."]]},{"id":"tu52_7","label":"كِتَابُ الْفَرَائِضِ · ٧","segs":[["matn","وَالْجَدَّةُ أُمُّ الْأُمِّ، وَأُمُّ الْأَبِ، لَهَا السُّدُسُ، وَاحِدَةً كَانَتْ، أَوْ أَكْثَرَ. وَلِلْبِنْتِ الْوَاحِدَةِ النِّصْفُ، وَلِلثِّنْتَيْنِ فَصَاعِدًا الثُّلُثَانِ. وَكَذَا بِنْتُ الِابْنِ عِنْدَ عَدَمِ بِنْتِ الصُّلْبِ."]]},{"id":"tu52_8","label":"كِتَابُ الْفَرَائِضِ · ٨","segs":[["matn","وَلَهَا وَاحِدَةً كَانَتْ، أَوْ أَكْثَرَ مَعَ بِنْتِ الصُّلْبِ، السُّدُسُ تَكْمِلَةً لِلثُّلُثَيْنِ. وَالْأُخْتُ لِأَبٍ وَأُمٍّ، لَهَا النِّصْفُ، وَلِلثِّنْتَيْنِ فَصَاعِدًا الثُّلُثَانِ، وَالْأُخْتُ لِأَبٍ كَذَلِكَ عِنْدَ عَدَمِ الْأُخْتِ لِأَبٍ وَأُمٍّ."]]},{"id":"tu52_9","label":"كِتَابُ الْفَرَائِضِ · ٩","segs":[["matn","وَلَهَا وَاحِدَةً كَانَتْ، أَوْ أَكْثَرَ مَعَ الْأُخْتِ لِأَبٍ وَأُمٍّ، السُّدُسُ تَكْمِلَةً لِلثُّلُثَيْنِ. وَالْأُخْتُ لِأُمٍّ كَالْأَخِ لِأُمٍّ، ذُكُورُهُمْ وَإِنَاثُهُمْ فِي الِاسْتِحْقَاقِ وَالْقِسْمَةِ سَوَاءٌ."]]},{"id":"tu52_10","label":"كِتَابُ الْفَرَائِضِ · ١٠","segs":[["matn","وَالزَّوْجَةُ لَهَا الرُّبُعُ عِنْدَ عَدَمِ الْوَلَدِ وَوَلَدِ الِابْنِ، وَاحِدَةً كَانَتْ، أَوْ أَكْثَرَ. وَالثُّمُنُ مَعَ أَحَدِهِمْ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"tu53","title":"فَصْلٌ","units":[{"id":"tu53_1","label":"فَصْلٌ · ١","segs":[["matn","الْعَصَبَةُ قِسْمَانِ: عَصَبَةُ نَسَبٍ، وَعَصَبَةُ سَبَبٍ. فَعَصَبَةُ النَّسَبِ ثَلَاثَةُ أَصْنَافٍ: عَصَبَةٌ بِنَفْسِهِ، وَعَصَبَةٌ بِغَيْرِهِ، وَعَصَبَةٌ مَعَ غَيْرِهِ."]]},{"id":"tu53_2","label":"فَصْلٌ · ٢","segs":[["matn","فَالْعَصَبَةُ بِنَفْسِهِ: كُلُّ ذَكَرٍ يُدْلِي إِلَى الْمَيِّتِ بِمَحْضِ الذُّكُورِ، كَالْأَبِ وَآبَائِهِ، وَالِابْنِ وَأَبْنَائِهِ، وَالْأَخِ لِأَبٍ وَأُمٍّ، أَوْ لِأَبٍ، وَأَبْنَائِهِمَا، وَالْعَمِّ لِأَبٍ وَأُمٍّ، أَوْ لِأَبٍ، وَأَبْنَائِهِمَا."]]},{"id":"tu53_3","label":"فَصْلٌ · ٣","segs":[["matn","وَالصِّنْفُ الْأَوَّلُ مُقَدَّمٌ، ثُمَّ الثَّانِي، ثُمَّ الثَّالِثُ، ثُمَّ الرَّابِعُ. فَإِنِ اجْتَمَعَ اثْنَانِ مِنْ صِنْفٍ وَاحِدٍ، قُدِّمَ أَعْلَاهُمَا دَرَجَةً، فَإِنِ اسْتَوَيَا فِي الدَّرَجَةِ قُدِّمَ ذُو الْجِهَتَيْنِ."]]},{"id":"tu53_4","label":"فَصْلٌ · ٤","segs":[["matn","وَالْعَصَبَةُ بِغَيْرِهِ: كُلُّ أُنْثَى فَرْضُهَا النِّصْفُ، تَصِيرُ عَصَبَةً بِأَخِيهَا، فَلَا يُفْرَضُ لَهَا، وَيَكُونُ الْمَالُ بَيْنَهُمَا لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ."]]},{"id":"tu53_5","label":"فَصْلٌ · ٥","segs":[["matn","وَهِيَ الْبِنْتُ، وَبِنْتُ الِابْنِ، وَالْأُخْتُ لِأَبٍ وَأُمٍّ، أَوْ لِأَبٍ. وَلَا يُعَصِّبُ عَصَبَةٌ أُخْتَهُ غَيْرُ هَؤُلَاءِ."]]},{"id":"tu53_6","label":"فَصْلٌ · ٦","segs":[["matn","وَعَصَبَةٌ مَعَ غَيْرِهِ: الْأَخَوَاتُ لِأَبٍ وَأُمٍّ، أَوْ لِأَبٍ، يَصِرْنَ عَصَبَةً مَعَ الْبَنَاتِ، وَبَنَاتِ الِابْنِ. وَعَصَبَةُ السَّبَبِ: الْمُعْتِقُ ذَكَرًا كَانَ، أَوْ أُنْثَى، وَعَصَبَتُهُ."]]},{"id":"tu53_7","label":"فَصْلٌ · ٧","segs":[["matn","وَهُوَ آخِرُ الْعَصَبَاتِ. وَالْعَصَبَةُ تَأْخُذُ كُلَّ الْمَالِ عِنْدَ عَدَمِ صَاحِبِ الْفَرْضِ، وَمَا بَقِيَ بَعْدَ الْفَرْضِ مَعَ وُجُودِ صَاحِبِ الْفَرْضِ، وَإِنْ لَمْ يَبْقَ شَيْءٌ سَقَطَ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"tu54","title":"فَصْلٌ","units":[{"id":"tu54_1","label":"فَصْلٌ · ١","segs":[["matn","سِتَّةٌ لَا يَسْقُطُونَ بِحَالٍ: الْأَبَوَانِ، وَالزَّوْجَانِ، وَالِابْنُ، وَالْبِنْتُ، وَمَنْ سِوَاهُمْ مِنَ الْوَرَثَةِ، فَالْأَقْرَبُ مِنْهُمْ يَحْجُبُ الْأَبْعَدَ. وَضَابِطُهُ: أَنَّ كُلَّ مَنِ انْتَسَبَ إِلَى الْمَيِّتِ بِوَاسِطَةٍ، لَا يَرِثُ مَعَ وُجُودِ تِلْكَ الْوَاسِطَةِ، إِلَّا الْإِخْوَةَ لِأُمٍّ."]]},{"id":"tu54_2","label":"فَصْلٌ · ٢","segs":[["matn","وَيَسْقُطُ الْأَجْدَادُ بِالْأَبِ، وَالْجَدَّاتُ مِنَ الْجِهَتَيْنِ بِالْأُمِّ، وَالْأَبَوِيَّاتُ خَاصَّةً بِالْأَبِ، وَأَوْلَادُ الِابْنِ بِالِابْنِ، وَالْإِخْوَةُ وَالْأَخَوَاتُ بِالِابْنِ وَابْنِ الِابْنِ وَالْأَبِ وَالْجَدِّ، وَأَوْلَادُ الْأَبِ بِهَؤُلَاءِ وَبِأَخٍ لِأَبٍ وَأُمٍّ."]]},{"id":"tu54_3","label":"فَصْلٌ · ٣","segs":[["matn","وَالْبُعْدَى مِنَ الْجَدَّاتِ، تُحْجَبُ بِالْقُرْبَى مِنْ أَيِّ جِهَةٍ كَانَتْ، وَأَوْلَادُ الْأُمِّ بِالْوَلَدِ، وَوَلَدِ الِابْنِ، وَالْأَبِ، وَالْجَدِّ، وَإِذَا أَخَذَتِ الْبَنَاتُ الثُّلُثَيْنِ، سَقَطَتْ بَنَاتُ الِابْنِ، إِلَّا أَنْ يَكُونَ مَعَهُنَّ، أَوْ أَسْفَلَ مِنْهُنَّ ذَكَرٌ، فَيُعَصِّبُهُنَّ."]]},{"id":"tu54_4","label":"فَصْلٌ · ٤","segs":[["matn","وَإِذَا أَخَذَتِ الْأَخَوَاتُ لِأَبٍ وَأُمٍّ الثُّلُثَيْنِ، سَقَطَتِ الْأَخَوَاتُ لِأَبٍ، إِلَّا أَنْ يَكُونَ مَعَهُنَّ أَخٌ فَيُعَصِّبُهُنَّ. وَالْمَحْجُوبُ يَحْجُبُ، كَالْأَخَوَيْنِ مَعَ الْأَبِ وَالْأُمِّ، وَأُمِّ الْأَبِ وَأُمِّ أُمِّ الْأُمِّ مَعَ الْأَبِ."]]},{"id":"tu54_5","label":"فَصْلٌ · ٥","segs":[["matn","وَالْمَحْرُومُ لَا يَحْجُبُ. وَأَسْبَابُ الْحِرْمَانِ أَرْبَعَةٌ: الرِّقُّ كَامِلًا كَانَ، أَوْ نَاقِصًا. وَالْقَتْلُ الَّذِي يَحْجُبُ مَا يَجِبُ بِهِ الْقِصَاصُ، أَوِ الْكَفَّارَةُ. وَاخْتِلَافُ الدِّينَيْنِ، وَاخْتِلَافُ الدَّارَيْنِ، حَقِيقَةً، أَوْ حُكْمًا."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"tu55","title":"فَصْلٌ","units":[{"id":"tu55_1","label":"فَصْلٌ · ١","segs":[["matn","ذُو الرَّحِمِ: كُلُّ قَرِيبٍ لَيْسَ صَاحِبَ فَرْضٍ، وَلَا عَصَبَةً. وَهُمْ أَرْبَعَةُ أَصْنَافٍ: الصِّنْفُ الْأَوَّلُ: أَوْلَادُ الْبَنَاتِ، وَأَوْلَادُ بَنَاتِ الِابْنِ، وَإِنْ سَفَلُوا."]]},{"id":"tu55_2","label":"فَصْلٌ · ٢","segs":[["matn","الثَّانِي: الْأَجْدَادُ الْفَاسِدُونَ، وَالْجَدَّاتُ الْفَاسِدَاتُ، وَإِنْ عَلَوْا. الثَّالِثُ: بَنَاتُ الْإِخْوَةِ مُطْلَقًا وَأَوْلَادُ الْأَخَوَاتِ مُطْلَقًا، وَبَنُو الْإِخْوَةِ لِأُمٍّ. الرَّابِعُ: عَمَّاتُ الْمَيِّتِ، وَأَخْوَالُهُ، وَخَالَاتُهُ مُطْلَقًا، وَأَعْمَامُهُ لِأُمٍّ، وَبَنَاتُ عَمِّهِ مُطْلَقًا."]]},{"id":"tu55_3","label":"فَصْلٌ · ٣","segs":[["matn","وَالْجَدُّ الْفَاسِدُ: كُلُّ جَدٍّ يَدْخُلُ بَيْنَهُ وَبَيْنَ الْمَيِّتِ أُمٌّ. وَالْجَدَّةُ الْفَاسِدَةُ: كُلُّ جَدَّةٍ يَدْخُلُ بَيْنَهَا وَبَيْنَ الْمَيِّتِ ذَكَرٌ بَيْنَ أُنْثَيَيْنِ. وَكُلُّ مَنْ تَفَرَّعَ مِنْهُمْ ذَوُو الْأَرْحَامِ."]]},{"id":"tu55_4","label":"فَصْلٌ · ٤","segs":[["matn","وَلَا يَرِثُونَ إِلَّا إِذَا لَمْ يَكُنْ لِلْمَيِّتِ صَاحِبُ فَرْضٍ، غَيْرُ الزَّوْجِ وَالزَّوْجَةِ، وَلَا عَصَبَةٌ. وَيُقَدَّمُ الصِّنْفُ الْأَوَّلُ، ثُمَّ الثَّانِي، ثُمَّ الثَّالِثُ، ثُمَّ الرَّابِعُ."]]},{"id":"tu55_5","label":"فَصْلٌ · ٥","segs":[["matn","وَمَتَى اجْتَمَعَ ذَكَرٌ وَأُنْثَى مِنْ صِنْفٍ وَاحِدٍ، وَتَسَاوَوْا فِي الدَّرَجَةِ وَالْجِهَةِ، قُسِمَ الْمَالُ بَيْنَهُمَا، لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ. وَإِنْ وُجِدَ مِنْهُمْ وَاحِدٌ لَا غَيْرُ، أَخَذَ كُلَّ الْمَالِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"tu56","title":"فَصْلٌ","units":[{"id":"tu56_1","label":"فَصْلٌ · ١","segs":[["matn","الْمَفْقُودُ حَيٌّ فِي مَالِهِ، فَلَا يُورَثُ حَتَّى يَحْكُمَ الْحَاكِمُ بِمَوْتِهِ إِذَا مَاتَ أَقْرَانُهُ، وَهُوَ مَوْقُوفٌ فِي الْحَالِ فِي مَالِ غَيْرِهِ، فَيُوقَفُ نَصِيبُهُ مِنْهُ كَالْحَمْلِ."]]},{"id":"tu56_2","label":"فَصْلٌ · ٢","segs":[["matn","وَإِذَا حُكِمَ بِمَوْتِهِ، فَمَالُهُ لِوَرَثَتِهِ الْمَوْجُودِينَ عِنْدَ الْحُكْمِ بِمَوْتِهِ، وَالْمَوْقُوفُ لَهُ مِنْ مَالِ غَيْرِهِ، يُرَدُّ إِلَى وَرَثَةِ ذَلِكَ الْغَيْرِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"tu57","title":"فَصْلٌ","units":[{"id":"tu57_1","label":"فَصْلٌ · ١","segs":[["matn","إِذَا مَاتَ جَمَاعَةٌ بِغَرَقٍ، أَوْ حَرْقٍ، أَوْ هَدْمٍ، وَلَمْ يُعْلَمْ تَرْتِيبُ مَوْتِهِمْ، جُعِلَ كَأَنَّهُمْ مَاتُوا مَعًا، فَمَالُ كُلِّ وَاحِدٍ مِنْهُمْ لِوَرَثَتِهِ الْأَحْيَاءِ، وَلَا يُعْتَدُّ بِوَاحِدٍ مِنَ الْغَرْقَى، وَنَحْوِهِمْ فِي وَرَثَةِ الْبَاقِينَ فِي إِرْثٍ، وَلَا فِي حَجْبٍ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"tu58","title":"فَصْلٌ","units":[{"id":"tu58_1","label":"فَصْلٌ · ١","segs":[["matn","الْكُفْرُ كُلُّهُ مِلَّةٌ وَاحِدَةٌ، فَيَرِثُ الْكُفَّارُ كُلُّهُمْ بَعْضُهُمْ مِنْ بَعْضٍ، بِالنَّسَبِ، وَالنِّكَاحِ، وَالْوَلَاءِ، إِلَّا أَنْ تَخْتَلِفَ دَارُهُمْ كَمَا مَرَّ. أَمَّا الْمُرْتَدُّ، فَلَا يَرِثُ مِنْ أَحَدٍ. وَحُكْمُ مَالِهِ ذَكَرْنَاهُ فِي كِتَابِ الْجِهَادِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"tu59","title":"فَصْلٌ","units":[{"id":"tu59_1","label":"فَصْلٌ · ١","segs":[["matn","الْحَمْلُ يُوقَفُ لَهُ نَصِيبُ ابْنٍ وَاحِدٍ، أَوْ بِنْتٍ وَاحِدَةٍ، أَيُّهُمَا كَانَ أَكْثَرَ، وَيُقْسَمُ الْبَاقِي بَيْنَهُمَا."]]},{"id":"tu59_2","label":"فَصْلٌ · ٢","segs":[["matn","وَإِنَّمَا يُعْطَى مَا وُقِفَ لَهُ، بِشَرْطِ أَنْ يُولَدَ حَيًّا فِي مُدَّةٍ يُعْلَمُ أَنَّهُ كَانَ مَوْجُودًا فِي بَطْنِ أُمِّهِ عِنْدَ مَوْتِ مُوَرِّثِهِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"tu60","title":"فَصْلٌ","units":[{"id":"tu60_1","label":"فَصْلٌ · ١","segs":[["matn","إِذَا فَضَلَتِ التَّرِكَةُ عَنْ فُرُوضِ الْوَرَثَةِ، وَلَمْ يَكُنْ مَعَهُمْ عَصَبَةٌ، فَالْبَاقِي يُرَدُّ عَلَيْهِمْ بِقَدْرِ فُرُوضِهِمْ. إِلَّا عَلَى الزَّوْجَيْنِ، فَإِنَّهُ لَا يُرَدُّ عَلَيْهِمَا، بَلْ يُوضَعُ الْبَاقِي فِي بَيْتِ الْمَالِ."]]},{"id":"tu60_2","label":"فَصْلٌ · ٢","segs":[["matn","إِنْ لَمْ يَكُنْ لِلْمَيِّتِ أَحَدٌ مِنْ ذَوِي الْأَرْحَامِ، فَإِنْ كَانَ الْوَارِثُ وَاحِدًا مِنْ أَصْحَابِ الْفُرُوضِ، أَخَذَ كُلَّ الْمَالِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"tu61","title":"كِتَابُ الْكَسْبِ وَالْأَدَبِ","units":[{"id":"tu61_1","label":"كِتَابُ الْكَسْبِ وَالْأَدَبِ · ١","segs":[["matn","طَلَبُ الْكَسْبِ لَازِمٌ، كَطَلَبِ الْعِلْمِ. وَهُوَ أَنْوَاعٌ أَرْبَعَةٌ: فَرْضٌ: وَهُوَ كَسْبُ أَقَلِّ الْكِفَايَةِ لِنَفْسِهِ، وَعِيَالِهِ، وَقَضَاءِ دَيْنِهِ."]]},{"id":"tu61_2","label":"كِتَابُ الْكَسْبِ وَالْأَدَبِ · ٢","segs":[["matn","وَمُسْتَحَبٌّ: وَهُوَ كَسْبُ الزَّائِدِ عَلَى أَقَلِّ الْكِفَايَةِ؛ لِيُوَاسِيَ بِهِ فَقِيرًا، أَوْ يَصِلَ بِهِ قَرِيبًا، وَهُوَ أَفْضَلُ مِنْ نَفْلِ الْعِبَادَةِ وَمُبَاحٌ: وَهُوَ كَسْبُ الزَّائِدِ عَلَى ذَلِكَ؛ لِلتَّنَعُّمِ، وَالتَّجَمُّلِ."]]},{"id":"tu61_3","label":"كِتَابُ الْكَسْبِ وَالْأَدَبِ · ٣","segs":[["matn","وَحَرَامٌ: وَهُوَ كَسْبُ مَا أَمْكَنَ، لِلتَّفَاخُرِ، وَالتَّكَاثُرِ، وَإِنْ كَانَ مِنْ حِلٍّ. وَأَفْضَلُ الْكَسْبِ: الْجِهَادُ، ثُمَّ التِّجَارَةُ، ثُمَّ الزِّرَاعَةُ، ثُمَّ الصِّنَاعَةُ."]]},{"id":"tu61_4","label":"كِتَابُ الْكَسْبِ وَالْأَدَبِ · ٤","segs":[["matn","وَالْعِلْمُ أَيْضًا أَنْوَاعٌ أَرْبَعَةٌ: فَرْضٌ: وَهُوَ تَعَلُّمُ مَا يُحْتَاجُ إِلَيْهِ لِأَدَاءِ الْفَرَائِضِ، وَمَعْرِفَةِ الْحَلَالِ وَالْحَرَامِ فِي أَحْوَالِ نَفْسِهِ."]]},{"id":"tu61_5","label":"كِتَابُ الْكَسْبِ وَالْأَدَبِ · ٥","segs":[["matn","وَمُسْتَحَبٌّ: وَهُوَ تَعَلُّمُ الزَّائِدِ عَلَى مَا يُحْتَاجُ إِلَيْهِ؛ لِيُعَلِّمَهُ مَنْ يَحْتَاجُ إِلَيْهِ، وَهُوَ أَفْضَلُ مِنْ نَفْلِ الْعِبَادَةِ. وَمُبَاحٌ: وَهُوَ تَعَلُّمُ الزَّائِدِ عَلَى ذَلِكَ؛ لِلزِّينَةِ، وَالْكَمَالِ."]]},{"id":"tu61_6","label":"كِتَابُ الْكَسْبِ وَالْأَدَبِ · ٦","segs":[["matn","وَحَرَامٌ: وَهُوَ التَّعَلُّمُ؛ لِيُبَاهِيَ بِهِ الْعُلَمَاءَ، وَيُمَارِيَ بِهِ السُّفَهَاءَ. وَيَجِبُ عَلَى الْعَالِمِ تَعْلِيمُ غَيْرِهِ إِذَا طُلِبَ مِنْهُ إِلَى أَنْ يَبْلُغَ. إِلَى الْمَرْتَبَةِ الْأُولَى."]]},{"id":"tu61_7","label":"كِتَابُ الْكَسْبِ وَالْأَدَبِ · ٧","segs":[["matn","وَلَا يَجِبُ عَلَى الْعَالِمِ أَنْ يُجِيبَ عَنْ كُلِّ مَا يُسْأَلُ عَنْهُ، إِلَّا إِذَا عَلِمَ أَنَّ مَا يُسْأَلُ عَنْهُ لَا يُعَلِّمُهُ غَيْرُهُ."]]},{"id":"tu61_8","label":"كِتَابُ الْكَسْبِ وَالْأَدَبِ · ٨","segs":[["matn","وَلَوْ طَلَبَ كَافِرٌ مِنْ مُسْلِمٍ أَنْ يُعَلِّمَهُ الْقُرْآنَ، أَوِ الْفِقْهَ، فَلَا بَأْسَ بِهِ؛ رَجَاءَ أَنْ يَطَّلِعَ عَلَى مَحَاسِنِهِ فَيُسْلِمَ."]]}],"group":"كِتَابُ الْكَسْبِ وَالْأَدَبِ"},{"id":"tu62","title":"فَصْلٌ","units":[{"id":"tu62_1","label":"فَصْلٌ · ١","segs":[["matn","وَالْأَكْلُ عَلَى ثَلَاثِ مَرَاتِبَ: فَرْضٌ: وَهُوَ قَدْرُ مَا يَنْدَفِعُ بِهِ الْهَلَاكُ، وَيُمْكِنُ مَعَهُ الصَّلَاةُ قَائِمًا. وَمُبَاحٌ: وَهُوَ أَدْنَى الشِّبَعِ، بِنِيَّةِ أَنْ يَتَقَوَّى بِهِ عَلَى الْعِبَادَةِ، وَيُحَاسَبُ فِيهِ حِسَابًا يَسِيرًا، إِنْ كَانَ مِنْ حِلٍّ."]]},{"id":"tu62_2","label":"فَصْلٌ · ٢","segs":[["matn","وَحَرَامٌ: وَهُوَ مَا زَادَ عَلَى ذَلِكَ، إِلَّا لِلصَّوْمِ فِي غَدٍ، أَوْ لِمُوَافَقَةِ الضَّيْفِ. وَلَا تَحِلُّ الرِّيَاضَةُ بِتَقْلِيلِ الْأَكْلِ، إِلَى أَنْ يَضْعُفَ عَنْ أَدَاءِ الْعِبَادَاتِ، وَلَوْ وَاصَلَ أَرْبَعِينَ يَوْمًا فَمَاتَ، مَاتَ عَاصِيًا."]]},{"id":"tu62_3","label":"فَصْلٌ · ٣","segs":[["matn","وَلَوْ مَرِضَ، فَتَرَكَ الْمُعَالَجَةَ، تَوَكُّلًا عَلَى اللَّهِ فَمَاتَ لَمْ يَمُتْ عَاصِيًا. وَالتَّنَعُّمُ بِأَنْوَاعِ الْفَاكِهَةِ، مُبَاحٌ، وَتَرْكُهُ أَفْضَلُ. وَالْجَمْعُ بَيْنَ أَنْوَاعِ الْأَطْعِمَةِ حَرَامٌ."]]},{"id":"tu62_4","label":"فَصْلٌ · ٤","segs":[["matn","وَكَذَا وَضْعُ الْخُبْزِ عَلَى الْمَائِدَةِ، أَضْعَافَ مَا يَحْتَاجُ إِلَيْهِ الْآكِلُونَ، وَكَذَا رَفْعُ الْخُبْزِ عَلَى الْخِوَانِ، وَوَضْعُهُ تَحْتَ الْقَصْعَةِ، لِتَعْتَدِلَ."]]},{"id":"tu62_5","label":"فَصْلٌ · ٥","segs":[["matn","وَمَسْحُ الْأَصَابِعِ وَالسِّكِّينِ بِالْخُبْزِ وَوَضْعُ الْمِمْلَحَةِ عَلَيْهِ، وَأَكْلُ وَجْهِهِ خَاصَّةً، وَمِنْ سُنَنِ الْأَكْلِ: غَسْلُ الْيَدَيْنِ قَبْلَهُ، وَبَعْدَهُ، وَالتَّسْمِيَةُ قَبْلَهُ، وَالشُّكْرُ بَعْدَهُ."]]},{"id":"tu62_6","label":"فَصْلٌ · ٦","segs":[["matn","وَمَنِ اشْتَدَّ جُوعُهُ، وَعَجَزَ عَنْ كَسْبِ قُوتِهِ، يَجِبُ عَلَى كُلِّ مَنْ عَلِمَ بِحَالِهِ إِطْعَامُهُ، وَإِنْ لَمْ يَعْلَمْ بِهِ أَحَدٌ، يَجِبُ عَلَيْهِ أَنْ يَسْأَلَ، وَيُعْلِمَ بِحَالِهِ، فَإِنْ لَمْ يَفْعَلْ حَتَّى مَاتَ كَانَ قَاتِلَ نَفْسِهِ."]]},{"id":"tu62_7","label":"فَصْلٌ · ٧","segs":[["matn","وَمَنْ لَهُ قُوتُ يَوْمٍ، لَا يَحِلُّ لَهُ السُّؤَالُ، وَيُبَاحُ لَهُ الْأَخْذُ. وَالسَّائِلُ فِي الْمَسْجِدِ، قِيلَ: يَحْرُمُ إِعْطَاؤُهُ."]]},{"id":"tu62_8","label":"فَصْلٌ · ٨","segs":[["matn","وَالْمُخْتَارُ: أَنَّهُ إِنْ كَانَ لَا يَتَخَطَّى رِقَابَ النَّاسِ، وَلَا يَمُرُّ بَيْنَ يَدَيِ الْمُصَلِّي، وَلَا يَسْأَلُ النَّاسَ إِلْحَافًا، يُبَاحُ إِعْطَاؤُهُ. وَإِنْ كَانَ يَفْعَلُ وَاحِدًا مِنْ هَذِهِ الثَّلَاثَةِ، يَحْرُمُ إِعْطَاؤُهُ."]]},{"id":"tu62_9","label":"فَصْلٌ · ٩","segs":[["matn","وَالْمُعْطِي لِلصَّدَقَةِ، أَفْضَلُ مِنْ آخِذِهَا، وَيَدُهُ هِيَ الْعُلْيَا. وَالْفَقِيرُ الصَّابِرُ، أَفْضَلُ مِنَ الْغَنِيِّ الشَّاكِرِ، وَقِيلَ: عَلَى الْعَكْسِ، وَالْأَوَّلُ عِنْدِي: أَصَحُّ."]]},{"id":"tu62_10","label":"فَصْلٌ · ١٠","segs":[["matn","وَاخْتَلَفَتِ الصَّحَابَةُ رَضِيَ اللَّهُ عَنْهُمْ، فِي جَوَازِ قَبُولِ هَدِيَّةِ الْأُمَرَاءِ الظَّلَمَةِ، وَأَكْلِ طَعَامِهِمْ. وَالْمُخْتَارُ: أَنَّهُ إِنْ كَانَ أَكْثَرُ مَالِهِ حَلَالًا حَلَّ قَبُولُ هَدِيَّتِهِ، وَأَكْلُ طَعَامِهِ، وَإِلَّا حَرُمَ."]]},{"id":"tu62_11","label":"فَصْلٌ · ١١","segs":[["matn","وَطَعَامُ الْوِلَادَةِ، وَالْعَقِيقَةِ، وَالْخِتَانِ، وَقُدُومِ الْمُسَافِرِ، وَالْمَوْتِ، لَيْسَ بِسُنَّةٍ. وَطَعَامُ الْعُرْسِ سُنَّةٌ. وَتُكْرَهُ الضِّيَافَةُ بَعْدَ الثَّلَاثِ فِي الْمَوْتِ. وَيُكْرَهُ رَفْعُ الزَّلَّةِ، إِلَّا بِإِذْنِ الْمُضِيفِ."]]},{"id":"tu62_12","label":"فَصْلٌ · ١٢","segs":[["matn","وَيَحِلُّ لِلضَّيْفِ فِي الْأَصَحِّ أَنْ يُطْعِمَ ضَيْفًا آخَرَ، وَأَنْ يُطْعِمَ الْخَادِمَ الْوَاقِفَ عَلَى الْمَائِدَةِ، وَلَا يَحِلُّ لَهُ أَنْ يُعْطِيَ سَائِلًا، أَوْ دَاخِلًا لِحَاجَتِهِ، أَوْ كَلْبًا، أَوْ هِرَّةً لِلْمُضِيفِ."]]},{"id":"tu62_13","label":"فَصْلٌ · ١٣","segs":[["matn","فَإِنْ أَطْعَمَ الْكَلْبَ، أَوِ الْهِرَّةَ، خُبْزًا مُحْتَرِقًا، أَوْ فُتَاتَ الْمَائِدَةِ، حَلَّ ذَلِكَ."]]}],"group":"كِتَابُ الْكَسْبِ وَالْأَدَبِ"},{"id":"tu63","title":"فَصْلٌ","units":[{"id":"tu63_1","label":"فَصْلٌ · ١","segs":[["matn","وَاللُّبْسُ عَلَى ثَلَاثِ مَرَاتِبَ: فَرْضٌ: وَهُوَ قَدْرُ مَا يَسْتُرُ بَدَنَهُ، وَيَدْفَعُ عَنْهُ ضَرَرَ الْحَرِّ، وَالْبَرْدِ، مِنْ وَسَطِ ثِيَابِ الْقُطْنِ، أَوِ الْكَتَّانِ."]]},{"id":"tu63_2","label":"فَصْلٌ · ٢","segs":[["matn","وَالْقُطْنُ عِنْدِي أَفْضَلُ. وَمُسْتَحَبٌّ: وَهُوَ لُبْسُ الثِّيَابِ الْجَمِيلَةِ، لِلتَّجَمُّلِ، وَالتَّزَيُّنِ، وَإِظْهَارِ نِعْمَةِ اللَّهِ تَعَالَى."]]},{"id":"tu63_3","label":"فَصْلٌ · ٣","segs":[["matn","وَحَرَامٌ: وَهُوَ لُبْسُهَا لِلتَّكَبُّرِ، وَالْخُيَلَاءِ. وَلُبْسُ الثَّوْبِ الْأَحْمَرِ، وَالْمُعَصْفَرِ، حَرَامٌ. وَأَفْضَلُ الثِّيَابِ الْبِيضُ. وَيُسْتَحَبُّ إِرْخَاءُ طَرَفِ الْعِمَامَةِ بَيْنَ الْكَتِفَيْنِ، إِلَى وَسَطِ الظَّهْرِ."]]},{"id":"tu63_4","label":"فَصْلٌ · ٤","segs":[["matn","وَقِيلَ: مِقْدَارَ شِبْرٍ، وَقِيلَ: إِلَى مَوْضِعِ الْجُلُوسِ. وَيَحْرُمُ إِرْخَاءُ السُّتُورِ فِي الْبُيُوتِ، وَسَتْرُ حِيطَانِهَا بِاللُّبُودِ، وَنَحْوِهَا؛ لِلزِّينَةِ، وَالتَّكَبُّرِ، وَيَحِلُّ لِدَفْعِ الْبَرْدِ."]]}],"group":"كِتَابُ الْكَسْبِ وَالْأَدَبِ"},{"id":"tu64","title":"فَصْلٌ","units":[{"id":"tu64_1","label":"فَصْلٌ · ١","segs":[["matn","وَالْكَلَامُ عَلَى ثَلَاثِ مَرَاتِبَ: مُسْتَحَبٌّ: كَالتَّسْبِيحِ، وَالتَّحْمِيدِ، وَالتَّكْبِيرِ، وَالتَّهْلِيلِ، وَالصَّلَاةِ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْوِ ذَلِكَ."]]},{"id":"tu64_2","label":"فَصْلٌ · ٢","segs":[["matn","وَمُبَاحٌ: وَهُوَ قَوْلُ الْإِنْسَانِ لِغَيْرِهِ: تَعَالَ، وَقُمْ، وَاقْعُدْ، وَنَحْوُ ذَلِكَ. وَحَرَامٌ: وَهُوَ الْكَذِبُ، وَالْغِيبَةُ، وَالنَّمِيمَةُ، وَالشَّتِيمَةُ، وَالتَّمَلُّقُ، وَالنِّفَاقُ، وَنَحْوُ ذَلِكَ."]]},{"id":"tu64_3","label":"فَصْلٌ · ٣","segs":[["matn","وَيُسْتَثْنَى مِنَ الْكَذِبِ: الْكَذِبُ فِي الْحَرْبِ لِلْخَدِيعَةِ، وَفِي الصُّلْحِ بَيْنَ اثْنَيْنِ، وَفِي إِرْضَاءِ الرَّجُلِ أَهْلَهُ، وَدَفْعِ ظُلْمِ الظَّالِمِ عَنِ الْمَظْلُومِ."]]},{"id":"tu64_4","label":"فَصْلٌ · ٤","segs":[["matn","فَإِنْ عَرَّضَ بِالْكَذِبِ بِغَيْرِ ضَرُورَةٍ، قِيلَ: يَحْرُمُ، وَقِيلَ: لَا يَحْرُمُ، مِثْلَ أَنْ يُقَالَ لَهُ: كُلْ مَعَنَا، فَيَقُولُ: أَكَلْتُ، وَيَعْنِي بِهِ: بِالْأَمْسِ."]]},{"id":"tu64_5","label":"فَصْلٌ · ٥","segs":[["matn","وَيُسْتَثْنَى مِنَ الْغِيبَةِ: غِيبَةُ الظَّالِمِ عِنْدَ الشَّكْوَى مِنْهُ، وَغِيبَةُ وَاحِدٍ لَا بِعَيْنِهِ مِنْ جَمَاعَةٍ."]]}],"group":"كِتَابُ الْكَسْبِ وَالْأَدَبِ"},{"id":"tu65","title":"فَصْلٌ","units":[{"id":"tu65_1","label":"فَصْلٌ · ١","segs":[["matn","وَيَحْرُمُ التَّسْبِيحُ، وَالتَّكْبِيرُ، وَالصَّلَاةُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ عَمَلٍ مُحَرَّمٍ، أَوْ عَرْضِ سِلْعَةٍ، أَوْ فَتْحِ فُقَّاعٍ، وَنَحْوِهَا، وَلَوْ أَمَرَ الْعَالِمُ بِذَلِكَ أَهْلَ مَجْلِسِهِ، أَوْ أَمَرَ الْغَازِي بِهِ وَقْتَ الْمُبَارَزَةِ، حَلَّ."]]},{"id":"tu65_2","label":"فَصْلٌ · ٢","segs":[["matn","وَالتَّسْبِيحُ فِي مَجْلِسِ الْفِسْقِ بِنِيَّةِ مُخَالَفَتِهِمْ، وَفِي السُّوقِ بِنِيَّةِ تِجَارَةِ الْآخِرَةِ، حَسَنٌ، وَهُوَ أَفْضَلُ مِنَ التَّسْبِيحِ فِي غَيْرِ السُّوقِ. وَالتَّرْجِيعُ فِي قِرَاءَةِ الْقُرْآنِ حَرَامٌ فِي الْمُخْتَارِ، عَلَى الْقَارِئِ، وَالسَّامِعِ."]]},{"id":"tu65_3","label":"فَصْلٌ · ٣","segs":[["matn","وَكَذَا فِي الْأَذَانِ. وَكَرِهَ أَبُو حَنِيفَةَ قِرَاءَةَ الْقُرْآنِ عِنْدَ الْقُبُورِ. وَقَالَ مُحَمَّدٌ رَحِمَهُ اللَّهُ: لَا يُكْرَهُ، وَيَنْتَفِعُ بِهِ الْمَيِّتُ. وَهَذَا هُوَ الْمُخْتَارُ."]]},{"id":"tu65_4","label":"فَصْلٌ · ٤","segs":[["matn","وَيَجِبُ مَنْعُ الصُّوفِيَّةِ الَّذِينَ يَدَّعُونَ الْوَجْدَ، وَالْمَحَبَّةَ عَنْ رَفْعِ الصَّوْتِ، وَتَمْزِيقِ الثِّيَابِ عِنْدَ سَمَاعِ الْغِنَاءِ؛ لِأَنَّ ذَلِكَ حَرَامٌ عِنْدَ سَمَاعِ الْقُرْآنِ، فَكَيْفَ عِنْدَ سَمَاعِ الْغِنَاءِ الَّذِي هُوَ حَرَامٌ؟! خُصُوصًا فِي هَذَا الزَّمَانِ."]]},{"id":"tu65_5","label":"فَصْلٌ · ٥","segs":[["matn","اعْلَمْ أَيُّهَا الْأَخُ الْعَزِيزُ وَفَّقَكَ اللَّهُ تَعَالَى، وَإِيَّانَا لِمَا يُحِبُّهُ وَيَرْضَاهُ: أَنَّ سَعَادَةَ الدُّنْيَا فَانِيَةٌ، وَسَعَادَةَ الْآخِرَةِ بَاقِيَةٌ، قَالَ النَّبِيُّ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ: \"لَوْ كَانَتِ الدُّنْيَا ذَهَبًا يَفْنَى، وَالْآخِرَةُ خَزَفًا يَبْقَى، لَوَجَبَ عَلَى الْعَاقِلِ أَنْ يَخْتَارَ الْآخِرَةَ عَلَى الدُّنْيَا\"."]]},{"id":"tu65_6","label":"فَصْلٌ · ٦","segs":[["matn","وَسَعَادَةُ الْآخِرَةِ، إِنَّمَا تَحْصُلُ بِتَقْوَى اللَّهِ تَعَالَى، وَالتَّقْوَى: اجْتِنَابُ مَحَارِمِهِ، وَهِيَ وَصِيَّةُ اللَّهِ تَعَالَى لِجَمِيعِ الْأُمَمِ، كَمَا قَالَ اللَّهُ تَعَالَى: ﴿وَلَقَدْ وَصَّيْنَا الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ وَإِيَّاكُمْ أَنِ اتَّقُوا اللَّهَ﴾."]]},{"id":"tu65_7","label":"فَصْلٌ · ٧","segs":[["matn","فَعَلَيْكَ أَيُّهَا الْأَخُ بِالتَّقْوَى، وَالِاسْتِعْدَادِ لِلِقَاءِ اللَّهِ عَزَّ وَجَلَّ، وَنَعِيمِ الْآخِرَةِ."]]}],"group":"كِتَابُ الْكَسْبِ وَالْأَدَبِ"}],"basmala":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ","sharh":false};
